# ============================================================================
# LOGGING CONFIGURATION
# ============================================================================

class SessionUUIDAccessLogFormatter(logging.Formatter):
    """Custom formatter that adds session UUID and timestamp to access logs."""
    
    def format(self, record):
        from datetime import datetime
        ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        
        # Check if this is an actual uvicorn access log (has client_addr from uvicorn)
        is_uvicorn_access_log = hasattr(record, 'client_addr') and record.client_addr != 'N/A'
        
        if not is_uvicorn_access_log:
            # For non-access logs, use a simple format with timestamp
            session_uuid = getattr(record, 'session_uuid', None)
            if session_uuid:
                return f"[{ts}] [{session_uuid[:8]}] {record.levelname}: {record.getMessage()}"
            return f"[{ts}] {record.levelname}: {record.getMessage()}"
        
        # For uvicorn access logs, add missing fields
        if not hasattr(record, 'levelprefix'):
            record.levelprefix = ''
        
        if not hasattr(record, 'request_line'):
            record.request_line = 'N/A'
        
        if not hasattr(record, 'status_code'):
            record.status_code = 'N/A'
        
        # Get session UUID from the record if available
        session_uuid = getattr(record, 'session_uuid', None)
        
        if session_uuid:
            record.msg = f"[{ts}] [{session_uuid[:8]}] {record.msg}"
        else:
            record.msg = f"[{ts}] {record.msg}"
        
        return super().format(record)


class StaticFileLogFilter(logging.Filter):
    """Filter out static file and asset requests from access logs."""
    
    STATIC_PREFIXES = ('/static/', '/assets/', '/favicon.ico')
    
    def filter(self, record):
        msg = record.getMessage()
        for prefix in self.STATIC_PREFIXES:
            if prefix in msg:
                return False
        return True


# Configure uvicorn access logger
def setup_logging():
    """Setup custom logging with session UUID support.
    Filters out static file requests to reduce log noise."""
    access_logger = logging.getLogger("uvicorn.access")
    access_logger.addFilter(StaticFileLogFilter())
    
    # Apply custom formatter with timestamps to all handlers
    formatter = SessionUUIDAccessLogFormatter()
    for handler in access_logger.handlers:
        handler.setFormatter(formatter)


# ============================================================================
# LOGGING HELPERS
# ============================================================================

def log(message: str, session_uuid: Optional[str] = None):
    """
    Log a message with timestamp and optional session UUID prefix.
    
    Args:
        message: Message to log
        session_uuid: Optional session UUID to include in log
    """
    from datetime import datetime
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    if session_uuid:
        print(f"[{ts}] [{session_uuid[:8]}] {message}")
    else:
        print(f"[{ts}] {message}")

# ============================================================================
# CUSTOM STATIC FILES WITH CACHING
# ============================================================================

class CachedStaticFiles(StaticFiles):
    """StaticFiles with cache headers for images and assets."""
    
    def file_response(self, *args, **kwargs) -> FileResponse:
        response = super().file_response(*args, **kwargs)
        # Cache images for 1 year (they never change)
        response.headers["Cache-Control"] = "public, max-age=31536000, immutable"
        return response


class ShortCachedStaticFiles(StaticFiles):
    """StaticFiles with per-type cache headers.
    
    - JS: no-store for both browser and CDN (prevents stale modules after deploys)
    - CSS: short browser cache + CDN cache with revalidation
    - SVG/images: long CDN + browser cache (rarely change, served from /static/css or inline)
    """
    
    def file_response(self, *args, **kwargs) -> FileResponse:
        response = super().file_response(*args, **kwargs)
        content_type = response.media_type or ''
        path = str(getattr(response, 'path', ''))
        
        if 'javascript' in content_type:
            # JS must never be cached by CDN — stale modules break the app
            response.headers["Cache-Control"] = "no-store"
            response.headers["CDN-Cache-Control"] = "no-store"
        elif 'svg' in content_type or 'image' in content_type:
            # SVGs and images: cache aggressively (1 day browser, 1 week CDN)
            response.headers["Cache-Control"] = "public, max-age=86400"
            response.headers["CDN-Cache-Control"] = "public, max-age=604800"
        elif 'css' in content_type:
            # CSS: short cache with revalidation (has ?v= cache buster in HTML)
            response.headers["Cache-Control"] = "public, max-age=3600"
            response.headers["CDN-Cache-Control"] = "public, max-age=86400"
        else:
            response.headers["Cache-Control"] = "no-cache"
            response.headers["CDN-Cache-Control"] = "no-store"
        return response

