def _connect_db():
    """Create a SQLite connection with WAL mode and busy timeout.
    
    Use this instead of raw sqlite3.connect(DATABASE_PATH) so every
    connection benefits from WAL (concurrent readers) and a 5-second
    busy timeout (avoids instant 'database is locked' errors).
    """
    conn = sqlite3.connect(DATABASE_PATH, timeout=5)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA busy_timeout=5000")
    return conn


# ============================================================================
# DATA VERSION (for cache busting)
# ============================================================================

def _compute_data_version() -> str:
    """Compute a version string from git commit hash for cache busting.
    Falls back to a timestamp if git is unavailable."""
    import subprocess
    try:
        result = subprocess.run(
            ['git', '-P', 'log', '-1', '--format=%h'],
            capture_output=True, text=True, timeout=5
        )
        if result.returncode == 0 and result.stdout.strip():
            return result.stdout.strip()
    except Exception:
        pass
    # Fallback: use startup timestamp so a restart always busts cache
    from datetime import datetime
    return datetime.now().strftime("%Y%m%d%H%M%S")

DATA_VERSION = _compute_data_version()
print(f"📦 Data version for cache busting: {DATA_VERSION}")


def _maybe_static_304(request: Request, response: Response, etag_prefix: str, max_age: int = 120) -> Optional[Response]:
    """Conditional-GET helper for endpoints whose payload is fully determined
    by DATA_VERSION (i.e. static across all sessions and only changes when
    we redeploy).

    Existing call sites already set `Cache-Control: no-cache` + an ETag, but
    none of them actually honor If-None-Match — so the browser sends the
    ETag back on every request and gets a full 200 every time. For
    `/api/items`, `/api/activities`, `/api/recipes`, `/api/catalog` and
    friends that means hundreds of KB of JSON serialization on every page
    load. On Xavlamin's mobile bug report the four parallel static-data
    fetches alone took ~1052 ms.

    This helper:
      - Computes a quoted ETag of the form `"<prefix>-<DATA_VERSION>"`.
      - If `If-None-Match` matches, returns a `304 Not Modified` response
        the caller should `return` immediately (with no body).
      - Otherwise sets `ETag` + `Cache-Control: public, max-age=N,
        must-revalidate` on the supplied response and returns None so the
        caller continues to build the full 200 payload.

    `max_age` is the time the browser may use the cached response WITHOUT
    revalidating with the server. After that it sends If-None-Match and we
    answer 304 (cheap) when DATA_VERSION matches. 120s is short enough that
    a deploy is reflected within ~2 min for any open tab; after revalidation
    the fast 304 path kicks in.
    """
    etag = f'"{etag_prefix}-{DATA_VERSION}"'
    client_etag = request.headers.get("if-none-match")
    if client_etag == etag:
        # 304 has no body; ETag echoed for clarity, Cache-Control kept short
        # so the browser revalidates again within max_age.
        return Response(
            status_code=304,
            headers={
                "ETag": etag,
                "Cache-Control": f"public, max-age={max_age}, must-revalidate",
            },
        )
    response.headers["ETag"] = etag
    response.headers["Cache-Control"] = f"public, max-age={max_age}, must-revalidate"
    return None

