# Track sheets sync manager instance (initialized lazily)
_sheets_sync_manager = None
_sheets_sync_report = None
_sheets_sync_paused = False


def _get_sheets_sync():
    """Get or create the SheetsSyncManager singleton."""
    global _sheets_sync_manager
    if _sheets_sync_manager is None:
        from ui.sheets_sync import SheetsSyncManager
        _sheets_sync_manager = SheetsSyncManager(get_db())
    return _sheets_sync_manager


async def _sheets_sync_loop():
    """Background task: sync with Google Sheets every 2 minutes."""
    global _sheets_sync_report, _sheets_sync_paused
    import traceback
    import json

    # Wait 10 seconds after startup before first sync
    await asyncio.sleep(10)

    while True:
        try:
            if _sheets_sync_paused:
                await asyncio.sleep(120)
                continue

            # Also check if paused on the sheet side (in case toggled externally)
            try:
                from ui.sheets_config import get_apps_script_url
                import urllib.request, urllib.parse
                webhook_url = get_apps_script_url()
                if webhook_url:
                    params = urllib.parse.urlencode({'action': 'check_paused'})
                    url = f"{webhook_url}?{params}"
                    req = urllib.request.Request(url, headers={'User-Agent': 'WalkscapeSync/1.0'})
                    loop = asyncio.get_event_loop()
                    resp_data = await loop.run_in_executor(
                        None, lambda: json.loads(urllib.request.urlopen(req, timeout=10).read().decode('utf-8'))
                    )
                    if resp_data.get('paused'):
                        _sheets_sync_paused = True
                        log("📊 Sheets sync paused (detected from sheet)")
                        await asyncio.sleep(120)
                        continue
            except Exception:
                pass  # Non-fatal — proceed with sync if check fails

            sync_mgr = _get_sheets_sync()
            # Run sync in a thread to avoid blocking the event loop
            loop = asyncio.get_event_loop()
            report = await loop.run_in_executor(None, sync_mgr.sync)
            _sheets_sync_report = report
            errors = report.get('errors', [])
            if errors:
                log(f"📊 Sheets sync completed with {len(errors)} error(s): {errors[0]}")
            else:
                fetched = report.get('fetched', {})
                total = sum(fetched.values()) if fetched else 0
                log(f"📊 Sheets sync OK — fetched {total} rows from sheet")
        except Exception as e:
            log(f"⚠️  Sheets sync error: {e}")
            _sheets_sync_report = {
                'timestamp': None,
                'errors': [str(e)],
                'traceback': traceback.format_exc(),
            }

        # Wait 2 minutes before next sync
        await asyncio.sleep(120)


# Setup custom logging with session UUID
setup_logging()


@app.on_event("startup")
async def startup_event():
    """Re-apply log filter after uvicorn initializes (needed with --reload)."""
    global _optimization_event_loop
    _optimization_event_loop = asyncio.get_event_loop()
    setup_logging()
    
    # Clean up any stale optimization records from previous runs
    # On server restart (including uvicorn --reload), any running workers are orphaned
    # since the _tail_worker_log thread that monitors them is gone. Clear all records.
    try:
        conn = get_db()._get_connection()
        cursor = conn.cursor()
        cursor.execute("DELETE FROM active_optimizations")
        cleared = cursor.rowcount
        conn.commit()
        if not get_db()._persistent_conn:
            conn.close()
        if cleared:
            print(f"🧹 Cleared {cleared} stale optimization record(s) from previous run")
    except Exception:
        pass  # Table might not exist yet before migrations
    
    # Run pending database migrations on startup
    from pathlib import Path
    from ui.apply_migrations import run_migrations
    ui_dir = Path(__file__).parent
    db_path = str(Path(DATABASE_PATH).resolve())
    migrations_dir = str(ui_dir / "migrations")
    print(f"🔄 Checking migrations (db={db_path}, migrations={migrations_dir})")
    try:
        applied = run_migrations(
            db_path=db_path,
            migrations_dir=migrations_dir
        )
        if applied:
            print(f"🔄 Applied {applied} migration(s) on startup")
    except Exception as e:
        print(f"⚠️  Migration error on startup (non-fatal): {e}")

    # ── Stats Report precompute auto-generate / refresh (2026-06-15) ─────
    # The stats-report stale-detection "item_change" signal diffs a per-scope
    # dominance bitmap built from the precompute tables (item_ids /
    # item_static_dominators / ...). Those tables are normally populated by
    # the scraper hook during data-gen — but a DEPLOYED sessions.db never runs
    # the scraper, so on testing AND prod they were empty. With item_ids empty,
    # get_max_item_id() == 0 and compute_effective_owned_bitmap() returns an
    # empty bitmap for EVERY scope, so item_change has never fired anywhere
    # (only newly_unlocked / version_bump worked). Self-heal here: regenerate
    # when the precompute is empty OR when the catalog has GROWN (new
    # (slug, quality) pairs not yet in item_ids) — e.g. a code deploy shipped
    # new items but the persisted sessions.db's precompute predates them.
    # precompute_is_stale() does a cheap subset check (catalog - item_ids);
    # generation is ~3-10s and idempotent, skipped once current.
    try:
        _pc_conn = get_db()._get_connection()
        _pc_cur = _pc_conn.cursor()
        _pc_cur.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='item_ids'"
        )
        if _pc_cur.fetchone():
            from util.stats_report.precompute import precompute_all, precompute_is_stale
            if precompute_is_stale(_pc_conn):
                _pc_cur.execute("SELECT COUNT(*) FROM item_ids")
                _pc_count = _pc_cur.fetchone()[0]
                _why = "empty" if _pc_count == 0 else "catalog grew"
                print(f"🔧 Stats-report precompute stale ({_why}) — generating now…")
                _pc_res = precompute_all(_pc_conn)
                print(f"🔧 Precompute generated: {_pc_res}")
        if not get_db()._persistent_conn:
            _pc_conn.close()
    except Exception as e:
        print(f"⚠️  Stats-report precompute auto-generate failed (non-fatal): {e}")

    # ── Stats Report orphan-run resume (2026-05-22) ──────────────────────
    # When the container restarts (deploy, OOM, manual reboot), any
    # stats_report_worker subprocesses inside it die with the container.
    # Their stats_report_runs rows are left at status='running' or
    # 'interrupted' (the SIGTERM handler may or may not have flipped it
    # before SIGKILL). Without intervention:
    #   • The frontend polls /status and gets stale `running` forever
    #   • New /run requests are blocked by the existing_run check
    #   • Push notifications never fire because no worker exists to fire them
    # Here we sweep for orphans and respawn workers for them. The worker's
    # --resume mode flips status back to running, forces stale_only=True
    # (skip already-completed jobs via the stats_report_results PK), and
    # honors the original notify_on_complete from the DB row.
    #
    # Caps:
    #   • max_age_hours=24: don't resume runs the user has clearly given up on
    #   • max_resume_count=3: detect runaway respawn loops (worker keeps
    #     crashing on the same job — eventually mark failed permanently)
    #   • Semaphore(3): cap concurrent resumes so one boot doesn't melt
    #     the box if there are many orphans
    try:
        asyncio.create_task(_resume_orphan_stats_report_runs(db_path))
    except Exception as e:
        print(f"⚠️  Could not schedule stats-report orphan resume (non-fatal): {e}")

    # Start Google Sheets sync background task (2-minute interval)
    from ui.sheets_config import SHEETS_SYNC_ENABLED
    if SHEETS_SYNC_ENABLED:
        from ui.sheets_sync import SHEET_SESSION_UUID
        from ui.sheets_config import get_sheet_id, get_apps_script_url
        import os
        print(f"📊 Sheets config: WALKSCAPE_ENV={os.environ.get('WALKSCAPE_ENV', '(not set)')}")
        print(f"📊 Sheets config: sheet_id={get_sheet_id()}")
        print(f"📊 Sheets config: webhook_url={get_apps_script_url()}")
        try:
            if not get_db().get_session(SHEET_SESSION_UUID):
                get_db().create_session(SHEET_SESSION_UUID)
                print(f"📊 Created sheet sync session: {SHEET_SESSION_UUID[:8]}...")
        except Exception as e:
            print(f"⚠️  Could not create sheet sync session (non-fatal): {e}")
        asyncio.create_task(_sheets_sync_loop())
    else:
        print("📊 Sheets sync DISABLED (SHEETS_SYNC_ENABLED = False in sheets_config.py)")


# ── Stats Report graceful shutdown (2026-06-02) ─────────────────────────
# Counterpart to the orphan-resume on startup. When uvicorn receives
# SIGTERM (from `docker stop` during a deploy / `docker compose up
# --force-recreate` / a manual reboot), we want to:
#
#   1. SIGTERM every in-flight stats_report_worker subprocess so it
#      stops launching NEW jobs and finishes whatever job it's
#      currently running. The worker's per-job loop checks
#      get_stats_report_run between jobs (see worker.execute_job's
#      self-terminate check), so once the run row flips to
#      'interrupted' and SIGTERM lands, it'll exit cleanly within
#      ~1 job (~20 s).
#   2. Mark every status='running' run as 'interrupted' so the NEXT
#      container's startup hook picks them up via the existing
#      orphan-resume path. get_orphan_runs already accepts
#      'interrupted', so the resume path Just Works.
#
# This pairs with `stop_grace_period: 30s` on the docker-compose
# definitions — without that, docker SIGKILL's the container 10 s
# after SIGTERM, which is shorter than a typical optimizer job.
#
# Why this matters: the 2026-06-02 oracle crash root cause was that
# a chests_recipes worker holding ~10 GB RSS got abruptly killed
# mid-job via container recreate, the replacement container then
# spun up its own worker (10 GB) before the host had released the
# previous one's pages — total ~20 GB on a 24 GB host with 0 swap +
# no container mem_limit → kernel thrash, sshd unresponsive, manual
# reboot. With graceful shutdown, the old worker is allowed to
# release before the new one allocates.
@app.on_event("shutdown")
async def shutdown_event():
    """Graceful shutdown for stats-report workers.

    Best-effort. All exceptions are caught and logged so a slow
    or unreachable DB doesn't block container exit (uvicorn would
    then time out and SIGKILL anyway, leaving a worse state).
    """
    try:
        killed = _kill_all_stats_report_workers()
        if killed:
            for pid, sess in killed:
                sess_short = (sess[:8] + '…') if sess else '<unknown>'
                print(f"🛑 [stats_report] SIGTERM PID {pid} (session {sess_short}) on shutdown")
            print(f"🛑 [stats_report] Sent SIGTERM to {len(killed)} worker subprocess(es)")
    except Exception as e:
        print(f"⚠️  [stats_report] _kill_all_stats_report_workers failed (non-fatal): {e}")

    try:
        n_interrupted = get_db().mark_running_runs_interrupted()
        if n_interrupted:
            print(f"🛑 [stats_report] Marked {n_interrupted} running run(s) as 'interrupted' "
                  f"— the next container's startup will resume them via _resume_orphan_runs")
    except Exception as e:
        print(f"⚠️  [stats_report] mark_running_runs_interrupted failed (non-fatal): {e}")

    # Give the SIGTERM'd workers a moment to flush their current job
    # to stats_report_results before docker SIGKILLs the container.
    # The bumped stop_grace_period (30s) covers this — we sleep for a
    # subset to leave headroom for uvicorn's own shutdown work.
    try:
        await asyncio.sleep(min(20.0, 25.0))
    except Exception:
        pass


