# ============================================================================
# PROTOTYPE: Client-side optimization (Pyodide hybrid, Option C)
# ----------------------------------------------------------------------------
# Two read-only endpoints that let the standalone benchmark harness at
# /static/pyodide-bench/ run ui.optimize_worker.main() in the browser:
#   1. runtime-bundle.zip : the pure-Python optimizer tree, zipped in-memory
#   2. last-request       : the exact request dict the server last handed the
#                           worker, so the harness benchmarks an identical
#                           real workload (no synthetic input).
# Both are additive and read-only; they do not touch the production optimize
# path beyond a best-effort stash of the request payload.
# ============================================================================
_PROJECT_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
_PYODIDE_LAST_REQUEST_PATH = "/tmp/walkscape_last_optimize_request.json"
_pyodide_bundle_cache: dict = {}  # {'bytes': ..., 'etag': ...}

# Client-side (Pyodide) goals report: jobs + character cached per run_id at
# run-local start so the per-scope ingest can re-derive the matching job (by
# stable identity, since job_id is random per build) + character to write the
# stale-detection row. Bounded by run lifetime; cleared on reset/finish.
_STATS_REPORT_LOCAL_RUNS: dict = {}  # run_id -> {'jobs': [ReportJob], 'character': ..., 'session_uuid': str}


def _find_local_job(jobs, scope):
    """Find the cached ReportJob matching a client-side scope by STABLE identity
    (category + skill + chest + source name) — job_id is random per build so it
    cannot be used for matching."""
    cat = scope.get('category')
    skill = scope.get('skill_name')
    chest = scope.get('chest_name')
    src = scope.get('activity_name')
    for j in jobs:
        j_src = j.activity.name if getattr(j, 'activity', None) else getattr(j, 'recipe_name', None)
        if j.category == cat and j.skill_name == skill and j.chest_name == chest and j_src == src:
            return j
    return None


def _write_local_stale_row(run_id, scope, session_uuid):
    """Background task: write the (heavy) stale-detection row for one client-side
    scope. Re-derives the job (stable identity) + cached character and calls
    _write_stats_report_result_row. Kept OFF the POST critical path because its
    compute_effective_owned_bitmap is CPU-heavy and was the goals-report
    bottleneck. Best-effort — only affects future stale-detection/resume."""
    try:
        cached = _STATS_REPORT_LOCAL_RUNS.get(run_id)
        if not cached or cached.get('session_uuid') != session_uuid:
            return
        job = _find_local_job(cached.get('jobs') or [], scope)
        character = cached.get('character')
        if job is None or character is None:
            return
        from ui.stats_report_worker import _write_stats_report_result_row
        result = {
            'metric_value': scope.get('metric_value'),
            'metric_name': scope.get('metric_name'),
            'gearset_export': scope.get('gearset_export'),
            'metrics_json': scope.get('metrics_json'),
        }
        _write_stats_report_result_row(get_db(), job, character, result)
    except Exception as e:
        try:
            log(f'[stats-report local-scope] deferred stale write skipped: {e}', session_uuid)
        except Exception:
            pass


def _ensure_pyodide_bundle():
    """Build and return (bytes, etag) for the Pyodide runtime bundle. Rebuilds
    whenever any bundled source file changes (max-mtime signature) so a deploy
    reaches local runs immediately — not only on a process restart. The etag is
    a content hash, so it also cache-busts the browser fetch."""
    import hashlib
    sig = _bundle_source_sig()
    if _pyodide_bundle_cache.get("bytes") is None or _pyodide_bundle_cache.get("sig") != sig:
        data = build_bundle_bytes(_PROJECT_ROOT)
        _pyodide_bundle_cache["bytes"] = data
        _pyodide_bundle_cache["etag"] = hashlib.sha256(data).hexdigest()[:16]
        _pyodide_bundle_cache["sig"] = sig
    return _pyodide_bundle_cache["bytes"], _pyodide_bundle_cache["etag"]


def _bundle_source_sig():
    """Max mtime over the bundled source files — cheap freshness signature so
    the bundle rebuilds on any source change without a process restart. Returns
    None on error (falls back to build-once behavior)."""
    try:
        from ui.pyodide_bundle import iter_bundle_members
        mx = 0.0
        for abs_path, _arc in iter_bundle_members(_PROJECT_ROOT):
            try:
                m = os.path.getmtime(abs_path)
                if m > mx:
                    mx = m
            except OSError:
                pass
        return round(mx, 3)
    except Exception:
        return None


@app.get("/api/pyodide/bundle-version")
async def pyodide_bundle_version():
    """Current bundle content version (hash). Tiny + revalidated, so the worker
    can fetch the bundle at a content-addressed ?v=<version> URL and cache that
    immutably — the big asset is downloaded once per version, never re-checked."""
    _, etag = _ensure_pyodide_bundle()
    return Response(
        content=json.dumps({"version": etag}),
        media_type="application/json",
        headers={"Cache-Control": "no-cache"},
    )


@app.get("/api/pyodide/runtime-bundle.zip")
async def pyodide_runtime_bundle(request: Request):
    """Serve the pure-Python optimizer tree as a zip for Pyodide to unpack.

    With a ?v=<version> query param (content-addressed via the bundle hash) the
    response is cached immutably for a year: a changed bundle gets a new version
    -> new URL -> fresh download, otherwise it's served from cache with no
    re-check. Without ?v it falls back to a short revalidated cache.
    """
    data, etag = _ensure_pyodide_bundle()
    versioned = bool(request.query_params.get("v"))
    cache_control = ("public, max-age=31536000, immutable" if versioned
                     else "public, max-age=300")
    return Response(
        content=data,
        media_type="application/zip",
        headers={
            "ETag": etag,
            "Cache-Control": cache_control,
            "Content-Disposition": "attachment; filename=walkscape-optimizer-runtime.zip",
        },
    )


@app.get("/api/pyodide/last-request")
async def pyodide_last_request():
    """Return the most recent worker request payload (for benchmark replay)."""
    try:
        with open(_PYODIDE_LAST_REQUEST_PATH, "r") as fh:
            return Response(content=fh.read(), media_type="application/json")
    except FileNotFoundError:
        return JSONResponse(
            status_code=404,
            content={
                "error": "no_request_captured",
                "hint": "Run one normal optimization first, then retry.",
            },
        )


