@app.get("/", response_class=HTMLResponse)
async def root():
    """Serve the main HTML page with cache-busted JS entry point."""
    with open("ui/static/index.html", "r") as f:
        html = f.read()
    # Inject DATA_VERSION into main.js URL so Cloudflare/CDN never serves stale JS modules
    html = html.replace(
        'src="/static/js/main.js"',
        f'src="/static/js/main.js?v={DATA_VERSION}"'
    )
    # Inject DATA_VERSION into styles.css URL as well — iOS Safari caches CSS
    # aggressively, and the hardcoded "?v=4" never changes between deploys.
    # Replacing it with the build-time version makes every deploy a fresh URL.
    html = html.replace(
        'href="/static/css/styles.css?v=4"',
        f'href="/static/css/styles.css?v={DATA_VERSION}"'
    )
    return HTMLResponse(content=html)

