# ---------------------------------------------------------------------------
# Generic closed-poll page
# ---------------------------------------------------------------------------
# Used by any poll route once the corresponding entry in POLLS_REGISTRY has
# `"closed": True`. To re-open a poll, flip the flag back to False.
#
# To use for a future poll:
#   1. Add `"closed": True` to the poll's entry in POLLS_REGISTRY.
#   2. Optionally set `"closed_message": "..."` to override the default copy.
#   3. The poll's page route should call _render_poll_closed(poll_id) when the
#      registry entry is closed; the vote endpoint should refuse with 410 Gone
#      (see craftingpoll_page / craftingpoll_vote below for the pattern).
# ---------------------------------------------------------------------------

DEFAULT_POLL_CLOSED_MESSAGE = (
    "This poll has been closed. Thanks to everyone who took the time to share "
    "their thoughts — your feedback shaped the next iteration of the optimizer."
)

# Placeholders are {{TITLE}}, {{MESSAGE}}, and {{DATA_VERSION}}. Done with
# .replace() (not f-strings or .format()) so the embedded CSS braces don't
# need escaping.
POLL_CLOSED_HTML_TEMPLATE = """<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{{TITLE}} — Walkscape Optimizer</title>
    <link rel="icon" type="image/svg+xml" href="/assets/icons/favicon.svg">
    <link rel="stylesheet" href="/static/css/styles.css?v={{DATA_VERSION}}">
    <style>
        html, body { height: auto; min-height: 100%; overflow-y: auto; }
        body {
            background: var(--bg-primary, #1a1a1a);
            color: var(--text-primary, #eee);
            margin: 0;
            padding: 0;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
        }
        @media (max-width: 768px) {
            html, body {
                position: static !important;
                overflow-y: auto !important;
                overflow-x: hidden !important;
                height: auto !important;
                min-height: 100% !important;
                width: auto !important;
            }
        }
        .poll-closed-wrap {
            max-width: 480px;
            margin: 0 auto;
            padding: 80px 24px 60px 24px;
            display: flex;
            flex-direction: column;
            gap: 20px;
            align-items: center;
            text-align: center;
        }
        .poll-closed-icon {
            font-size: 56px;
            line-height: 1;
            opacity: 0.85;
        }
        .poll-closed-title {
            font-size: 22px;
            font-weight: 600;
            margin: 0;
            line-height: 1.3;
        }
        .poll-closed-message {
            font-size: 15px;
            color: var(--text-secondary, #aaa);
            margin: 0;
            line-height: 1.55;
        }
        .poll-closed-back {
            display: inline-block;
            margin-top: 12px;
            padding: 10px 20px;
            background: var(--accent-color, #4a7);
            color: var(--button-text, #fff);
            text-decoration: none;
            border-radius: 6px;
            font-size: 14px;
            font-weight: 500;
            border: 1px solid var(--border-color, transparent);
        }
        .poll-closed-back:hover {
            filter: brightness(1.1);
        }
    </style>
</head>
<body>
    <main class="poll-closed-wrap">
        <div class="poll-closed-icon" aria-hidden="true">📪</div>
        <h1 class="poll-closed-title">{{TITLE}}</h1>
        <p class="poll-closed-message">{{MESSAGE}}</p>
        <a href="/" class="poll-closed-back">← Back to optimizer</a>
    </main>
</body>
</html>"""


def _render_poll_closed(poll_id: str, custom_message: Optional[str] = None) -> HTMLResponse:
    """Render the generic 'this poll has been closed' page for any poll.

    Pulls the title from POLLS_REGISTRY[poll_id]['title'] when available,
    falling back to a generic 'Poll' title. Message resolution order:
        1. `custom_message` argument (caller override)
        2. `closed_message` field on the registry entry
        3. DEFAULT_POLL_CLOSED_MESSAGE
    """
    entry = POLLS_REGISTRY.get(poll_id) if 'POLLS_REGISTRY' in globals() else None
    title = (entry or {}).get("title") or "Poll"
    msg = (
        custom_message
        or (entry or {}).get("closed_message")
        or DEFAULT_POLL_CLOSED_MESSAGE
    )
    body = (
        POLL_CLOSED_HTML_TEMPLATE
        .replace("{{TITLE}}", html_lib.escape(title))
        .replace("{{MESSAGE}}", html_lib.escape(msg))
        .replace("{{DATA_VERSION}}", str(DATA_VERSION))
    )
    return HTMLResponse(content=body)


def _is_poll_closed(poll_id: str) -> bool:
    """True iff POLLS_REGISTRY marks the given poll as closed."""
    entry = POLLS_REGISTRY.get(poll_id) if 'POLLS_REGISTRY' in globals() else None
    return bool((entry or {}).get("closed"))


@app.get("/craftingpoll")
async def craftingpoll_page():
    """Serve the crafting optimization redesign poll page.

    Functional mockup of the proposed X-per-Y dropdown UI for crafting
    optimization. Users can try the interface and vote on whether they
    like the redesign.

    When the poll is closed (POLLS_REGISTRY['crafting']['closed'] = True),
    serves the generic 'poll closed' page instead.
    """
    if _is_poll_closed("crafting"):
        return _render_poll_closed("crafting")
    with open("ui/static/craftingpoll.html", "r") as f:
        html = f.read()
    html = html.replace(
        'src="/static/js/craftingpoll.js"',
        f'src="/static/js/craftingpoll.js?v={DATA_VERSION}"'
    )
    html = html.replace(
        'href="/static/css/styles.css?v=4"',
        f'href="/static/css/styles.css?v={DATA_VERSION}"'
    )
    return HTMLResponse(content=html)




