# Reusable structure so future polls just slot in:
#   - /api/admin/polls/list                → list every registered poll
#   - /api/admin/polls/responses/{poll_id} → votes enriched with usage stats
#   - /api/admin/polls/word-frequency/{id} → top words across free-text answers
#
# POLLS_REGISTRY is the one place to declare a new poll. Each entry maps a
# short poll_id to the DB table, display title, and the answer-schema hint
# (which keys are textareas vs radios vs checklists) so the admin UI can
# render sensible aggregates without hardcoding question IDs.
