def _poll_for_id(poll_id: str) -> Dict[str, Any]:
    """Return the registry entry or 404."""
    entry = POLLS_REGISTRY.get(poll_id)
    if not entry:
        raise HTTPException(
            status_code=404,
            detail={"error": True, "code": "POLL_NOT_FOUND", "message": f"Unknown poll: {poll_id}"}
        )
    return entry


def _fetch_poll_rows(table: str) -> List[Tuple[str, Optional[str], str, str, str]]:
    """Fetch all votes for a poll table. Returns list of
    (session_uuid, character_name, answers_json, created_at, updated_at).

    All poll tables share this shape (see crafting_poll_votes schema).
    """
    conn = get_db()._get_connection()
    try:
        cur = conn.cursor()
        cur.execute(
            f"SELECT session_uuid, character_name, answers_json, created_at, updated_at "
            f"FROM {table} ORDER BY updated_at DESC"
        )
        return cur.fetchall()
    finally:
        if not get_db()._persistent_conn:
            conn.close()


def _session_usage_stats(session_uuid: str) -> Dict[str, Any]:
    """Build a small stats bundle for a single session, used to decorate
    every vote row on the admin Polls page.

    Fields:
      - total_api_calls   : row count in api_access_audit for this session
      - first_seen        : earliest timestamp in api_access_audit (proxy for sign-up)
      - last_seen         : latest timestamp in api_access_audit OR sessions.last_updated
      - total_steps       : from character_config.steps
      - character_level   : derived from total_steps
      - owned_item_count  : count of keys in sessions.all_items_raw
      - inventory_value   : from sessions.inventory_value
      - skills            : dict of skill_name -> level (max level summarised separately)
      - top_skill_level   : highest skill level
      - total_skill_levels: sum of all skill levels (lifestyle metric)
    """
    db = get_db()
    session = db.get_session(session_uuid)
    stats: Dict[str, Any] = {
        "total_api_calls": 0,
        "first_seen": None,
        "last_seen": None,
        "total_steps": 0,
        "character_level": None,
        "owned_item_count": 0,
        "inventory_value": 0,
        "skills": {},
        "top_skill_level": None,
        "total_skill_levels": None,
    }

    # API access stats
    conn = db._get_connection()
    try:
        cur = conn.cursor()
        cur.execute(
            "SELECT COUNT(*), MIN(timestamp), MAX(timestamp) "
            "FROM api_access_audit WHERE session_uuid = ?",
            (session_uuid,)
        )
        row = cur.fetchone()
        if row:
            stats["total_api_calls"] = row[0] or 0
            stats["first_seen"] = row[1]
            stats["last_seen"] = row[2]
    finally:
        if not db._persistent_conn:
            conn.close()

    if not session:
        return stats

    # last_seen fallback to sessions.last_updated if no API rows yet
    if not stats["last_seen"]:
        stats["last_seen"] = session.get("last_updated")

    # Inventory value + item count
    stats["inventory_value"] = session.get("inventory_value") or 0
    all_items_raw = session.get("all_items_raw")
    if all_items_raw:
        try:
            parsed = json.loads(all_items_raw) if isinstance(all_items_raw, str) else all_items_raw
            if isinstance(parsed, dict):
                stats["owned_item_count"] = len(parsed)
        except Exception:
            pass

    # Character / skills
    config = session.get("character_config") or {}
    if isinstance(config, dict):
        steps = config.get("steps") or 0
        stats["total_steps"] = steps
        try:
            stats["character_level"] = db._character_level_from_steps(steps)
        except Exception:
            stats["character_level"] = None
        skills = config.get("skills") or {}
        if isinstance(skills, dict) and skills:
            stats["skills"] = skills
            try:
                lvls = [int(v) for v in skills.values() if isinstance(v, (int, float))]
                if lvls:
                    stats["top_skill_level"] = max(lvls)
                    stats["total_skill_levels"] = sum(lvls)
            except Exception:
                pass

    return stats


# Small set of English stop words and poll-jargon filler we don't want
# dominating the "most typed words" aggregation.
_POLL_STOP_WORDS = frozenset([
    "the", "a", "an", "and", "or", "but", "if", "in", "on", "at", "to", "for",
    "of", "is", "it", "that", "this", "be", "was", "were", "been", "have",
    "has", "had", "do", "does", "did", "will", "would", "could", "should",
    "may", "might", "must", "can", "i", "you", "he", "she", "we", "they",
    "me", "him", "her", "us", "them", "my", "your", "our", "their", "as",
    "by", "from", "with", "about", "into", "than", "then", "so", "not",
    "no", "yes", "too", "very", "just", "also", "like", "only", "more",
    "most", "some", "all", "any", "each", "other", "such", "same", "own",
    "over", "under", "up", "down", "out", "off", "again", "here", "there",
    "when", "where", "why", "how", "what", "which", "who", "whom", "whose",
    "am", "are",
])


def _word_frequency(texts: List[str], top_n: int = 40) -> List[Tuple[str, int]]:
    """Count word occurrences across all provided texts, lowercased, with
    stop words filtered. Returns (word, count) sorted by count desc.
    """
    from collections import Counter
    counter: Counter = Counter()
    for text in texts:
        if not text or not isinstance(text, str):
            continue
        # Simple word split: alphanumeric runs, lowercased. 2+ chars only.
        for word in re.findall(r"[a-z][a-z'\-]+", text.lower()):
            if len(word) < 3:
                continue
            if word in _POLL_STOP_WORDS:
                continue
            counter[word] += 1
    return counter.most_common(top_n)








