@app.get("/api/generic-activity-recipe-requirements/diff")
async def generic_activity_recipe_requirements_diff():
    """Return old and new versions of generic-activity-recipe requirements.md for inline diff rendering."""
    import subprocess
    from fastapi.responses import JSONResponse
    try:
        result = subprocess.run(
            ["git", "-P", "show", "HEAD~1:.kiro/specs/generic-activity-recipe/requirements.md"],
            capture_output=True, text=True, cwd="."
        )
        old_content = result.stdout if result.returncode == 0 else ""
        with open(".kiro/specs/generic-activity-recipe/requirements.md", "r") as f:
            new_content = f.read()
        return JSONResponse({
            "old": old_content,
            "new": new_content,
            "has_diff": old_content != new_content
        })
    except Exception as e:
        with open(".kiro/specs/generic-activity-recipe/requirements.md", "r") as f:
            new_content = f.read()
        return JSONResponse({"old": "", "new": new_content, "has_diff": False, "error": str(e)})


