@app.post("/api/sell-for-chips")
async def sell_for_chips(request: Request):
    """
    Project Mysterious Merchant chip earnings + buy preview for a character.

    Body: { "character_uuid": <optional, defaults to current session>,
            "force_overrides": { item_slug: "force_sell" | "force_keep" } }

    Returns a SellPlan (see util/sell_for_chips.compute_sell_plan):
      { "sections": [...], "totals_by_chip": {...} }
    Empty inventory / no imported character returns an empty plan with 200
    (the frontend shows an import CTA), not a 500 (spec Req 7.2).
    """
    from util.sell_for_chips import compute_sell_plan, build_merchant_item_lookup, build_current_chips

    body = await request.json()
    character_uuid = body.get("character_uuid") or request.state.session_uuid

    session = get_db().get_session(character_uuid)
    # Only hard-404 when the caller explicitly named a character that doesn't exist.
    if session is None and body.get("character_uuid"):
        raise HTTPException(status_code=404, detail="Character not found")

    char_config = session.get("character_config") if session else None
    owned_quantities = (char_config or {}).get("owned_quantities") or {}
    if not owned_quantities:
        return JSONResponse({"sections": [], "totals_by_chip": {}, "needs_import": True})

    # Sanitize overrides to the two allowed values.
    raw_overrides = body.get("force_overrides") or {}
    force_overrides = {
        str(slug): val for slug, val in raw_overrides.items()
        if val in ("force_sell", "force_keep")
    }

    item_lookup = build_merchant_item_lookup()
    current_chips = build_current_chips((char_config or {}).get("currencies") or {})
    plan = compute_sell_plan(owned_quantities, item_lookup, force_overrides, current_chips)
    return JSONResponse(plan)




