@app.get("/api/docs/list")
async def docs_list():
    """Return the list of available documents (whitelisted only)."""
    from fastapi.responses import JSONResponse
    import os
    docs = []
    for doc_id, info in ALLOWED_DOCS.items():
        if os.path.exists(info["path"]):
            docs.append({"id": doc_id, "label": info["label"]})
    return JSONResponse({"docs": docs})


@app.get("/api/docs/read/{doc_id}")
async def docs_read(doc_id: str):
    """Read a whitelisted document and return current + previous version for diff."""
    import subprocess
    from fastapi.responses import JSONResponse

    if doc_id not in ALLOWED_DOCS:
        raise HTTPException(status_code=404, detail="Document not found")

    file_path = ALLOWED_DOCS[doc_id]["path"]

    import os
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="Document file not found on disk")

    try:
        result = subprocess.run(
            ["git", "-P", "show", f"HEAD~1:{file_path}"],
            capture_output=True, text=True, cwd="."
        )
        old_content = result.stdout if result.returncode == 0 else ""
        with open(file_path, "r") as f:
            new_content = f.read()
        return JSONResponse({
            "old": old_content,
            "new": new_content,
            "has_diff": old_content != new_content
        })
    except Exception as e:
        with open(file_path, "r") as f:
            new_content = f.read()
        return JSONResponse({"old": "", "new": new_content, "has_diff": False, "error": str(e)})


@app.get("/api/docs/comments/{doc_id}")
async def docs_comments_list(doc_id: str):
    """List all comments for a document."""
    from fastapi.responses import JSONResponse
    if doc_id not in ALLOWED_DOCS:
        raise HTTPException(status_code=404, detail="Document not found")
    conn = get_db()._get_connection()
    cursor = conn.cursor()
    # Ensure table and columns exist (handles old table without new columns)
    cursor.execute("""CREATE TABLE IF NOT EXISTS doc_comments (
        id INTEGER PRIMARY KEY AUTOINCREMENT, doc_id TEXT NOT NULL,
        selected_text TEXT NOT NULL, comment TEXT NOT NULL,
        line_num INTEGER, section TEXT, full_line TEXT,
        created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)""")
    for col in ['line_num INTEGER', 'section TEXT', 'full_line TEXT']:
        try:
            cursor.execute(f"ALTER TABLE doc_comments ADD COLUMN {col}")
        except Exception:
            pass  # Column already exists
    cursor.execute(
        "SELECT id, doc_id, selected_text, comment, line_num, section, full_line, created_at FROM doc_comments WHERE doc_id = ? ORDER BY created_at ASC",
        (doc_id,)
    )
    rows = cursor.fetchall()
    comments = [{"id": r[0], "doc_id": r[1], "selected_text": r[2], "comment": r[3],
                 "line_num": r[4], "section": r[5], "full_line": r[6], "created_at": r[7]} for r in rows]
    return JSONResponse({"comments": comments})


@app.post("/api/docs/comments/{doc_id}")
async def docs_comments_create(doc_id: str, request: Request):
    """Create a comment on a document."""
    from fastapi.responses import JSONResponse
    if doc_id not in ALLOWED_DOCS:
        raise HTTPException(status_code=404, detail="Document not found")
    body = await request.json()
    selected_text = body.get("selected_text", "").strip()
    comment = body.get("comment", "").strip()
    line_num = body.get("line_num")
    section = body.get("section", "")
    full_line = body.get("full_line", "")
    if not selected_text or not comment:
        raise HTTPException(status_code=400, detail="selected_text and comment are required")
    conn = get_db()._get_connection()
    cursor = conn.cursor()
    # Ensure table and columns exist
    cursor.execute("""CREATE TABLE IF NOT EXISTS doc_comments (
        id INTEGER PRIMARY KEY AUTOINCREMENT, doc_id TEXT NOT NULL,
        selected_text TEXT NOT NULL, comment TEXT NOT NULL,
        line_num INTEGER, section TEXT, full_line TEXT,
        created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)""")
    for col in ['line_num INTEGER', 'section TEXT', 'full_line TEXT']:
        try:
            cursor.execute(f"ALTER TABLE doc_comments ADD COLUMN {col}")
        except Exception:
            pass
    cursor.execute(
        "INSERT INTO doc_comments (doc_id, selected_text, comment, line_num, section, full_line, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
        (doc_id, selected_text, comment, line_num, section, full_line, _utc_now())
    )
    conn.commit()
    comment_id = cursor.lastrowid
    return JSONResponse({"id": comment_id, "doc_id": doc_id, "selected_text": selected_text, "comment": comment})


@app.delete("/api/docs/comments/{doc_id}/{comment_id}")
async def docs_comments_delete(doc_id: str, comment_id: int):
    """Delete a comment."""
    from fastapi.responses import JSONResponse
    if doc_id not in ALLOWED_DOCS:
        raise HTTPException(status_code=404, detail="Document not found")
    conn = get_db()._get_connection()
    cursor = conn.cursor()
    cursor.execute("DELETE FROM doc_comments WHERE id = ? AND doc_id = ?", (comment_id, doc_id))
    conn.commit()
    return JSONResponse({"deleted": cursor.rowcount > 0})


@app.patch("/api/docs/comments/{doc_id}/{comment_id}")
async def docs_comments_update(doc_id: str, comment_id: int, request: Request):
    """Update a comment's text."""
    from fastapi.responses import JSONResponse
    if doc_id not in ALLOWED_DOCS:
        raise HTTPException(status_code=404, detail="Document not found")
    body = await request.json()
    comment = body.get("comment", "").strip()
    if not comment:
        raise HTTPException(status_code=400, detail="comment is required")
    conn = get_db()._get_connection()
    cursor = conn.cursor()
    cursor.execute("UPDATE doc_comments SET comment = ? WHERE id = ? AND doc_id = ?", (comment, comment_id, doc_id))
    conn.commit()
    return JSONResponse({"updated": cursor.rowcount > 0})


@app.get("/api/docs/comments/{doc_id}/export")
async def docs_comments_export(doc_id: str):
    """Export all comments for a document as a detailed text file with full context."""
    from fastapi.responses import PlainTextResponse
    if doc_id not in ALLOWED_DOCS:
        raise HTTPException(status_code=404, detail="Document not found")
    label = ALLOWED_DOCS[doc_id]["label"]
    conn = get_db()._get_connection()
    cursor = conn.cursor()
    cursor.execute(
        "SELECT selected_text, comment, line_num, section, full_line, created_at FROM doc_comments WHERE doc_id = ? ORDER BY line_num ASC, created_at ASC",
        (doc_id,)
    )
    rows = cursor.fetchall()
    lines = [f"# Review Comments: {label}", f"# Document ID: {doc_id}", f"# Exported: {_utc_now()}", f"# Total comments: {len(rows)}", ""]
    for i, r in enumerate(rows, 1):
        selected_text, comment, line_num, section, full_line, created_at = r
        lines.append(f"{'='*60}")
        lines.append(f"Comment {i} of {len(rows)}")
        lines.append(f"{'='*60}")
        if section:
            lines.append(f"Section:       {section}")
        if line_num:
            lines.append(f"Line:          {line_num}")
        if full_line:
            lines.append(f"Full line:     {full_line}")
        lines.append(f"Selected text: \"{selected_text}\"")
        lines.append(f"")
        lines.append(f"Comment:       {comment}")
        lines.append(f"")
        lines.append(f"Date:          {created_at}")
        lines.append("")
    if not rows:
        lines.append("(No comments)")
    return PlainTextResponse("\n".join(lines), headers={
        "Content-Disposition": f'attachment; filename="{doc_id}-comments.txt"'
    })


@app.get("/sw.js")
async def service_worker():
    """Serve service worker from root scope (required for PWA installability)."""
    from starlette.responses import FileResponse
    return FileResponse(
        "ui/static/sw.js",
        media_type="application/javascript",
        headers={"Service-Worker-Allowed": "/"}
    )

# ============================================================================
# SESSION API ENDPOINTS
# ============================================================================

@app.get("/api/session/{uuid}", response_model=SessionData)
async def get_session(uuid: str):
    """
    Retrieve or create session data.
    
    If the session UUID doesn't exist, creates a new session automatically.
    
    Args:
        uuid: Session UUID
        
    Returns:
        SessionData with uuid, character_config, ui_config, last_updated
    """
    # Try to get existing session
    session = get_db().get_session(uuid)
    
    # Create new session if doesn't exist
    if not session:
        session = get_db().create_session(uuid)

    # One-time migration: rewrite legacy location ids in ui_config so
    # saved column-3 / travel / gearset-context / crafting-tree
    # selections survive API renames (e.g. blackspell_port →
    # blackspell_harbour on 2026-05-28). Idempotent — once rewritten,
    # subsequent calls are no-ops because the new ids aren't in the
    # legacy-rename map.
    from ui.legacy_location_id_migration import migrate_legacy_location_ids
    ui_config = session.get('ui_config') or {}
    if migrate_legacy_location_ids(ui_config):
        get_db().update_ui_config(uuid, ui_config)
        session['ui_config'] = ui_config
    
    # Build export-name-to-item-id alias map for renamed items
    # This helps the frontend match owned_items (stored as export names) to catalog IDs
    from util.autogenerated.export_names import get_item_mapping
    item_mapping = get_item_mapping()
    export_aliases = {}
    for export_name, item_obj in item_mapping.items():
        if hasattr(item_obj, 'name'):
            canonical_id = item_obj.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
            if export_name != canonical_id:
                export_aliases[export_name] = canonical_id
    
    result = SessionData(**session)
    # Attach export_aliases to the response (for renamed item resolution)
    response_dict = result.model_dump()
    response_dict['export_aliases'] = export_aliases
    return response_dict


@app.post("/api/session/{uuid}/import")
async def import_character(uuid: str, data: ImportData):
    """
    Import character data from game export JSON.
    
    Parses the character export using character_export_util and stores
    the parsed data in the session's character_config.
    
    Args:
        uuid: Session UUID
        data: ImportData with export_json string
        
    Returns:
        Success message with session data
        
    Raises:
        HTTPException: If JSON is invalid or doesn't match expected schema
    """
    try:
        # Parse character export
        character = Character(data.export_json)
        
        # Build character config from parsed data
        # Store both XP and levels for skills
        skill_levels = {}
        skill_xp = {}
        for skill_name, xp in character.skills.items():
            skill_levels[skill_name] = character.get_skill_level(skill_name)
            skill_xp[skill_name] = xp
        
        # Parse item qualities and quantities from inventory + bank + gear
        item_qualities = {}  # item_id -> {quality -> quantity} for crafted items
        item_quantities = {}  # item_id -> quantity for non-crafted items
        item_slots = {}  # item_id -> slot name (tracked during parsing to avoid re-lookups)
        item_has_slot = {}  # export_name -> bool (True if equipment/tool, for owned_items filtering)
        item_has_duration = {}  # export_name -> bool (True if consumable)
        
        # Combine all sources: inventory, bank, and equipped gear
        # NOTE: Can't use {**a, **b} because it overwrites duplicate keys!
        # If an item is in both inventory and bank, we need to SUM the quantities.
        all_items_raw = dict(character._inventory_raw)
        for export_name, quantity in character._bank_raw.items():
            all_items_raw[export_name] = all_items_raw.get(export_name, 0) + quantity
        
        # Add gear items (each equipped item counts as quantity 1)
        for slot, export_name in character._gear_raw.items():
            if export_name:
                all_items_raw[export_name] = all_items_raw.get(export_name, 0) + 1
        
        # Import the function to get items from export names
        from util.autogenerated.export_names import get_item_from_export_name
        
        log(f"Processing {len(all_items_raw)} items for quality/quantity parsing (inventory + bank + gear)...", uuid)
        
        # Map rarity suffixes to quality names
        rarity_to_quality = {
            'common': 'Normal',
            'uncommon': 'Good',
            'rare': 'Great',
            'epic': 'Excellent',
            'legendary': 'Perfect',
            'ethereal': 'Eternal'
        }
        
        log(f"=== BACKEND: PARSING ITEMS ===", uuid)
        
        for export_name, quantity in all_items_raw.items():
            quality = None
            base_export_name = export_name
            
            # Check for rarity suffix (e.g., "silver_opal_ring_common")
            for rarity_suffix, quality_name in rarity_to_quality.items():
                if export_name.endswith(f'_{rarity_suffix}'):
                    base_export_name = export_name[:-len(f'_{rarity_suffix}')]
                    quality = quality_name
                    log(f"  Found rarity suffix: {export_name} -> base={base_export_name}, quality={quality}", uuid)
                    break
            
            # Also check for quality in parentheses (e.g., "Gold Ruby Ring (Great)")
            if not quality and '(' in export_name and ')' in export_name:
                parts = export_name.rsplit('(', 1)
                if len(parts) == 2:
                    base_export_name = parts[0].strip()
                    quality_part = parts[1].rstrip(')')
                    
                    # Check if it's a quality name
                    valid_qualities = ['Normal', 'Good', 'Great', 'Excellent', 'Perfect', 'Eternal']
                    if quality_part in valid_qualities:
                        quality = quality_part
            
            # Get item from base export name (without quality suffix)
            item = get_item_from_export_name(base_export_name)
            
            if item:
                # Get item ID using the same logic as catalog._name_to_id
                # Convert: lowercase, spaces to underscores, remove parentheses, hyphens to underscores, remove apostrophes
                item_id = item.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
                
                # Track slot and type info for later filtering
                if hasattr(item, 'slot'):
                    item_slots[item_id] = item.slot
                    item_has_slot[export_name] = True
                else:
                    item_has_slot[export_name] = False
                item_has_duration[export_name] = hasattr(item, 'duration')
                
                if quality:
                    # Crafted item with quality
                    log(f"  ✓ Crafted: {export_name} -> {item.name} -> {item_id} (quality: {quality}, qty: {quantity})", uuid)
                    
                    # Store quality and quantity - GROUP BY ITEM_ID
                    if item_id not in item_qualities:
                        item_qualities[item_id] = {}
                    
                    # Add this quality's quantity to the item
                    if quality not in item_qualities[item_id]:
                        item_qualities[item_id][quality] = 0
                    item_qualities[item_id][quality] += quantity
                else:
                    # Non-crafted item - just track total quantity
                    log(f"  ✓ Non-crafted: {export_name} -> {item.name} -> {item_id} (qty: {quantity})", uuid)
                    
                    if item_id not in item_quantities:
                        item_quantities[item_id] = 0
                    item_quantities[item_id] += quantity
            else:
                if quality:  # Only log if we found a quality but couldn't find the item
                    log(f"  ✗ Could not find item for: {export_name} (base: {base_export_name}, quality: {quality})", uuid)
        
        log(f"=== BACKEND: FINAL RESULTS ===", uuid)
        log(f"item_qualities: {json.dumps(item_qualities, indent=2)}", uuid)
        log(f"item_quantities: {json.dumps(item_quantities, indent=2)}", uuid)
        log(f"=== END BACKEND PARSING ===", uuid)

        # Simplify item_qualities: ONLY keep rings (they need ring1/ring2 quality tracking)
        # Non-ring crafted items don't need item_qualities - their quality is determined
        # from owned_items (which includes the quality suffix)
        simplified_qualities = {}
        quality_hierarchy = ['Eternal', 'Perfect', 'Excellent', 'Great', 'Good', 'Normal']
        # Reverse mapping: quality name -> rarity suffix (e.g., 'Excellent' -> 'epic')
        quality_to_rarity = {v: k for k, v in rarity_to_quality.items()}
        
        # Detect which items are rings using slot info tracked during parsing
        ring_item_ids = set()
        for item_id in item_qualities.keys():
            if item_slots.get(item_id) == 'ring':
                ring_item_ids.add(item_id)
        
        # Build simplified_qualities (rings only) and selected quality suffixes per item
        selected_qualities_by_id = {}  # item_id -> set of rarity suffixes like {'_epic', '_uncommon'}
        
        for item_id, qualities_obj in item_qualities.items():
            sorted_quals = sorted(
                qualities_obj.keys(),
                key=lambda q: quality_hierarchy.index(q) if q in quality_hierarchy else 999
            )
            if not sorted_quals:
                continue
            
            highest = sorted_quals[0]
            highest_qty = qualities_obj[highest]
            
            if item_id in ring_item_ids:
                # Ring: keep top 2 qualities in item_qualities
                simplified = {}
                suffixes = set()
                if highest_qty >= 2:
                    simplified[highest] = 2
                    suffixes.add(f"_{quality_to_rarity[highest]}")
                else:
                    simplified[highest] = 1
                    suffixes.add(f"_{quality_to_rarity[highest]}")
                    if len(sorted_quals) > 1:
                        simplified[sorted_quals[1]] = 1
                        suffixes.add(f"_{quality_to_rarity[sorted_quals[1]]}")
                simplified_qualities[item_id] = simplified
                selected_qualities_by_id[item_id] = suffixes
            else:
                # Non-ring: only track the selected suffix for owned_items filtering
                selected_qualities_by_id[item_id] = {f"_{quality_to_rarity[highest]}"}
        
        # Simplify item_quantities: only keep non-crafted rings with qty >= 2
        simplified_quantities = {}
        for item_id, qty in item_quantities.items():
            if qty >= 2 and item_slots.get(item_id) == 'ring':
                simplified_quantities[item_id] = min(qty, 2)

        # Build owned_quantities: total quantity per item_id (across all qualities),
        # used by the recipe info section to mark recipe materials as
        # have-enough (green) / have-not-enough (red) and to display "(N owned)"
        # in the source dropdown nav label. Includes everything in inventory + bank
        # + gear so materials, consumables, and equipment all show counts.
        owned_quantities = {}
        for item_id, qty in item_quantities.items():
            owned_quantities[item_id] = owned_quantities.get(item_id, 0) + qty
        for item_id, qualities_obj in item_qualities.items():
            owned_quantities[item_id] = owned_quantities.get(item_id, 0) + sum(qualities_obj.values())
        
        # Build owned_items: only equipment, tools, and consumables at the selected quality
        # Skip materials, fine variants, and non-selected quality variants
        owned_items_simplified = set()
        
        all_export_names = set(
            list(character._inventory_raw.keys()) + 
            list(character._bank_raw.keys()) +
            [export_name for export_name in character._gear_raw.values() if export_name]
        )
        
        for export_name in all_export_names:
            # Check if this is a crafted item with a quality suffix
            base_name = export_name
            found_suffix = None
            for rarity_suffix in rarity_to_quality.keys():
                if export_name.endswith(f'_{rarity_suffix}'):
                    base_name = export_name[:-len(f'_{rarity_suffix}')]
                    found_suffix = f'_{rarity_suffix}'
                    break
            
            if found_suffix:
                # Crafted item - only include if this is a selected quality
                # Look up item_id from the base export name using tracked data
                item_id = None
                for tracked_id, slot in item_slots.items():
                    # Match by checking if base_name corresponds to this item_id
                    if base_name == tracked_id or base_name.replace('_', ' ').replace("'", '') == tracked_id.replace('_', ' '):
                        item_id = tracked_id
                        break
                
                # Fallback: resolve via get_item_from_export_name (already imported)
                if item_id is None:
                    item = get_item_from_export_name(base_name)
                    if item and hasattr(item, 'name'):
                        item_id = item.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
                
                if item_id and item_id in selected_qualities_by_id:
                    if found_suffix in selected_qualities_by_id[item_id]:
                        # Store with canonical item_id + suffix (handles renamed items)
                        owned_items_simplified.add(item_id + found_suffix)
            else:
                # Non-crafted item - include equipment, tools, consumables, and materials
                if item_has_slot.get(export_name, False):
                    # Resolve export name to canonical item_id (handles renamed items)
                    resolved_item = get_item_from_export_name(export_name)
                    if resolved_item and hasattr(resolved_item, 'name'):
                        canonical_id = resolved_item.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
                        owned_items_simplified.add(canonical_id)
                    else:
                        owned_items_simplified.add(export_name)
                elif item_has_duration.get(export_name, False):
                    # Resolve consumable export names too
                    resolved_item = get_item_from_export_name(export_name)
                    if resolved_item and hasattr(resolved_item, 'name'):
                        canonical_id = resolved_item.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
                        owned_items_simplified.add(canonical_id)
                    else:
                        owned_items_simplified.add(export_name)
                else:
                    # Check if it's a material (no slot, no duration)
                    resolved_item = get_item_from_export_name(export_name, item_type="material")
                    if resolved_item and hasattr(resolved_item, 'name'):
                        canonical_id = resolved_item.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
                        owned_items_simplified.add(canonical_id)
                        # Also add fine variant if present in inventory
                        if export_name + '_fine' in all_export_names or export_name.endswith('_fine'):
                            owned_items_simplified.add(export_name)

        character_config = {
            "name": character.name,
            "game_version": character.game_version,
            "steps": character.steps,
            "achievement_points": character.achievement_points,
            "total_skill_level": character.get_total_skill_level(),
            "coins": character.coins,
            "skills": skill_levels,  # Store levels for display
            "skills_xp": skill_xp,  # Store XP for progress calculation
            "reputation": character.reputation,
            # Store only equipment, tools, consumables at selected quality
            "owned_items": list(owned_items_simplified),
            # Raw export names from inventory+bank+gear (for generic item matching)
            "raw_export_names": list(all_export_names),
            "collectibles": character._collectibles_raw,
            # Pets from game export — parsed with species, level, xp, stage, abilities
            "pets": character.pets,
            # Store ring qualities only (non-rings don't need this)
            "item_qualities": simplified_qualities,
            "item_quantities": simplified_quantities,
            # Total quantity per item_id (materials, consumables, equipment).
            # Used by the recipe info section's have-enough / have-not-enough
            # outline coloring and the "(N owned)" source-nav label.
            "owned_quantities": owned_quantities,
            # Currencies the player holds (chips/tokens), raw from the export
            # ({ "<Currency name>": qty }). Used by Sell for Chips to show
            # current chip balances.
            "currencies": character._currencies_raw,
        }
        
        # Compute inventory value: coins + (value × quantity) for ALL items in inventory+bank+gear
        inventory_value = character.coins or 0
        for export_name, quantity in all_items_raw.items():
            try:
                item = get_item_from_export_name(export_name)
                if item and hasattr(item, 'value') and item.value:
                    inventory_value += item.value * quantity
            except Exception:
                pass

        # Ensure session exists
        session = get_db().get_session(uuid)
        if not session:
            session = get_db().create_session(uuid)
        
        # Update character config
        get_db().update_character_config(uuid, character_config)
        
        # Update inventory value
        get_db().update_inventory_value(uuid, inventory_value)
        
        # Store full inventory with quantities (backend-only column)
        get_db().update_all_items_raw(uuid, all_items_raw)
        
        # Invalidate stats report results if inventory changed
        try:
            get_db().mark_stats_report_runs_stale(uuid)
        except Exception:
            pass  # Non-critical — don't fail the import if this errors
        
        # Get updated session
        session = get_db().get_session(uuid)
        
        return {
            "success": True,
            "message": "Character data imported successfully",
            "session": SessionData(**session)
        }
        
    except json.JSONDecodeError as e:
        raise HTTPException(
            status_code=400,
            detail={
                "error": True,
                "code": "INVALID_JSON",
                "message": "The provided JSON is not valid",
                "details": str(e)
            }
        )
    except Exception as e:
        raise HTTPException(
            status_code=400,
            detail={
                "error": True,
                "code": "INVALID_EXPORT",
                "message": "Valid JSON but doesn't match character export schema",
                "details": str(e)
            }
        )


@app.get("/api/session/{uuid}/export")
async def export_character_config(uuid: str):
    """
    Export character config in the same JSON format as the game export.
    
    Reconstructs the original game export structure from stored data so
    the user can re-import it later or share it.
    
    Args:
        uuid: Session UUID
        
    Returns:
        JSON matching the game's character export format
    """
    session = get_db().get_session(uuid)
    if not session or not session.get('character_config'):
        raise HTTPException(
            status_code=404,
            detail={"error": True, "code": "NO_CHARACTER", "message": "No character data found for this session"}
        )
    
    config = session['character_config']
    
    # Reconstruct the game export format
    # Skills: stored as skills_xp {name: xp} — this IS the original format
    skills = config.get('skills_xp', {})
    
    # If skills_xp is missing (old sessions), try to reverse from levels (lossy)
    if not skills:
        skill_levels = config.get('skills', {})
        if skill_levels:
            from util.walkscape_constants import level_to_xp
            skills = {name: level_to_xp(level) for name, level in skill_levels.items()}
    
    # all_items_raw has the merged inventory+bank+gear as {export_name: quantity}
    # We can't perfectly split back into inventory/bank/gear, so put everything in inventory
    all_items_json = session.get('all_items_raw')
    inventory = {}
    if all_items_json:
        try:
            inventory = json.loads(all_items_json) if isinstance(all_items_json, str) else all_items_json
        except (json.JSONDecodeError, TypeError):
            pass

    # Fallback for sessions captured without all_items_raw (e.g. snapshots
    # created before the snapshot copy fix). owned_items is a list of export
    # names with no quantities, so export each at quantity 1 — better than an
    # empty inventory, which dropped all owned items from the export.
    if not inventory:
        owned_items = config.get('owned_items') or []
        inventory = {name: 1 for name in owned_items if name}

    # Reconstruct pets in game export format:
    # "pets": {"pet": {active_pet}}, "available_pets": [...], "available_eggs": [...]
    stored_pets = config.get("pets", [])
    active_pet = None
    available_pets = []
    available_eggs = []
    # Strip abilities/variant/active — those are our enrichments, not in the game export
    export_pet_keys = {'name', 'species', 'level', 'xp', 'stage'}
    for pet in stored_pets:
        if not isinstance(pet, dict):
            continue
        clean_pet = {k: v for k, v in pet.items() if k in export_pet_keys}
        if pet.get('active'):
            active_pet = clean_pet
        elif pet.get('stage') == 'egg' and pet.get('level', 0) == 0:
            available_eggs.append(clean_pet)
        else:
            available_pets.append(clean_pet)
    
    pets_obj = {}
    if active_pet:
        pets_obj["pet"] = active_pet
    
    # Build the export JSON matching the game format
    export = {
        "name": config.get("name", "Unknown"),
        "game_version": config.get("game_version", "Unknown"),
        "steps": config.get("steps", 0),
        "achievement_points": config.get("achievement_points", 0),
        "coins": config.get("coins", 0),
        "skills": skills,
        "reputation": config.get("reputation", {}),
        "inventory": inventory,
        "bank": {},
        "gear": {},
        "consumables": {},
        "collectibles": config.get("collectibles", []),
        "pets": pets_obj,
        "available_pets": available_pets,
        "available_eggs": available_eggs,
    }
    
    # Include custom_stats if present in ui_config
    ui_config = session.get('ui_config', {})
    custom_stats = ui_config.get('custom_stats')
    if custom_stats is not None:
        export["custom_stats"] = custom_stats
    
    return {"success": True, "export": export}


def _recompute_inventory_value(uuid: str):
    """Recompute and store inventory_value for a session based on all items with quantities."""
    try:
        from util.autogenerated.export_names import get_item_from_export_name
        
        session = get_db().get_session(uuid)
        if not session or not session.get('character_config'):
            return
        
        config = session['character_config']
        inventory_value = config.get('coins', 0) or 0
        
        # Use full inventory from separate column if available
        all_items_json = session.get('all_items_raw')
        if all_items_json:
            try:
                all_items = json.loads(all_items_json) if isinstance(all_items_json, str) else all_items_json
                for export_name, quantity in all_items.items():
                    try:
                        item_obj = get_item_from_export_name(export_name)
                        if item_obj and hasattr(item_obj, 'value') and item_obj.value:
                            inventory_value += item_obj.value * quantity
                    except Exception:
                        pass
            except (json.JSONDecodeError, TypeError):
                pass
        else:
            # Fallback to owned_items (no quantities)
            owned_items = config.get('owned_items', [])
            for export_name in owned_items:
                try:
                    item_obj = get_item_from_export_name(export_name)
                    if item_obj and hasattr(item_obj, 'value') and item_obj.value:
                        inventory_value += item_obj.value
                except Exception:
                    pass
        
        get_db().update_inventory_value(uuid, inventory_value)
    except Exception as e:
        log(f"Failed to recompute inventory value: {e}", uuid)


@app.patch("/api/session/{uuid}/config")
async def update_config(uuid: str, update: ConfigUpdate):
    """
    Update a specific configuration path.
    
    Supports nested paths like "items.TRAVELERS_KIT.has" or "skills.mining".
    Automatically determines whether to update character_config or ui_config.
    
    Args:
        uuid: Session UUID
        update: ConfigUpdate with path and value
        
    Returns:
        Success message
        
    Raises:
        HTTPException: If session doesn't exist
    """
    # Ensure session exists
    session = get_db().get_session(uuid)
    if not session:
        raise HTTPException(
            status_code=404,
            detail={
                "error": True,
                "code": "SESSION_NOT_FOUND",
                "message": f"Session {uuid} not found"
            }
        )
    
    try:
        # Update the config path
        get_db().update_config_path(uuid, update.path, update.value)
        
        # Recompute inventory value when item ownership changes
        if update.path.startswith('items.') and update.path.endswith('.has'):
            _recompute_inventory_value(uuid)
        
        # Invalidate stats report results when item ownership, hide, or quality changes
        parts = update.path.split('.')
        if len(parts) >= 3 and parts[0] == 'items' and parts[2] in ('has', 'hide', 'quality'):
            try:
                get_db().mark_stats_report_runs_stale(uuid)
            except Exception:
                pass  # Non-critical
        
        return {
            "success": True,
            "message": f"Updated {update.path} to {update.value}"
        }
        
    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail={
                "error": True,
                "code": "DATABASE_ERROR",
                "message": "Failed to update configuration",
                "details": str(e)
            }
        )

