@app.get("/api/session/{uuid}/gearsets")
async def get_gear_sets(uuid: str, response: Response, summary: bool = False, limit: Optional[int] = None, offset: int = 0):
    """
    Get all gear sets for a session.

    Args:
        uuid: Session UUID
        summary: When True (default False), omit the heavy `slots_json` and
            `export_string` fields. The list-only metadata is enough for the
            gear-set manager dropdown and for the saved-gearset picker; full
            data is fetched lazily via GET /api/session/{uuid}/gearsets/{id}
            when the user actually loads or compares a gearset.

            For accounts with hundreds of saved gearsets this drops the
            response from hundreds of KB to a few KB and removes a 1-second
            page-load hit (measured: 1156ms → ~150ms on Xavlamin).
        limit: When provided, return only the N most-recently-updated gearsets.
            Page load defaults to 50 (frontend opts in); the user can request
            the full list via the "Load all" button on the dropdown. The total
            count is returned in the X-Total-Count response header so the
            frontend knows whether more exist.
        offset: Skip this many rows. Only meaningful with `limit`.

    Returns:
        List of gear sets with id, name, timestamps, is_optimized.
        When summary=False, also includes slots_json and export_string.
        Response sets X-Total-Count header with the total number of gearsets
        for this session, regardless of limit.
    """
    # Ensure session exists
    session = get_db().get_session(uuid)
    if not session:
        # Create session if doesn't exist
        get_db().create_session(uuid)

    # Always set total count so the frontend can decide whether to offer
    # "Load all" — extremely cheap query (single SELECT COUNT).
    total = get_db().count_gear_sets(uuid)
    response.headers["X-Total-Count"] = str(total)
    # Browsers can only access a custom header from XHR responses if the server
    # explicitly exposes it. The default CORS middleware doesn't include this
    # one. Same-origin XHR doesn't actually need it (only cross-origin) but
    # setting it is safe and future-proofs against subdomain CDN setups.
    response.headers["Access-Control-Expose-Headers"] = "X-Total-Count"

    gear_sets = get_db().get_gear_sets(uuid, limit=limit, offset=offset)
    if summary:
        return [
            {
                "id": gs["id"],
                "session_uuid": gs["session_uuid"],
                "name": gs["name"],
                "is_optimized": gs.get("is_optimized", False),
                "created_at": gs["created_at"],
                "updated_at": gs["updated_at"],
            }
            for gs in gear_sets
        ]
    return gear_sets


@app.get("/api/session/{uuid}/gearsets/{gearset_id}", response_model=GearSetResponse)
async def get_gear_set(uuid: str, gearset_id: str):
    """
    Get a single gear set by id, including the heavy `slots_json` and
    `export_string` fields. Used by the frontend to lazy-load the full
    payload of a gearset that was initially listed in summary mode.
    """
    session = get_db().get_session(uuid)
    if not session:
        raise HTTPException(status_code=404, detail="Session not found")

    gear_sets = get_db().get_gear_sets(uuid)
    for gs in gear_sets:
        if gs["id"] == gearset_id:
            return gs
    raise HTTPException(status_code=404, detail="Gear set not found")


@app.post("/api/session/{uuid}/gearsets", response_model=GearSetResponse)
async def save_gear_set(uuid: str, data: GearSetData):
    """
    Save or update a gear set.
    
    If data.id is provided and exists, updates that gear set.
    If data.name matches an existing gear set, updates that gear set.
    Otherwise, creates a new gear set.
    
    Args:
        uuid: Session UUID
        data: GearSetData with name, slots, and optional id
        
    Returns:
        Saved gear set data
        
    Raises:
        HTTPException: If name conflicts with existing gear set (when creating new)
    """
    # Ensure session exists
    session = get_db().get_session(uuid)
    if not session:
        get_db().create_session(uuid)
    
    try:
        gear_set = get_db().save_gear_set(
            session_uuid=uuid,
            name=data.name,
            slots_json=data.slots,
            gear_set_id=data.id
        )
        return gear_set
        
    except ValueError as e:
        raise HTTPException(
            status_code=400,
            detail={
                "error": True,
                "code": "DUPLICATE_NAME",
                "message": str(e)
            }
        )
    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail={
                "error": True,
                "code": "DATABASE_ERROR",
                "message": "Failed to save gear set",
                "details": str(e)
            }
        )


@app.delete("/api/session/{uuid}/gearsets/{gearset_id}")
async def delete_gear_set(uuid: str, gearset_id: str):
    """
    Delete a gear set.
    
    Args:
        uuid: Session UUID
        gearset_id: Gear set ID to delete
        
    Returns:
        Success message
        
    Raises:
        HTTPException: If gear set not found
    """
    # Ensure session exists
    session = get_db().get_session(uuid)
    if not session:
        raise HTTPException(
            status_code=404,
            detail={
                "error": True,
                "code": "SESSION_NOT_FOUND",
                "message": f"Session {uuid} not found"
            }
        )
    
    deleted = get_db().delete_gear_set(uuid, gearset_id)
    
    if not deleted:
        raise HTTPException(
            status_code=404,
            detail={
                "error": True,
                "code": "GEAR_SET_NOT_FOUND",
                "message": f"Gear set {gearset_id} not found"
            }
        )
    
    return {
        "success": True,
        "message": f"Gear set {gearset_id} deleted"
    }


# ============================================================================
# GEAR SET CLEANUP ENDPOINTS
# ============================================================================

def compute_gear_set_fingerprint(gear_set: dict) -> str:
    """Compute a deterministic fingerprint for a gear set based on its equipment.
    
    Tier 1: Use raw export_string when available (fast string equality).
    Tier 2: Build normalized fingerprint from slots_json via SHA-256 hash.
    """
    export_string = gear_set.get('export_string')
    if export_string:
        return export_string
    
    # Fallback: normalize slots_json
    return _fingerprint_from_slots(gear_set.get('slots_json', {}))


def _fingerprint_from_slots(slots_json: dict) -> str:
    """Build a SHA-256 fingerprint from normalized slot data."""
    import hashlib
    
    canonical_slots = [
        'head', 'cape', 'back', 'chest', 'hands', 'legs', 'neck', 'feet',
        'primary', 'secondary', 'ring1', 'ring2',
        'tool0', 'tool1', 'tool2', 'tool3', 'tool4', 'tool5',
        'consumable', 'pet',
    ]
    
    normalized = []
    for slot in sorted(canonical_slots):
        slot_data = slots_json.get(slot)
        if slot_data and isinstance(slot_data, dict):
            item_id = slot_data.get('itemId') or slot_data.get('id') or None
            quality = slot_data.get('quality') or slot_data.get('rarity') or None
            normalized.append([slot, [item_id, quality]])
        else:
            normalized.append([slot, None])
    
    serialized = json.dumps(normalized, sort_keys=True)
    return 'slots:' + hashlib.sha256(serialized.encode('utf-8')).hexdigest()


def _decode_export_to_slots(export_string: str) -> dict:
    """Decode an export string to normalized {slot: {itemId, quality}} dict."""
    try:
        from util.gearset_utils import decode_gearset
        decoded = decode_gearset(export_string)
        items = decoded.get('items', [])
        
        slots = {}
        for entry in items:
            slot_type = entry.get('type', '')
            index = entry.get('index', 0)
            item_str = entry.get('item', 'null')
            
            # Build canonical slot name
            if slot_type == 'ring':
                slot_name = f'ring{index + 1}'
            elif slot_type == 'tool':
                slot_name = f'tool{index}'
            else:
                slot_name = slot_type
            
            if item_str and item_str != 'null':
                try:
                    item_data = json.loads(item_str) if isinstance(item_str, str) else item_str
                    slots[slot_name] = {
                        'itemId': item_data.get('id'),
                        'quality': item_data.get('quality'),
                    }
                except (json.JSONDecodeError, AttributeError):
                    slots[slot_name] = None
            else:
                slots[slot_name] = None
        
        return slots
    except Exception:
        return {}


def find_duplicate_groups(gear_sets: list) -> list:
    """Find groups of duplicate gear sets.
    
    Two-tier detection:
    1. Group by raw export_string (fast)
    2. Merge groups with matching decoded fingerprints (catches different encodings)
    
    Returns list of DuplicateGroup dicts sorted by group size descending.
    """
    from collections import defaultdict
    
    # Tier 1: group by raw fingerprint
    groups_by_fp = defaultdict(list)
    for gs in gear_sets:
        fp = compute_gear_set_fingerprint(gs)
        groups_by_fp[fp].append(gs)
    
    # Tier 2: merge groups with matching decoded fingerprints
    decoded_fp_to_group_key = {}
    merged_groups = {}
    
    for fp, group in groups_by_fp.items():
        # Compute decoded fingerprint for this group (use first member)
        first_gs = group[0]
        export_string = first_gs.get('export_string')
        
        if export_string:
            decoded_slots = _decode_export_to_slots(export_string)
            decoded_fp = _fingerprint_from_slots(decoded_slots)
        else:
            decoded_fp = fp  # Already a slots-based fingerprint
        
        if decoded_fp in decoded_fp_to_group_key:
            # Merge into existing group
            existing_key = decoded_fp_to_group_key[decoded_fp]
            merged_groups[existing_key].extend(group)
        else:
            decoded_fp_to_group_key[decoded_fp] = fp
            merged_groups[fp] = list(group)
    
    # Build result: exclude singletons, sort by size desc
    result = []
    for fp, group in merged_groups.items():
        if len(group) < 2:
            continue
        
        # Sort by updated_at descending (most recent first = keep candidate)
        group.sort(key=lambda gs: gs.get('updated_at', ''), reverse=True)
        
        keep = group[0]
        delete = group[1:]
        
        result.append({
            'fingerprint': fp,
            'gear_sets': [
                {'id': gs['id'], 'name': gs['name'], 'updated_at': gs.get('updated_at', '')}
                for gs in group
            ],
            'keep_id': keep['id'],
            'delete_ids': [gs['id'] for gs in delete],
        })
    
    # Sort groups by size descending
    result.sort(key=lambda g: len(g['gear_sets']), reverse=True)
    
    return result


@app.get("/api/gear-sets/{session_uuid}/duplicates", response_model=DuplicatesResponse)
async def get_duplicate_gear_sets(session_uuid: str):
    """Detect duplicate gear sets for a session."""
    session = get_db().get_session(session_uuid)
    if not session:
        raise HTTPException(
            status_code=404,
            detail={"error": True, "code": "SESSION_NOT_FOUND", "message": f"Session {session_uuid} not found"}
        )
    
    gear_sets = get_db().get_gear_sets(session_uuid)
    groups = find_duplicate_groups(gear_sets)
    return {"groups": groups}


@app.post("/api/gear-sets/{session_uuid}/cleanup", response_model=CleanupResponse)
async def cleanup_gear_sets(session_uuid: str, data: CleanupRequest):
    """Bulk-delete gear sets by ID. Only deletes gear sets belonging to the session."""
    session = get_db().get_session(session_uuid)
    if not session:
        raise HTTPException(
            status_code=404,
            detail={"error": True, "code": "SESSION_NOT_FOUND", "message": f"Session {session_uuid} not found"}
        )
    
    deleted_count = get_db().bulk_delete_gear_sets(session_uuid, data.ids)
    return {"deleted_count": deleted_count}


