@app.post("/api/custom-keywords")
async def save_custom_keyword(request: Request):
    """Save a new custom keyword."""
    body = await request.json()
    name = (body.get('name') or '').strip()
    if not name:
        raise HTTPException(status_code=400, detail="Keyword name is required")
    icon = body.get('icon', '🏷️')
    icon_color = body.get('icon_color')
    banned = body.get('banned', True)
