@app.get("/api/items")
async def get_items(request: Request, response: Response):
    """
    Get full item catalog with categories.
    
    Returns all items organized by category:
    - Collectibles
    - Consumables (by skill)
    - Materials
    - Loot (achievement rewards, activity drops, faction rewards, shop items, chests)
    - Crafted (by keyword)
    - Pets
    
    Returns:
        Dict with categories and item counts
    """
    from ui.catalog import ItemCatalog
    
    cached = _maybe_static_304(request, response, "items")
    if cached:
        return cached
    
    catalog = ItemCatalog()
    
    return {
        "categories": catalog.categories,
        "counts": catalog.get_categories()
    }


@app.get("/api/catalog")
async def get_catalog(request: Request, response: Response):
    """
    Get flat item catalog for gear selection popup.
    
    Returns all items as a flat list with full details needed for
    the item selection popup (slot, stats, rarity, etc.)
    
    Returns:
        Dict with items array and collectibles array
    """
    from ui.catalog import ItemCatalog
    from util.walkscape_constants import Item
    
    cached = _maybe_static_304(request, response, "catalog")
    if cached:
        return cached
    
    catalog = ItemCatalog()
    
    # Flatten all items from categories into a single list
    all_items = []
    
    def add_items_from_category(category_data):
        """Recursively extract items from category structure"""
        if isinstance(category_data, dict):
            # Check if this is an item (has 'id' field)
            if 'id' in category_data and 'name' in category_data:
                all_items.append(category_data)
            else:
                # Recurse into subcategories
                for key, value in category_data.items():
                    if isinstance(value, (dict, list)):
                        add_items_from_category(value)
        elif isinstance(category_data, list):
            for item in category_data:
                add_items_from_category(item)
    
    # Extract items from all categories (except collectibles, we'll handle those separately)
    for category_name, category_data in catalog.categories.items():
        if category_name != 'collectibles':
            add_items_from_category(category_data)
    
    # Get collectibles separately (flatten from subcategorized structure)
    collectibles_data = catalog.categories.get('collectibles', {})
    collectibles = []
    if isinstance(collectibles_data, dict):
        for subcat_data in collectibles_data.values():
            if isinstance(subcat_data, list):
                collectibles.extend(subcat_data)
            elif isinstance(subcat_data, dict):
                for group_items in subcat_data.values():
                    if isinstance(group_items, list):
                        collectibles.extend(group_items)
    elif isinstance(collectibles_data, list):
        collectibles = collectibles_data
    
    # Note: No session UUID available in this endpoint (static data)
    log(f"Catalog API: Returning {len(all_items)} items and {len(collectibles)} collectibles")
    
    # Debug: log Ghost trap pack stats
    for item in all_items:
        if item.get('name') == 'Ghost trap pack':
            log(f"  DEBUG Ghost trap pack stats: {item.get('stats')}")
            break
    
    # Build export-name-to-item-id alias map for renamed items
    # This helps the frontend match owned_items (stored as export names) to catalog IDs
    from util.autogenerated.export_names import get_item_mapping
    item_mapping = get_item_mapping()
    export_aliases = {}
    for export_name, item_obj in item_mapping.items():
        if hasattr(item_obj, 'name'):
            canonical_id = item_obj.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
            if export_name != canonical_id:
                export_aliases[export_name] = canonical_id
    
    return {
        "items": all_items,
        "collectibles": collectibles,
        "export_aliases": export_aliases
    }

@app.get("/api/skills")
async def get_skills(request: Request, response: Response):
    """
    Get skill definitions with categories.
    
    Returns all skills organized by category:
    - Gathering: Fishing, Foraging, Hunting, Mining, Woodcutting
    - Artisan: Carpentry, Cooking, Crafting, Smithing, Tailoring, Trinketry
    - Utility: Agility
    
    Returns:
        Dict with skill categories and definitions
    """
    from util.walkscape_constants import Skill
    
    cached = _maybe_static_304(request, response, "skills")
    if cached:
        return cached
    
    # Define skill categories
    gathering_skills = ['fishing', 'foraging', 'hunting', 'mining', 'woodcutting']
    artisan_skills = ['carpentry', 'cooking', 'crafting', 'smithing', 'tailoring', 'trinketry']
    utility_skills = ['agility']  # Only Agility is a traditional skill in Utility
    
    # Build skill list
    skills = []
    for attr_name in dir(Skill):
        if attr_name.startswith('_') or not attr_name.isupper():
            continue
        
        skill = getattr(Skill, attr_name)
        if not hasattr(skill, 'name') or not hasattr(skill, 'value'):
            continue
        
        # Determine category
        skill_value = skill.value.lower()
        if skill_value in gathering_skills:
            category = 'Gathering'
        elif skill_value in artisan_skills:
            category = 'Artisan'
        elif skill_value in utility_skills:
            category = 'Utility'
        else:
            # Skip skills that aren't in any category (like Traveling)
            continue
        
        skills.append({
            'id': skill_value,
            'name': skill.name,
            'display_name': skill_value.capitalize(),
            'category': category
        })
    
    # Sort by category then name
    skills.sort(key=lambda x: (x['category'], x['display_name']))
    
    # Group by category
    by_category = {
        'Gathering': [],
        'Artisan': [],
        'Utility': []
    }
    
    for skill in skills:
        by_category[skill['category']].append(skill)
    
    return {
        "skills": skills,
        "by_category": by_category
    }


@app.get("/api/activities")
async def get_activities(request: Request, response: Response):
    """
    Get all activities organized by skill.
    
    Returns activities with:
    - Icon paths
    - Locations
    - Requirements (skill, keyword, reputation, achievement points)
    - Drop tables (with level-based drop rates calculated)
    - Base stats (steps, xp, max efficiency)
    
    Returns:
        Dict with activities organized by skill category
    """
    from util.autogenerated.activities import Activity, ActivityInfo
    
    cached = _maybe_static_304(request, response, "activities")
    if cached:
        return cached
    
    # Collect all activities
    activities_by_skill = {}
    all_activities = []
    
    for attr_name in dir(Activity):
        if attr_name.startswith('_'):
            continue
        
        activity = getattr(Activity, attr_name)
        if not isinstance(activity, ActivityInfo):
            continue
        
        # Build activity data
        skill = activity.primary_skill or 'Other'
        
        # Generate activity ID from name
        activity_id = activity.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
        
        # Build icon path - skill folder + activity name
        skill_folder = skill.lower() if skill != 'Other' else 'other'
        icon_filename = activity.name.lower().replace(' ', '_').replace("'", '').replace('-', '_')
        icon_path = f"/assets/icons/activities/{skill_folder}/{icon_filename}.svg"
        
        # Build locations list
        locations = []
        for loc in activity.locations:
            if hasattr(loc, 'name'):
                loc_id = loc.name.lower().replace(' ', '_').replace("'", '')
                locations.append({
                    'id': loc_id,
                    'name': loc.name,
                    'regions': loc.regions if hasattr(loc, 'regions') else [],
                    'is_underwater': loc.is_underwater if hasattr(loc, 'is_underwater') else False,
                    'icon_name': loc.icon_name if hasattr(loc, 'icon_name') else None
                })
        
        # Build requirements
        requirements = {
            'skill_requirements': activity.skill_requirements,
            'keyword_counts': activity.requirements.get('keyword_counts', {}),
            'reputation': activity.requirements.get('reputation', {}),
            'achievement_points': activity.requirements.get('achievement_points', 0),
            'activity_completions': activity.requirements.get('activity_completions', {}),
            'item_requirements': activity.requirements.get('item_requirements', []),
            'keyword_level_requirements': activity.requirements.get('keyword_level_requirements', [])
        }
        
        # Build drop table
        drop_table = []
        
        # Chest sell values. Single source of truth is util.coin_value so
        # the optimizer's coin target (cat:coins) and this drop-table
        # endpoint can never diverge. See util/coin_value.py for the wiki
        # link + note on the locally-computed Hunting/Tailoring values.
        from util.coin_value import CHEST_COIN_VALUES
        # Sea shell values. CHEST_SHELL_VALUES is the source of truth for
        # how many sea shells (linearly) a chest is expected to yield —
        # see util/shell_value.py. Used by both the cat:sea_shells
        # optimizer target and the column-3 shells/1k pill.
        from util.shell_value import (
            CHEST_SHELL_VALUES,
            get_drop_shell_value,
            get_drop_fine_shell_value,
        )
        
        def _get_drop_currency_info(drop):
            """Extract coin value and special sell info from a drop entry.
            Resolves directly from item_ref to avoid circular import through item_object.
            """
            coin_value = 0
            special_sell = None
            shell_value = get_drop_shell_value(drop)
            fine_shell_value = get_drop_fine_shell_value(drop)
            if not drop.item_ref:
                # Coins drop with no ref (e.g., chest Coins entries)
                if drop.item_name == 'Coins':
                    coin_value = 1
                return coin_value, special_sell, shell_value, fine_shell_value
            try:
                ref = drop.item_ref
                if ref == 'Currency.COIN':
                    coin_value = 1
                elif ref == 'Currency.ADVENTURERS_GUILD_TOKEN':
                    special_sell = {'quantity': 1, 'currency': 'ag_token'}
                elif ref.startswith('Container.'):
                    # Use wiki chest values
                    coin_value = CHEST_COIN_VALUES.get(ref, 0)
                elif ref.startswith('Material.'):
                    from util.autogenerated.materials import Material
                    attr_name = ref.split('.', 1)[1]
                    if hasattr(Material, attr_name):
                        obj = getattr(Material, attr_name)
                        coin_value = obj.value or 0
                        if hasattr(obj, 'special_sell') and obj.special_sell:
                            qty, currency_obj = obj.special_sell
                            if hasattr(currency_obj, 'name') and 'guild token' in currency_obj.name.lower():
                                special_sell = {'quantity': qty, 'currency': 'ag_token'}
                elif ref.startswith('Consumable.'):
                    from util.autogenerated.consumables import Consumable
                    attr_name = ref.split('.', 1)[1]
                    if hasattr(Consumable, attr_name):
                        obj = getattr(Consumable, attr_name)
                        if hasattr(obj, 'value'):
                            coin_value = obj.value or 0
                elif ref.startswith('Item.'):
                    # 2026-05-28 (jwbail): equipment drops (e.g. Flippers from
                    # Underwater swimming) carry an intrinsic .value used by
                    # the optimizer's coin-target scoring. Without this branch
                    # column-3 reported coin_value=0 for Item.* drops while
                    # the worker's compute_coin_targets used the real value,
                    # producing a stable per-activity gap (Flippers contributes
                    # ~0.90 coins/1k on Underwater swimming with the user's
                    # gear). Per the existing rule that items keep their
                    # wiki/legacy value even when the API says canBeSold=false,
                    # we surface the intrinsic value here so column-3 matches
                    # the worker's optimizer score.
                    from util.autogenerated.equipment import Item
                    attr_name = ref.split('.', 1)[1]
                    if hasattr(Item, attr_name):
                        obj = getattr(Item, attr_name)
                        if hasattr(obj, 'value'):
                            coin_value = obj.value or 0
            except Exception:
                pass
            return coin_value, special_sell, shell_value, fine_shell_value
        
        # Get character skill level for level-based drops
        character_skill_level = 1
        if hasattr(request, 'state') and hasattr(request.state, 'session_uuid'):
            try:
                session = get_db().get_session(request.state.session_uuid)
                if session and session.get('character_config'):
                    char_config = session['character_config']
                    skill_name = skill.lower()
                    character_skill_level = char_config.get('skills', {}).get(skill_name, 1)
            except:
                pass
        
        # Calculate total weight for level-based drops
        has_level_based = any(hasattr(drop, 'is_level_based') and drop.is_level_based for drop in activity.drop_table)
        total_weight = 0.0
        non_level_weighted_percent = 10.0
        if has_level_based:
            for drop in activity.drop_table:
                if hasattr(drop, 'is_level_based') and drop.is_level_based:
                    total_weight += drop.calculate_weight(character_skill_level)
            
            # Calculate non_level_weighted_percent
            total_final_chance = sum(drop.final_chance for drop in activity.drop_table if hasattr(drop, 'final_chance') and drop.final_chance)
            non_level_weighted_percent = 100.0 - total_final_chance
        
        for drop in activity.drop_table:
            if drop.item_name == 'Nothing':
                continue
            
            # Get drop chance (static or level-based)
            if hasattr(drop, 'is_level_based') and drop.is_level_based:
                chance_percent = drop.get_chance_at_level(character_skill_level, total_weight, non_level_weighted_percent)
            else:
                chance_percent = drop.chance_percent
            
            # Check if this item has a fine version
            # Check Materials and Consumables for fine counterparts
            has_fine = False
            if drop.item_ref and drop.item_ref.startswith('Material.'):
                try:
                    from util.autogenerated.materials import Material
                    material_name = drop.item_ref.replace('Material.', '')
                    fine_name = f"{material_name}_FINE"
                    has_fine = hasattr(Material, fine_name)
                except Exception as e:
                    pass
            elif drop.item_ref and drop.item_ref.startswith('Consumable.'):
                try:
                    from util.autogenerated.consumables import Consumable
                    consumable_name = drop.item_ref.replace('Consumable.', '')
                    fine_name = f"{consumable_name}_FINE"
                    has_fine = hasattr(Consumable, fine_name)
                except Exception as e:
                    pass
            
            coin_value, special_sell_info, shell_value, fine_shell_value = _get_drop_currency_info(drop)
            
            # Get fine version coin value if applicable
            fine_coin_value = 0
            if has_fine:
                try:
                    if drop.item_ref.startswith('Material.'):
                        from util.autogenerated.materials import Material
                        fine_name = drop.item_ref.replace('Material.', '') + '_FINE'
                        if hasattr(Material, fine_name):
                            fine_coin_value = getattr(Material, fine_name).value or 0
                    elif drop.item_ref.startswith('Consumable.'):
                        from util.autogenerated.consumables import Consumable
                        fine_name = drop.item_ref.replace('Consumable.', '') + '_FINE'
                        if hasattr(Consumable, fine_name):
                            fine_coin_value = getattr(Consumable, fine_name).value or 0
                except Exception:
                    pass
            
            # Get item keywords for frontend find bonus detection (e.g., gems)
            item_keywords = []
            try:
                if drop.item_object and hasattr(drop.item_object, 'keywords'):
                    item_keywords = [kw for kw in drop.item_object.keywords]
            except Exception:
                pass
            
            drop_entry = {
                'item_name': drop.item_name,
                'item_ref': drop.item_ref,
                'chance_percent': chance_percent,
                # Level gate: the skill level at which this drop first appears.
                # Sent only for level-based drops so the UI can show a grayed
                # "At <skill> <level>" card when the character is below it
                # instead of a 0% / infinite-steps row (bug 1a799e8d follow-up).
                'initial_level': drop.initial_level if (hasattr(drop, 'is_level_based') and drop.is_level_based) else None,
                # max_chance_level + final_chance let the frontend re-scale a
                # level-based drop's chance to a manually-edited (column-1)
                # skill level instead of the imported character level.
                'max_chance_level': drop.max_chance_level if (hasattr(drop, 'is_level_based') and drop.is_level_based) else None,
                'final_chance': drop.final_chance if (hasattr(drop, 'is_level_based') and drop.is_level_based) else None,
                'has_fine_material': has_fine,
                'coin_value': coin_value,
                'fine_coin_value': fine_coin_value,
                'special_sell': special_sell_info,
                'fine_ag_token_value': get_drop_fine_ag_token_value(drop),
                'shell_value': shell_value,
                'fine_shell_value': fine_shell_value,
                'item_keywords': item_keywords,
                'multi_roll_count': drop.multi_roll_count if hasattr(drop, 'multi_roll_count') and drop.multi_roll_count else None,
                'quantity': {
                    'min': drop.quantity.min_qty if not drop.quantity.is_na else None,
                    'max': drop.quantity.max_qty if not drop.quantity.is_na else None,
                    'is_static': drop.quantity.is_static if hasattr(drop.quantity, 'is_static') else False
                }
            }
            drop_table.append(drop_entry)
        
        # Build secondary drop table
        secondary_drop_table = []
        for drop in activity.secondary_drop_table:
            # Get drop chance (static or level-based)
            if hasattr(drop, 'is_level_based') and drop.is_level_based:
                chance_percent = drop.get_chance_at_level(character_skill_level, total_weight, non_level_weighted_percent)
            else:
                chance_percent = drop.chance_percent
            
            # Check if this item has a fine version
            # Check Materials and Consumables for fine counterparts
            has_fine = False
            if drop.item_ref and drop.item_ref.startswith('Material.'):
                try:
                    from util.autogenerated.materials import Material
                    material_name = drop.item_ref.replace('Material.', '')
                    fine_name = f"{material_name}_FINE"
                    has_fine = hasattr(Material, fine_name)
                except Exception as e:
                    pass
            elif drop.item_ref and drop.item_ref.startswith('Consumable.'):
                try:
                    from util.autogenerated.consumables import Consumable
                    consumable_name = drop.item_ref.replace('Consumable.', '')
                    fine_name = f"{consumable_name}_FINE"
                    has_fine = hasattr(Consumable, fine_name)
                except Exception as e:
                    pass
            
            coin_value, special_sell_info, shell_value, fine_shell_value = _get_drop_currency_info(drop)
            
            # Get fine version coin value if applicable
            fine_coin_value = 0
            if has_fine:
                try:
                    if drop.item_ref.startswith('Material.'):
                        from util.autogenerated.materials import Material
                        fine_name = drop.item_ref.replace('Material.', '') + '_FINE'
                        if hasattr(Material, fine_name):
                            fine_coin_value = getattr(Material, fine_name).value or 0
                    elif drop.item_ref.startswith('Consumable.'):
                        from util.autogenerated.consumables import Consumable
                        fine_name = drop.item_ref.replace('Consumable.', '') + '_FINE'
                        if hasattr(Consumable, fine_name):
                            fine_coin_value = getattr(Consumable, fine_name).value or 0
                except Exception:
                    pass
            
            # Get item keywords for frontend find bonus detection (e.g., gems)
            item_keywords = []
            try:
                if drop.item_object and hasattr(drop.item_object, 'keywords'):
                    item_keywords = [kw for kw in drop.item_object.keywords]
            except Exception:
                pass
            
            drop_entry = {
                'item_name': drop.item_name,
                'item_ref': drop.item_ref,
                'chance_percent': chance_percent,
                # Level gate: the skill level at which this drop first appears.
                # Sent only for level-based drops so the UI can show a grayed
                # "At <skill> <level>" card when the character is below it
                # instead of a 0% / infinite-steps row (bug 1a799e8d follow-up).
                'initial_level': drop.initial_level if (hasattr(drop, 'is_level_based') and drop.is_level_based) else None,
                # max_chance_level + final_chance let the frontend re-scale a
                # level-based drop's chance to a manually-edited (column-1)
                # skill level instead of the imported character level.
                'max_chance_level': drop.max_chance_level if (hasattr(drop, 'is_level_based') and drop.is_level_based) else None,
                'final_chance': drop.final_chance if (hasattr(drop, 'is_level_based') and drop.is_level_based) else None,
                'has_fine_material': has_fine,
                'coin_value': coin_value,
                'fine_coin_value': fine_coin_value,
                'special_sell': special_sell_info,
                'fine_ag_token_value': get_drop_fine_ag_token_value(drop),
                'shell_value': shell_value,
                'fine_shell_value': fine_shell_value,
                'item_keywords': item_keywords,
                'multi_roll_count': drop.multi_roll_count if hasattr(drop, 'multi_roll_count') and drop.multi_roll_count else None,
                'quantity': {
                    'min': drop.quantity.min_qty if not drop.quantity.is_na else None,
                    'max': drop.quantity.max_qty if not drop.quantity.is_na else None,
                    'is_static': drop.quantity.is_static if hasattr(drop.quantity, 'is_static') else False
                }
            }
            secondary_drop_table.append(drop_entry)
        
        # Build secondary XP
        secondary_xp = {}
        if activity.secondary_xp:
            for skill_name, xp in activity.secondary_xp.items():
                secondary_xp[skill_name] = xp
        
        # Build faction reputation reward
        faction_reward = None
        if activity.faction_reputation_reward:
            faction_reward = {
                'faction': activity.faction_reputation_reward.name,
                'value': activity.faction_reputation_reward.value
            }
        
        activity_data = {
            'id': activity_id,
            'name': activity.name,
            'primary_skill': skill,
            'icon_path': icon_path,
            'locations': locations,
            'requirements': requirements,
            'drop_table': drop_table,
            'secondary_drop_table': secondary_drop_table,
            'base_steps': activity.base_steps,
            'base_xp': activity.base_xp,
            'secondary_xp': secondary_xp,
            'max_efficiency': activity.max_efficiency,
            'faction_reputation_reward': faction_reward,
            'description': activity.description,
            'input_items': [
                {k: v for k, v in {
                    'name': ii.name, 'type': ii.type, 'reference': ii.reference,
                    'quantity': ii.quantity, 'level': getattr(ii, 'level', None),
                    'optional': getattr(ii, 'optional', False) or None
                }.items() if v is not None}
                for ii in (activity.input_items or [])
            ] if hasattr(activity, 'input_items') and activity.input_items else [],
        }
        
        all_activities.append(activity_data)
        
        # Organize by skill
        if skill not in activities_by_skill:
            activities_by_skill[skill] = []
        activities_by_skill[skill].append(activity_data)
    
    # Add special "Traveling" activity under Agility
    traveling_activity = {
        'id': 'traveling',
        'name': 'Traveling',
        'primary_skill': 'Agility',
        'component_skills': ['agility', 'traveling'],
        'icon_path': '/assets/icons/activities/agility/traveling.svg',
        'locations': [],
        'requirements': {
            'skill_requirements': {},
            'keyword_counts': {},
            'reputation': {},
            'achievement_points': 0,
            'activity_completions': {},
            'item_requirements': []
        },
        'drop_table': [],
        'secondary_drop_table': [],
        'base_steps': 0,
        'base_xp': 0,
        'secondary_xp': {},
        'max_efficiency': 0.60,
        'faction_reputation_reward': None,
        'description': 'Travel between locations across Arenum.',
        'is_travel': True
    }
    all_activities.append(traveling_activity)
    if 'Agility' not in activities_by_skill:
        activities_by_skill['Agility'] = []
    activities_by_skill['Agility'].append(traveling_activity)

    # Sort activities within each skill alphabetically
    for skill in activities_by_skill:
        activities_by_skill[skill].sort(key=lambda x: x['name'])
    
    # Sort skills alphabetically
    sorted_skills = sorted(activities_by_skill.keys())
    sorted_by_skill = {skill: activities_by_skill[skill] for skill in sorted_skills}
    
    return {
        'activities': all_activities,
        'by_skill': sorted_by_skill,
        'count': len(all_activities)
    }


# ============================================================================
# TRAVEL / LOCATIONS API
