# Region display names and icon paths
REGION_CONFIG = {
    'gdte': {'name': 'Grand Duchy of Trellin-Erdwise', 'icon': '/assets/icons/regions/gdte.svg'},
    'jarvonia': {'name': 'Jarvonia', 'icon': '/assets/icons/regions/jarvonia.svg'},
    'syrenthia': {'name': 'Syrenthia', 'icon': '/assets/icons/regions/syrenthia.svg'},
    'wallisia': {'name': 'Wallisia', 'icon': '/assets/icons/regions/wallisia.svg'},
    'wrentmark': {'name': 'Wrentmark', 'icon': '/assets/icons/regions/wrentmark.svg'},
}


@app.get("/api/locations")
async def get_locations(request: Request, response: Response):
    """
    Get all locations grouped by region for location dropdowns.

    Returns:
        { regions: [{ id, name, icon, locations: [{ id, name }] }] }
        Regions sorted alphabetically by display name, locations sorted alphabetically within each region.
    """
    from util.autogenerated.locations import Location, LocationInfo

    cached = _maybe_static_304(request, response, "locations")
    if cached:
        return cached
    regions_map = {}  # region_id -> list of {id, name}

    for attr_name in dir(Location):
        if attr_name.startswith('_'):
            continue
        loc = getattr(Location, attr_name)
        if not isinstance(loc, LocationInfo):
            continue

        # Use the primary region (first in the regions list)
        primary = loc.primary_region
        if primary not in REGION_CONFIG:
            continue

        loc_id = attr_name.lower()
        if primary not in regions_map:
            regions_map[primary] = []
        regions_map[primary].append({
            'id': loc_id,
            'name': loc.name,
            'icon_name': loc.icon_name,
            'regions': loc.regions if hasattr(loc, 'regions') else [loc_id],
        })

    # Build response sorted alphabetically
    regions = []
    for region_id, config in REGION_CONFIG.items():
        locs = regions_map.get(region_id, [])
        locs.sort(key=lambda x: x['name'])
        regions.append({
            'id': region_id,
            'name': config['name'],
            'icon': config['icon'],
            'locations': locs,
        })

    regions.sort(key=lambda x: x['name'])

    return {'regions': regions}


@app.get("/api/travel/route")
async def get_travel_route(start: str, end: str):
    """
    Find shortest path between two locations.

    Args:
        start: Start location ID (e.g. 'kallaheim')
        end: End location ID (e.g. 'centaham')

    Returns:
        { success, segments: [...], total_distance } or error response.
    """
    from util.travel_route_finder import find_shortest_path, _LOC_NAMES

    if start not in _LOC_NAMES:
        return JSONResponse(
            status_code=400,
            content={'success': False, 'error': f'Unknown start location: {start}'}
        )
    if end not in _LOC_NAMES:
        return JSONResponse(
            status_code=400,
            content={'success': False, 'error': f'Unknown end location: {end}'}
        )

    segments = find_shortest_path(start, end)

    if segments is None:
        return JSONResponse(
            status_code=404,
            content={'success': False, 'error': f'No route found from {_LOC_NAMES[start]} to {_LOC_NAMES[end]}'}
        )

    total_distance = sum(s['distance'] for s in segments)

    return {
        'success': True,
        'segments': segments,
        'total_distance': total_distance,
    }


def _resolve_location(loc_id: str):
    """Resolve a lowercase attr-name location ID to a LocationInfo object."""
    from util.autogenerated.locations import Location, LocationInfo
    attr = loc_id.upper()
    loc = getattr(Location, attr, None)
    if isinstance(loc, LocationInfo):
        return loc
    return None


def _calculate_segment_steps(distance: int, stats: dict, max_efficiency: float = 0.60) -> int:
    """
    Calculate expected steps for a single route segment.

    Uses the travel formula confirmed against the official Walkscape tool:
    1. adjusted = distance / (2 + WE)  -- base efficiency is 200% for traveling, NO WE cap
    2. per_action = adjusted / 10
    3. per_action = per_action * (1 + pct) + flat
    4. per_action = max(10, ceil(per_action))
    5. expected_total = ceil(10 / (1 + DA) * per_action)

    Stats dict should already include level bonus WE from aggregate_gearset_stats.
    """
    import math
    we = stats.get('work_efficiency', 0.0)
    da = stats.get('double_action', 0.0)
    flat = stats.get('steps_add', 0)
    pct = stats.get('steps_percent', 0.0)

    # Step 1: Apply WE with base efficiency of 200% (2.0) for traveling
    adjusted = distance / (2.0 + we)

    # Step 2: Divide into 10 action nodes
    per_action = adjusted / 10.0

    # Step 3: Apply percentage and flat step modifiers
    per_action = per_action * (1.0 + pct) + flat

    # Step 4: Minimum 10 steps per action, round up
    per_action = max(10, math.ceil(per_action))

    # Step 5: Expected total with DA
    expected_paid = 10.0 / (1.0 + da)
    return math.ceil(expected_paid * per_action)


@app.post("/api/travel/stats")
async def get_travel_stats(request: Request):
    """
    Calculate per-segment and total travel stats for a route with a gearset.

    Request body:
        segments: List of route segment dicts (from /api/travel/route)
        gearset_export: Base64-encoded gearset export string

    Returns:
        { success, total: { steps_min, steps_max, steps_avg, work_efficiency, double_action },
          segments: [ per-segment stats ] }
    """
    import math
    from util.gearset_utils import Gearset, aggregate_gearset_stats
    from util.autogenerated.locations import Location, LocationInfo
    from util.walkscape_constants import Skill

    body = await request.json()
    segments = body.get('segments', [])
    gearset_export = body.get('gearset_export', '')

    if not segments:
        return JSONResponse(
            status_code=400,
            content={'success': False, 'error': 'No segments provided'}
        )

    # Decode gearset
    gearset = None
    items = []
    if gearset_export:
        try:
            gearset = Gearset(gearset_export)
            items = [item for _, item in gearset.get_all_items(include_pet_consumable=True)]
            print(f"Travel stats: decoded {len(items)} items from gearset")
            for slot, item in gearset.get_all_items(include_pet_consumable=True):
                item_stats = item.get_stats_for_skill('travel')
                if item_stats.get('double_action', 0) != 0 or item_stats.get('work_efficiency', 0) != 0:
                    print(f"  {slot}: {item.name} -> DA={item_stats.get('double_action',0):.4f}, WE={item_stats.get('work_efficiency',0):.4f}")
        except Exception as e:
            print(f"Travel stats: failed to decode gearset: {e}")

    # Load character from session
    character = None
    if hasattr(request, 'state') and hasattr(request.state, 'session_uuid'):
        try:
            session = get_db().get_session(request.state.session_uuid)
            if session and session.get('character_config'):
                char_config = session['character_config']
                # Apply user overrides
                ui_config = session.get('ui_config', {})
                user_overrides = ui_config.get('user_overrides', {})
                if user_overrides.get('achievement_points') is not None:
                    char_config['achievement_points'] = user_overrides['achievement_points']
                if user_overrides.get('skills'):
                    if 'skills' not in char_config:
                        char_config['skills'] = {}
                    char_config['skills'].update(user_overrides['skills'])
                if user_overrides.get('skills_xp'):
                    if 'skills_xp' not in char_config:
                        char_config['skills_xp'] = {}
                    char_config['skills_xp'].update(user_overrides['skills_xp'])
                if user_overrides.get('reputation'):
                    if 'reputation' not in char_config:
                        char_config['reputation'] = {}
                    char_config['reputation'].update(user_overrides['reputation'])

                # Merge skills: start with levels (converted to XP), override with actual XP
                skills_xp = char_config.get('skills_xp', {})
                skills_levels = char_config.get('skills', {})
                from util.walkscape_constants import level_to_xp
                skills_data = {}
                for skill, level in skills_levels.items():
                    skills_data[skill] = level_to_xp(level)
                for skill, xp in skills_xp.items():
                    skills_data[skill] = xp
                
                minimal_export = {
                    "name": char_config.get('name', 'Player'),
                    "game_version": char_config.get('game_version', '1.0'),
                    "steps": char_config.get('steps', 0),
                    "achievement_points": char_config.get('achievement_points', 0),
                    "coins": char_config.get('coins', 0),
                    "skills": skills_data,
                    "reputation": char_config.get('reputation', {}),
                    "inventory": {},
                    "bank": {},
                    "gear": char_config.get('gear', {}),
                    "collectibles": char_config.get('collectibles', []),
                }
                character = Character(json.dumps(minimal_export))
        except Exception:
            pass

    # Build a minimal character if none loaded
    if character is None:
        character = Character('{"name":"Guest","game_version":"1.0","steps":0,"achievement_points":0,"coins":0,"skills":{},"reputation":{},"inventory":{},"bank":{},"gear":{},"collectibles":[]}')

    total_min = 0
    total_max = 0
    total_avg = 0
    all_we = []
    all_da = []
    segment_results = []
    seg_stats_list = []  # (steps_avg, stats, names) per segment for the drops summary

    for seg in segments:
        distance = seg.get('distance', 0)
        start_id = seg.get('start', '')
        location = _resolve_location(start_id)

        # Calculate stats with location awareness
        stats = aggregate_gearset_stats(
            items, 'travel', location, character,
            include_level_bonus=True, include_collectibles=True
        )

        we = stats.get('work_efficiency', 0.0)
        da = stats.get('double_action', 0.0)
        flat = stats.get('steps_add', 0)
        pct = stats.get('steps_percent', 0.0)
        print(f"Travel stats: segment {start_id} -> location={location}, regions={getattr(location, 'regions', None)}, WE={we:.4f}, DA={da:.4f}, flat={flat}, pct={pct:.4f}")

        # Calculate steps_per_action (same for min/max/avg - only DA varies)
        import math as _math
        # Travel formula: divisor is (2 + WE_bonus), NOT (1 + WE_bonus)
        # The base traveling efficiency is 200% (2.0), not 100% (1.0)
        # This is confirmed against the official Walkscape tool
        adjusted = distance / (2.0 + we)

        # Divide into 10 action nodes
        per_action = adjusted / 10.0

        # Apply percentage and flat step modifiers
        per_action = per_action * (1.0 + pct) + flat

        # Minimum 10 steps per action, round up
        steps_per_action = max(10, _math.ceil(per_action))

        # Max steps: 0 DA triggers (all 10 nodes paid)
        steps_max = steps_per_action * 10

        # Min steps: max DA triggers (5 free actions, only 5 paid)
        steps_min = steps_per_action * 5

        # Avg steps: expected with DA probability
        expected_paid = 10.0 / (1.0 + da)
        steps_avg = _math.ceil(expected_paid * steps_per_action)

        # Check requirements
        keyword_counts = seg.get('requirements', {}).get('keyword_counts', {})
        requirements_met = True
        keyword_fulfillment = {}
        for keyword, required_count in keyword_counts.items():
            count = sum(
                1 for item in items
                if hasattr(item, 'keywords') and
                any(keyword.lower() in kw.lower() for kw in item.keywords)
            )
            met = count >= required_count
            keyword_fulfillment[keyword] = {
                'required': required_count,
                'current': count,
                'met': met
            }
            if not met:
                requirements_met = False

        total_min += steps_min
        total_max += steps_max
        total_avg += steps_avg
        all_we.append(round(we * 100, 1))
        all_da.append(round(da * 100, 1))

        # Collect this segment's stats for the drops summary (per-segment drops
        # + whole-route Total, each with coins/AGT per 1k) computed after the
        # loop by compute_travel_drops_summary. Region = segment START.
        seg_stats_list.append({
            'steps_avg': steps_avg,
            'stats': stats,
            'start_name': seg.get('start_name', ''),
            'end_name': seg.get('end', ''),
        })

        segment_results.append({
            'start': start_id,
            'start_name': seg.get('start_name', ''),
            'end': seg.get('end', ''),
            'end_name': seg.get('end_name', ''),
            'distance': distance,
            'steps_avg': steps_avg,
            'steps_min': steps_min,
            'steps_max': steps_max,
            'work_efficiency': round(we * 100, 1),
            'double_action': round(da * 100, 1),
            'requirements_met': requirements_met,
            'requirements': seg.get('requirements', {}),
            'keyword_fulfillment': keyword_fulfillment,
            'drops': [],           # filled by the drops summary below
            'coins_per_1k': 0,
            'agt_per_1k': 0,
        })

    # Per-segment drops + whole-route Total, each with coins/AGT per 1k steps.
    drops_total = {}
    try:
        from optimize_travel_gearsets import compute_travel_drops_summary
        _summary = compute_travel_drops_summary(seg_stats_list)
        for i, so in enumerate(_summary.get('segments', [])):
            if i < len(segment_results):
                segment_results[i]['drops'] = so.get('drops', [])
                segment_results[i]['coins_per_1k'] = so.get('coins_per_1k', 0)
                segment_results[i]['agt_per_1k'] = so.get('agt_per_1k', 0)
        drops_total = _summary.get('total', {})
    except Exception as _sum_err:
        print(f"Travel stats: drops summary failed: {_sum_err!r}")

    n = max(len(segments), 1)

    return {
        'success': True,
        'total': {
            'steps_min': total_min,
            'steps_max': total_max,
            'steps_avg': total_avg,
            'work_efficiency_min': min(all_we) if all_we else 0,
            'work_efficiency_max': max(all_we) if all_we else 0,
            'double_action_min': min(all_da) if all_da else 0,
            'double_action_max': max(all_da) if all_da else 0,
        },
        'segments': segment_results,
        'drops_total': drops_total,
    }


@app.post("/api/calculate-activity-stats")
async def calculate_activity_stats(request: Request):
    """
    Calculate all stats for an activity with current gearset.
    
    Request body:
        activity_id: Activity ID
        gearset: Current gearset slots {slot: {itemId, quality}}
        location_id: Selected location ID
        consumable_id: Optional consumable ID
    
    Returns:
        Calculated stats with breakdown of contributors
    """
    from util.autogenerated.activities import Activity
    from util.gearset_utils import Gearset
    from util.autogenerated.equipment import Item
    from util.autogenerated.locations import Location
    
    body = await request.json()
    activity_id = body.get('activity_id')
    gearset_slots = body.get('gearset', {})
    location_id = body.get('location_id')
    consumable_id = body.get('consumable_id')
    
    # Find activity
    activity = None
    for attr_name in dir(Activity):
        if attr_name.startswith('_'):
            continue
        act = getattr(Activity, attr_name)
        if isinstance(act, type(Activity.REPAIR_THE_BANK)):  # ActivityInfo type
            act_id = act.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
            if act_id == activity_id:
                activity = act
                break
    
    if not activity:
        return {"error": "Activity not found"}, 404
    
    # Find location
    location = None
    if location_id:
        for attr_name in dir(Location):
            if attr_name.startswith('_'):
                continue
            loc = getattr(Location, attr_name)
            if hasattr(loc, 'name'):
                loc_id = loc.name.lower().replace(' ', '_').replace("'", '')
                if loc_id == location_id:
                    location = loc
                    break
    
    # Build gearset from slots
    # Convert UI format to Python Gearset
    items = []
    for slot, slot_data in gearset_slots.items():
        if not slot_data or not slot_data.get('itemId'):
            continue
        
        item_id = slot_data['itemId']
        quality = slot_data.get('quality')
        
        # Find item by ID
        item = Item.by_id(item_id, quality=quality)
        if item:
            items.append(item)
    
    # Create gearset from items
    gearset = Gearset.from_items(items)
    
    # Get character
    character = None
    if hasattr(request, 'state') and hasattr(request.state, 'session_uuid'):
        try:
            session = get_db().get_session(request.state.session_uuid)
            if session and session.get('character_config'):
                from ui.database import Character
                character = Character.from_dict(session['character_config'])
        except:
            pass
    
    # Calculate stats using get_total_stats
    skill = activity.primary_skill
    gear_stats = gearset.get_total_stats(skill, location=location)
    
    # Get consumable stats if provided
    consumable = None
    if consumable_id:
        # TODO: Load consumable by ID
        pass
    
    # Call get_expected_drop_rate with verbose=True to get full breakdown
    results, details = activity.get_expected_drop_rate(
        stats=gear_stats,
        location=location,
        verbose=True,
        character=character,
        consumable=consumable
    )
    
    return {
        'activity': {
            'id': activity_id,
            'name': activity.name,
            'primary_skill': activity.primary_skill
        },
        'stats': gear_stats,
        'details': details,
        'drop_rates': results
    }


@app.post("/api/comparison-stats")
async def comparison_stats(request: Request):
    """
    Calculate stats and metrics for a gearset in the context of an activity or recipe.
    Used by the comparison view to get accurate stats for both gearsets.
    
    Request body:
        gearset: {slot: {itemId, quality, is_fine, is_generic}} — gearset slots
        activity_id: str — activity ID (mutually exclusive with recipe_id)
        recipe_id: str — recipe ID (mutually exclusive with activity_id)
        service_id: str — optional service ID (for recipes)
        location: str — optional selected location ID
    
    Returns:
        stats: {stat_name: value} — aggregated stats as percentages
        metrics: {metric_name: value} — calculated metrics (steps/action, XP/step, etc.)
    """
    import json as json_mod
    from util.character_export_util import Character
    from util.autogenerated.equipment import Item
    from util.gearset_utils import aggregate_gearset_stats
    from util.activity_metrics import calculate_activity_metrics, calculate_crafting_metrics
    
    # Clear the stats cache at the start of each request to prevent cross-request
    # cache pollution. The cache key omits character context, so concurrent requests
    # can return stale results (manifests as ±0.02 WE under rapid toggling).
    from util.stats_mixin import _STATS_CACHE
    _STATS_CACHE.clear()
    
    body = await request.json()
    gearset_slots = body.get('gearset', {})
    activity_id = body.get('activity_id')
    recipe_id = body.get('recipe_id')
    service_id = body.get('service_id')
    location_id = body.get('location')
    use_fine_inputs = body.get('use_fine_inputs', False)
    
    # Load character from session
    session_uuid = request.state.session_uuid
    session = get_db().get_session(session_uuid)
    character_config = session.get('character_config') if session else None
    
    # Apply user overrides
    if character_config and session:
        ui_config = session.get('ui_config', {})
        user_overrides = ui_config.get('user_overrides', {})
        if user_overrides.get('achievement_points') is not None:
            character_config['achievement_points'] = user_overrides['achievement_points']
        if user_overrides.get('skills'):
            if 'skills' not in character_config:
                character_config['skills'] = {}
            character_config['skills'].update(user_overrides['skills'])
        if user_overrides.get('skills_xp'):
            if 'skills_xp' not in character_config:
                character_config['skills_xp'] = {}
            character_config['skills_xp'].update(user_overrides['skills_xp'])
        if user_overrides.get('reputation'):
            if 'reputation' not in character_config:
                character_config['reputation'] = {}
            character_config['reputation'].update(user_overrides['reputation'])
    
    # Build Character object
    character = None
    if character_config:
        try:
            from util.walkscape_constants import level_to_xp
            skills_xp = character_config.get('skills_xp', {})
            skills_levels = character_config.get('skills', {})
            skills_data = {}
            for skill, level in skills_levels.items():
                skills_data[skill] = level_to_xp(level)
            for skill, xp in skills_xp.items():
                skills_data[skill] = xp
            minimal_export = {
                "name": character_config.get('name', 'Player'),
                "game_version": character_config.get('game_version', '1.0'),
                "steps": character_config.get('steps', 0),
                "achievement_points": character_config.get('achievement_points', 0),
                "coins": character_config.get('coins', 0),
                "skills": skills_data,
                "reputation": character_config.get('reputation', {}),
                "inventory": {},
                "bank": {},
                "gear": character_config.get('gear', {}),
                "collectibles": character_config.get('collectibles', []),
            }
            character = Character(json_mod.dumps(minimal_export))
        except Exception:
            pass
    if character is None:
        character = Character('{"name":"Guest","game_version":"1.0","steps":0,"achievement_points":0,"coins":0,"skills":{},"reputation":{},"inventory":{},"bank":{},"gear":{},"collectibles":[]}')
    
    # Resolve activity or recipe
    activity = None
    recipe = None
    skill_name = None
    base_steps = 0
    base_xp = 0
    max_efficiency = 0.0
    activity_level = 1
    
    if activity_id:
        if activity_id.startswith('generic::'):
            # Generic activity — skip for now (edge case)
            pass
        else:
            from util.autogenerated.activities import Activity
            for attr_name in dir(Activity):
                if attr_name.startswith('_'):
                    continue
                act = getattr(Activity, attr_name)
                if hasattr(act, 'name') and hasattr(act, 'base_steps'):
                    act_id = act.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
                    if act_id == activity_id:
                        activity = act
                        skill_name = act.skill if hasattr(act, 'skill') else (act.primary_skill if hasattr(act, 'primary_skill') else 'agility')
                        base_steps = act.base_steps
                        base_xp = act.base_xp
                        max_efficiency = act.max_efficiency
                        activity_level = act.skill_requirements.get(act.primary_skill, 1) if hasattr(act, 'skill_requirements') else 1
                        break
    
    elif recipe_id:
        if recipe_id.startswith('generic::'):
            # Generic recipe — skip for now (edge case)
            pass
        else:
            from util.autogenerated.recipes import Recipe
            import util.autogenerated.recipes as recipes_module
            from util.autogenerated.recipes import RecipeInstance
            for attr_name in dir(recipes_module):
                if attr_name.startswith('_'):
                    continue
                rec = getattr(recipes_module, attr_name)
                if not isinstance(rec, RecipeInstance):
                    continue
                if attr_name.lower() == recipe_id:
                    recipe = rec
                    skill_name = rec.skill if hasattr(rec, 'skill') else 'carpentry'
                    # Smelting sub-skill: bar-smelting recipes (in SMELTING_RECIPE_NAMES)
                    # also pick up "smelting"-scoped stats (e.g. Tortoise L4 +2 bonus
                    # XP). Route them to the 'smelting' scope (Skill.SMELTING matches
                    # smithing + smelting + artisan + global); other smithing recipes
                    # are unaffected. get_skill_level aliases smelting->smithing so the
                    # level/WE/QO bonus stays correct.
                    try:
                        from util.autogenerated.pets import SMELTING_RECIPE_NAMES
                        if (skill_name or '').lower() == 'smithing' and getattr(rec, 'name', None) in SMELTING_RECIPE_NAMES:
                            skill_name = 'smelting'
                    except Exception:
                        pass
                    base_steps = rec.base_steps
                    base_xp = rec.base_xp
                    max_efficiency = rec.max_efficiency
                    activity_level = rec.level if hasattr(rec, 'level') else 1
                    break
    
    if not skill_name:
        return {"error": "Activity or recipe not found", "stats": {}, "metrics": {}}
    
    # Resolve location
    location = None
    if location_id:
        from util.autogenerated.locations import Location
        for attr_name in dir(Location):
            if attr_name.startswith('_'):
                continue
            loc = getattr(Location, attr_name)
            if hasattr(loc, 'name'):
                loc_id = loc.name.lower().replace(' ', '_').replace("'", '')
                if loc_id == location_id:
                    location = loc
                    break
    
    # Resolve gearset items
    items = []
    log(f"[comparison-stats] Received {len(gearset_slots)} slots, activity={activity_id}, recipe={recipe_id}", session_uuid)
    for slot, slot_data in gearset_slots.items():
        if not slot_data:
            continue
        item_id = slot_data.get('itemId') or slot_data.get('item_id')
        if not item_id:
            continue
        quality = slot_data.get('quality')
        is_generic = slot_data.get('is_generic', False)
        is_fine = slot_data.get('is_fine', False)
        
        if is_generic or (isinstance(item_id, str) and item_id.startswith('generic::item::')):
            # Generic item — load from DB and build a GenericItemInstance
            try:
                gen_id = item_id.replace('generic::item::', '')
                gen_data = get_db().get_generic_item_by_id(gen_id)
                if gen_data:
                    from ui.generic_definitions import GenericItemInstance
                    # _row_to_generic_item already parses JSON — keys are 'stats' and 'gated_stats'
                    # For crafted items, quality_stats[quality] is the complete stats for that quality
                    # (not incremental — base stats are the Normal quality stats, not shared base)
                    base_stats = gen_data.get('stats', {})
                    quality_stats = gen_data.get('quality_stats') or {}
                    # quality may be a quality name ("Great") or rarity name ("rare") — normalize
                    rarity_to_quality = {
                        'common': 'Normal', 'uncommon': 'Good', 'rare': 'Great',
                        'epic': 'Excellent', 'legendary': 'Perfect', 'ethereal': 'Eternal'
                    }
                    quality_name = quality
                    if quality_name and quality_name.lower() in rarity_to_quality:
                        quality_name = rarity_to_quality[quality_name.lower()]
                    if quality_name and quality_stats and quality_name in quality_stats:
                        # Use quality-specific stats directly (complete replacement, not additive)
                        stats_raw = quality_stats[quality_name]
                        log(f"[comparison-stats] Generic item '{gen_data.get('name')}' quality={quality_name}, stats keys: {list(stats_raw.keys())}", session_uuid)
                    else:
                        stats_raw = base_stats
                        log(f"[comparison-stats] Generic item '{gen_data.get('name')}' quality={quality!r} (no quality match, using base stats)", session_uuid)
                    gated_raw = gen_data.get('gated_stats', {})
                    keywords = gen_data.get('keywords', [])
                    if isinstance(keywords, str):
                        keywords = [k.strip() for k in keywords.split(',') if k.strip()]
                    gi = GenericItemInstance(
                        name=gen_data.get('name', 'Generic Item'),
                        uuid=item_id,
                        slot=gen_data.get('slot', 'head'),
                        keywords=keywords,
                        rarity=gen_data.get('rarity', 'common'),
                        _stats=stats_raw,
                    )
                    gi.gated_stats = gated_raw
                    items.append(gi)
                else:
                    log(f"[comparison-stats] Generic item not found in DB: {gen_id}", session_uuid)
            except Exception as e:
                print(f"[comparison-stats] Failed to load generic item {item_id}: {e}")
            continue
        
        # Handle fine consumable suffix
        if is_fine and item_id.endswith('_fine'):
            item_id = item_id[:-5]
        
        # Try UUID lookup first
        item = None
        uuid = slot_data.get('uuid')
        if uuid:
            rarity = quality
            if quality and quality in ('Normal', 'Good', 'Great', 'Excellent', 'Perfect', 'Eternal'):
                quality_to_rarity = {
                    'Normal': 'common', 'Good': 'uncommon', 'Great': 'rare',
                    'Excellent': 'epic', 'Perfect': 'legendary', 'Eternal': 'ethereal'
                }
                rarity = quality_to_rarity.get(quality, quality)
            item = Item.by_uuid(uuid, quality=rarity)
        
        # Fallback: try name-based lookup via enum attributes
        if not item:
            name = slot_data.get('name', '')
            if name:
                # Search through Item class attributes
                for attr_name in dir(Item):
                    if attr_name.startswith('_'):
                        continue
                    attr = getattr(Item, attr_name)
                    if hasattr(attr, 'name') and attr.name == name:
                        if quality and hasattr(attr, 'NORMAL'):
                            # CraftedItem — get quality variant
                            quality_attr = quality.upper()
                            variant = getattr(attr, quality_attr, None)
                            if variant:
                                item = variant
                            else:
                                item = attr
                        else:
                            item = attr
                        break
        
        if item:
            items.append(item)
        else:
            # Try pet lookup (pets aren't in Item class)
            try:
                from util.autogenerated.pets import Pet as PetLookup, PETS_BY_NAME
                pet_name = slot_data.get('name', '')
                pet_level = slot_data.get('level', 0)
                use_ability = slot_data.get('useAbility', False)
                found_pet = None
                # Try enum name first
                pet_enum = item_id.upper()
                if hasattr(PetLookup, pet_enum):
                    found_pet = getattr(PetLookup, pet_enum)
                if not found_pet:
                    for pn, pl in PETS_BY_NAME.items():
                        if pn.lower().replace(' ', '_').replace("'", '') == item_id:
                            found_pet = pl
                            break
                if found_pet and hasattr(found_pet, 'get_level') and pet_level and int(pet_level) > 0:
                    level_info = found_pet.get_level(int(pet_level))
                    if level_info:
                        # If useAbility is checked, merge ability stats
                        if use_ability and level_info.abilities:
                            import copy
                            level_info = copy.copy(level_info)
                            merged_stats = copy.deepcopy(level_info._stats) if hasattr(level_info, '_stats') else {}
                            for ability in level_info.abilities:
                                ability_stats = ability.get('ability_stats', {})
                                if ability_stats:
                                    for sk, locs in ability_stats.items():
                                        if sk not in merged_stats:
                                            merged_stats[sk] = {}
                                        for loc, sv in locs.items():
                                            if loc not in merged_stats[sk]:
                                                merged_stats[sk][loc] = {}
                                            for st, v in sv.items():
                                                merged_stats[sk][loc][st] = merged_stats[sk][loc].get(st, 0) + v
                            level_info._stats = merged_stats
                        items.append(level_info)
            except Exception as e:
                print(f"[comparison-stats] Failed pet lookup for {item_id}: {e}")
            
            # Try consumable lookup by name (consumables aren't in Item class)
            try:
                from util.autogenerated.consumables import Consumable, ConsumableItem
                cname = slot_data.get('name', '')
                for cattr_name in dir(Consumable):
                    if cattr_name.startswith('_'):
                        continue
                    cattr = getattr(Consumable, cattr_name)
                    if isinstance(cattr, ConsumableItem) and cattr.name == cname:
                        items.append(cattr)
                        break
            except Exception:
                pass
    
    # Add service stats if applicable (for recipes)
    service_stats = {}
    if service_id and recipe_id:
        if service_id.startswith('generic::'):
            # Generic service — skip for now (edge case)
            pass
        else:
            try:
                from util.autogenerated.services import Service, ServiceInstance
                for attr_name in dir(Service):
                    if attr_name.startswith('_'):
                        continue
                    svc = getattr(Service, attr_name)
                    if isinstance(svc, ServiceInstance):
                        svc_id = svc.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
                        # Also try with location suffix
                        loc_name = svc.location.name if hasattr(svc.location, 'name') else ''
                        svc_id_with_loc = (svc.name + '_' + loc_name).lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
                        if svc_id == service_id or svc_id_with_loc == service_id:
                            # Get service stats for the recipe's skill
                            svc_stats = svc.attr(skill_name, location=location)
                            for stat_name, val in svc_stats.items():
                                service_stats[stat_name] = service_stats.get(stat_name, 0) + val
                            break
            except Exception as e:
                print(f"[comparison-stats] Failed to load service {service_id}: {e}")
    
    # Calculate aggregated stats using the proven Python backend
    total_stats = aggregate_gearset_stats(
        items=items,
        skill=skill_name,
        location=location,
        character=character,
        include_level_bonus=True,
        include_collectibles=True,
        activity_level=activity_level
    )
    
    log(f"[comparison-stats] {len(items)} items, skill={skill_name}, location={location}, WE={total_stats.get('work_efficiency', 0):.4f}, activity_level={activity_level}, items={[getattr(i,'name','?') for i in items]}", session_uuid)
    log(f"[comparison-stats] QO={total_stats.get('quality_outcome', 0)}, service_stats={service_stats}", session_uuid)
    
    # Add service stats
    for stat_name, val in service_stats.items():
        total_stats[stat_name] = total_stats.get(stat_name, 0) + val
    
    log(f"[comparison-stats] After service: QO={total_stats.get('quality_outcome', 0)}", session_uuid)
    
    # Add fine input bonus if enabled (same bonuses as the main view)
    if use_fine_inputs and activity_id:
        # Check if the activity has input_items (keyword-type inputs that can be fine)
        if activity and hasattr(activity, 'input_items') and activity.input_items:
            has_keyword_input = any(getattr(ii, 'type', '') == 'keyword' for ii in activity.input_items)
            if has_keyword_input:
                total_stats['work_efficiency'] = total_stats.get('work_efficiency', 0) + 0.40
                total_stats['double_rewards'] = total_stats.get('double_rewards', 0) + 0.10
                total_stats['bonus_xp_percent'] = total_stats.get('bonus_xp_percent', 0) + 1.00
                total_stats['fine_material_finding'] = total_stats.get('fine_material_finding', 0) + 2.00
    
    # Add input item stats (items selected in input slots contribute their stats)
    input_items_data = body.get('input_items', [])
    if input_items_data and activity_id:
        log(f"[comparison-stats] Processing {len(input_items_data)} input items", session_uuid)
        for input_item_data in input_items_data:
            input_item_id = input_item_data.get('item_id')
            input_name = input_item_data.get('name', '')
            input_is_generic = input_item_data.get('is_generic', False)
            log(f"[comparison-stats] Input item: id={input_item_id}, name={input_name}, generic={input_is_generic}", session_uuid)
            if not input_item_id:
                continue
            try:
                input_item_obj = None
                if input_is_generic:
                    gen_id = input_item_id if input_item_id.startswith('generic::') else f'generic::{input_item_id}'
                    gen_data = get_db().get_generic_definition(gen_id)
                    if gen_data:
                        from ui.generic_definitions import GenericItemInstance
                        gi = GenericItemInstance(
                            name=gen_data.get('name', ''),
                            _stats=gen_data.get('stats', {}),
                            gated_stats=gen_data.get('gated_stats', {}),
                            keywords=gen_data.get('keywords', []),
                            slot=gen_data.get('slot', 'tool'),
                            uuid=gen_id,
                            rarity=gen_data.get('rarity', 'common'),
                            requirements=gen_data.get('requirements', [])
                        )
                        input_item_obj = gi
                else:
                    # Try Item (equipment) by UUID first
                    input_item_obj = Item.by_uuid(input_item_id)
                    # Try Material module (arrows, etc. are materials)
                    if not input_item_obj:
                        from util.autogenerated.materials import Material, MaterialInstance
                        input_item_obj = Material.by_export_name(input_item_id)
                        if not input_item_obj:
                            for attr_name in dir(Material):
                                if attr_name.startswith('_'):
                                    continue
                                mat = getattr(Material, attr_name)
                                if isinstance(mat, MaterialInstance) and hasattr(mat, 'name'):
                                    if mat.name == input_name:
                                        input_item_obj = mat
                                        break
                    # Try Consumable module
                    if not input_item_obj:
                        from util.autogenerated.consumables import Consumable
                        for attr_name in dir(Consumable):
                            if attr_name.startswith('_'):
                                continue
                            cons = getattr(Consumable, attr_name)
                            if hasattr(cons, 'name') and cons.name == input_name:
                                input_item_obj = cons
                                break
                    log(f"[comparison-stats] Resolved input item: {getattr(input_item_obj, 'name', 'NOT FOUND')} (type={type(input_item_obj).__name__})", session_uuid)
                
                if input_item_obj and hasattr(input_item_obj, 'attr'):
                    input_stats = input_item_obj.attr(skill_name, location=location)
                    log(f"[comparison-stats] Input item stats for {skill_name}/{location}: {input_stats}", session_uuid)
                    for stat_name, val in input_stats.items():
                        if val and val != 0:
                            # Stats from .attr() are in decimal form (0.10 = 10%)
                            # total_stats is also in decimal form — add directly
                            total_stats[stat_name] = total_stats.get(stat_name, 0) + val
            except Exception as e:
                print(f"[comparison-stats] Failed to load input item {input_item_id}: {e}")
    
    # Calculate metrics
    metrics = {}
    if activity_id:
        metrics = calculate_activity_metrics(
            base_steps=base_steps,
            base_xp=base_xp,
            max_efficiency=max_efficiency,
            total_stats=total_stats
        )
    elif recipe_id:
        metrics = calculate_crafting_metrics(
            base_steps=base_steps,
            base_xp=base_xp,
            max_efficiency=max_efficiency,
            total_stats=total_stats
        )
    
    # Convert stats to percentage format for frontend (backend uses decimals for percentage stats)
    # Non-percentage stats (steps_add, bonus_xp_add, quality_outcome, inventory_space) stay as-is
    from util.attributes import Attribute
    percentage_stats = set()
    for attr in Attribute:
        if attr.value.is_percentage:
            percentage_stats.add(attr.value.internal_name)
    
    stats_pct = {}
    for k, v in total_stats.items():
        if k in percentage_stats:
            stats_pct[k] = v * 100.0
        else:
            stats_pct[k] = v
    
    return {
        "stats": stats_pct,
        "metrics": metrics,
        "skill": skill_name,
        "base_steps": base_steps,
        "base_xp": base_xp,
        "max_efficiency": max_efficiency,
        "activity_level": activity_level,
    }


@app.get("/api/recipes")
async def get_recipes(request: Request, response: Response):
    """
    Get all recipes organized by skill.
    
    Returns recipes with:
    - Materials as array of alternative groups
    - has_fine_option flag (true if recipe uses only materials/consumables)
    - Base stats (steps, xp, max efficiency)
    - Service type required
    
    Returns:
        Dict with recipes organized by skill category
    """
    from util.autogenerated.recipes import RecipeInstance
    from util.autogenerated.materials import Material
    from util.autogenerated.consumables import Consumable
    from util.autogenerated.equipment import Item
    import util.autogenerated.recipes as recipes_module
    from util.coin_value import CHEST_COIN_VALUES
    from util.shell_value import CHEST_SHELL_VALUES

    def _enrich_recipe_drop(d):
        """Add `coin_value` and `shell_value` to a recipe drop_table entry
        so the drops-section currency pills can sum them without looking
        up the item catalog client-side. Side-drop materials (Silver
        nugget, Mummy egg, ...) use their base .value; Container refs
        use CHEST_COIN_VALUES / CHEST_SHELL_VALUES. Mutates a copy of
        the input dict; the source stays untouched.
        """
        out = dict(d) if isinstance(d, dict) else d
        if not isinstance(out, dict):
            return out
        try:
            ref = (out.get('item_ref') or '')
            if ref.startswith('Container.'):
                out['coin_value'] = float(CHEST_COIN_VALUES.get(ref, 0) or 0)
                if ref in CHEST_SHELL_VALUES:
                    out['shell_value'] = float(CHEST_SHELL_VALUES[ref])
            elif ref == 'Currency.COIN':
                out['coin_value'] = 1
            elif ref == 'Material.SEA_SHELL':
                _attr = ref.split('.', 1)[1]
                if hasattr(Material, _attr):
                    out['coin_value'] = float(getattr(Material, _attr).value or 0)
                _fine = _attr + '_FINE'
                if hasattr(Material, _fine):
                    out['fine_coin_value'] = float(getattr(Material, _fine).value or 0)
                out['shell_value'] = 1.0
                out['fine_shell_value'] = 10.0  # Material.SEA_SHELL_FINE.special_sell qty
            elif ref == 'Material.SEA_SHELL_FINE':
                _attr = ref.split('.', 1)[1]
                if hasattr(Material, _attr):
                    out['coin_value'] = float(getattr(Material, _attr).value or 0)
                out['shell_value'] = 10.0
            elif ref.startswith('Material.'):
                _attr = ref.split('.', 1)[1]
                if hasattr(Material, _attr):
                    out['coin_value'] = float(getattr(Material, _attr).value or 0)
                # Fine variant value — drops-section uses this to add the
                # fine contribution to the coin pill when FMF is active.
                _fine = _attr + '_FINE'
                if hasattr(Material, _fine):
                    out['fine_coin_value'] = float(getattr(Material, _fine).value or 0)
            elif ref.startswith('Item.'):
                _attr = ref.split('.', 1)[1]
                if hasattr(Item, _attr):
                    out['coin_value'] = float(getattr(Item, _attr).value or 0)
            elif ref.startswith('Consumable.'):
                _attr = ref.split('.', 1)[1]
                if hasattr(Consumable, _attr):
                    _o = getattr(Consumable, _attr)
                    out['coin_value'] = float(getattr(_o, 'value', 0) or 0)
                _fine = _attr + '_FINE'
                if hasattr(Consumable, _fine):
                    out['fine_coin_value'] = float(getattr(Consumable, _fine).value or 0)
        except Exception:
            pass
        return out

    # Set cache headers via _maybe_static_304: returns 304 (no body) when the
    # client's If-None-Match matches our ETag, else sets ETag + Cache-Control.
    cached = _maybe_static_304(request, response, "recipes")
    if cached:
        return cached
    
    # Collect all recipes
    recipes_by_skill = {}
    all_recipes = []
    
    for attr_name in dir(recipes_module):
        if attr_name.startswith('_'):
            continue
        
        recipe = getattr(recipes_module, attr_name)
        if not isinstance(recipe, RecipeInstance):
            continue
        
        # Generate recipe ID from attribute name
        recipe_id = attr_name.lower()
        
        # Build materials as array of alternative groups
        # Each group is an array of {material_id, material_name, quantity, type}
        material_groups = []
        has_fine_option = True  # Assume true, set to false if equipment found
        has_equipment_input = False  # Track if recipe uses equipment as input
        
        for group in recipe.materials:
            group_materials = []
            for qty, material_obj in group:
                # Determine material type and name
                material_type = 'unknown'
                material_name = str(material_obj)
                material_id = ''
                material_icon_name = ''
                
                if isinstance(material_obj, type(Material.BIRCH_LOGS)) if hasattr(Material, 'BIRCH_LOGS') else False:
                    material_type = 'material'
                    material_name = material_obj.name
                    material_id = material_obj.name.lower().replace(' ', '_').replace("'", '')
                    material_icon_name = material_obj.name.replace(' ', '_').lower()  # Lowercase for icon filename
                elif hasattr(material_obj, 'name'):
                    material_name = material_obj.name
                    # Keep apostrophes for icon paths, but create a clean ID for lookups
                    material_id = material_name.lower().replace(' ', '_').replace('(', '').replace(')', '')
                    material_icon_name = material_name.replace(' ', '_').lower()  # Lowercase for icon filename
                    
                    # Check type by module
                    obj_module = type(material_obj).__module__
                    if 'material' in obj_module:
                        material_type = 'material'
                    elif 'consumable' in obj_module:
                        material_type = 'consumable'
                    elif 'equipment' in obj_module:
                        material_type = 'equipment'
                        has_equipment_input = True  # Recipe uses equipment as input
                    else:
                        # Try to detect by class name
                        class_name = type(material_obj).__name__
                        if 'Material' in class_name:
                            material_type = 'material'
                        elif 'Consumable' in class_name:
                            material_type = 'consumable'
                        elif 'Item' in class_name:
                            material_type = 'equipment'
                            has_equipment_input = True
                
                # Coin sell value of this material — powers the "materials
                # cost" row in the coins/1k-steps breakdown dropdown. Flat
                # value regardless of quality (materials have no per-
                # quality pricing, unlike equipment).
                try:
                    material_value = float(getattr(material_obj, 'value', 0) or 0)
                except (TypeError, ValueError):
                    material_value = 0.0

                group_materials.append({
                    'material_id': material_id,
                    'material_name': material_name,
                    'material_icon_name': material_icon_name,  # Icon filename with apostrophes
                    'quantity': qty,
                    'type': material_type,
                    'value': material_value,
                })
            
            material_groups.append(group_materials)
        
        # Build icon path - use output item icon
        # Resolve output_item to get the correct icon path
        icon_path = f"/assets/icons/items/equipment/{recipe_id}.svg"  # Default fallback
        
        output_item_name = None
        
        if recipe.output_item:
            # Parse output_item string like "Material.PINE_PLANK" or "Item.IRON_SICKLE"
            try:
                if "." in recipe.output_item:
                    class_name, attr_name = recipe.output_item.split(".", 1)
                    
                    # Get the actual object
                    output_obj = None
                    if class_name == "Material":
                        output_obj = getattr(Material, attr_name, None)
                        if output_obj:
                            # Use material icon
                            item_name = output_obj.name.replace(' (Fine)', '')  # Remove fine suffix
                            output_item_name = item_name
                            icon_filename = item_name.replace(' ', '_').lower() + '.svg'
                            icon_path = f"/assets/icons/items/materials/{icon_filename}"
                    elif class_name == "Item":
                        output_obj = getattr(Item, attr_name, None)
                        if output_obj:
                            output_item_name = output_obj.name
                            # Use equipment icon
                            icon_filename = output_obj.name.replace(' ', '_').lower() + '.svg'
                            icon_path = f"/assets/icons/items/equipment/{icon_filename}"
                    elif class_name == "Consumable":
                        output_obj = getattr(Consumable, attr_name, None)
                        if output_obj:
                            # Use consumable icon
                            item_name = output_obj.name.replace(' (Fine)', '')  # Remove fine suffix
                            output_item_name = item_name
                            icon_filename = item_name.replace(' ', '_').lower() + '.svg'
                            icon_path = f"/assets/icons/items/consumables/{icon_filename}"
            except Exception as e:
                # Note: No session UUID available in this endpoint (static data)
                log(f"Warning: Failed to resolve output_item '{recipe.output_item}' for recipe '{recipe.name}': {e}")
        else:
            # output_item is None — default fallback to equipment
            pass
        
        # Enrich drop_table entries with has_fine_material flag so the UI can
        # render the fine variant row (e.g. Silver nugget Fine) and apply FMF
        # bonuses the same way activity drops do.
        _drop_table = []
        for _drop in (recipe.drop_table or []):
            _d = dict(_drop)
            _has_fine = False
            try:
                _ref = _d.get('item_ref') or ''
                if _ref.startswith('Material.'):
                    from util.autogenerated.materials import Material as _Mat
                    _base_attr = _ref.split('.', 1)[1]
                    _fine_attr = f'{_base_attr}_FINE'
                    if hasattr(_Mat, _fine_attr):
                        _has_fine = True
            except Exception:
                _has_fine = False
            _d['has_fine_material'] = _has_fine
            _drop_table.append(_d)

        recipe_data = {
            'id': recipe_id,
            'name': recipe.name,
            'skill': recipe.skill,
            'level': recipe.level,
            'service_type': recipe.service,
            'quantity': recipe.quantity,
            'output_item': recipe.output_item,  # Add output_item for quality check
            'output_item_name': output_item_name,  # Resolved display name for wiki links
            'materials': material_groups,
            'has_fine_option': has_fine_option,
            'has_equipment_input': has_equipment_input,
            'base_xp': recipe.base_xp,
            'base_steps': recipe.base_steps,
            'max_efficiency': recipe.max_efficiency,
            'icon_path': icon_path,
            'drop_table': [_enrich_recipe_drop(d) for d in _drop_table],
        }
        
        # Enrich with output sell value so the drops-section coin pill can
        # render the quality-weighted coins/1k-steps line for recipes the
        # same way it does for activities. Equipment outputs get a per-
        # quality values dict; materials/consumables collapse to a single
        # base value (no quality tier variance).
        try:
            _out_obj = recipe.get_output_item_object()
        except Exception:
            _out_obj = None
        if _out_obj is not None:
            recipe_data['output_coin_value'] = float(getattr(_out_obj, 'value', 0) or 0)
            _qv = getattr(_out_obj, '_quality_values', None)
            if _qv:
                recipe_data['output_quality_values'] = dict(_qv)
        else:
            recipe_data['output_coin_value'] = 0
        
        all_recipes.append(recipe_data)
        
        # Organize by skill
        skill = recipe.skill
        if skill not in recipes_by_skill:
            recipes_by_skill[skill] = []
        recipes_by_skill[skill].append(recipe_data)
    
    # Sort recipes within each skill alphabetically (case-insensitive)
    for skill in recipes_by_skill:
        recipes_by_skill[skill].sort(key=lambda x: x['name'].lower())
    
    # Sort skills alphabetically
    sorted_skills = sorted(recipes_by_skill.keys())
    sorted_by_skill = {skill: recipes_by_skill[skill] for skill in sorted_skills}
    
    return {
        'recipes': all_recipes,
        'by_skill': sorted_by_skill,
        'count': len(all_recipes)
    }


@app.get("/api/item-sources")
async def get_item_sources(request: Request, response: Response):
    """
    Build a reverse lookup: item/material name → list of sources.
    
    Sources include:
    - Activities that drop the item (with skill, level, base_steps, drop_rate)
    - Activities that drop the item via item finding categories
    - Recipes that produce the item (with skill, level, base_steps)
    - Recipes that consume the item as a material (with skill, level, base_steps)
    
    Returns:
        Dict mapping lowercase item names to lists of source objects.
    """
    from util.autogenerated.activities import Activity, ActivityInfo
    import util.autogenerated.recipes as recipes_module
    from util.autogenerated.recipes import RecipeInstance
    from util.autogenerated.item_finding import ItemFindingCategory, CategoryInstance
    
    cached = _maybe_static_304(request, response, "item-sources")
    if cached:
        return cached
    
    sources = {}  # lowercase item name -> list of sources
    
    def add_source(item_name, source):
        key = item_name.lower().strip()
        if key not in sources:
            sources[key] = []
        # Avoid duplicates
        for existing in sources[key]:
            if existing.get('id') == source.get('id') and existing.get('type') == source.get('type'):
                # For item_finding_drop, also check category to avoid dupes
                if source.get('type') == 'item_finding_drop':
                    if existing.get('category') == source.get('category'):
                        return
                else:
                    return
        sources[key].append(source)
    
    # --- Build item finding category → items reverse map ---
    # Maps category constant name → list of (item_name, chance_percent)
    category_items = {}
    for cat_attr in dir(ItemFindingCategory):
        if cat_attr.startswith('_'):
            continue
        cat = getattr(ItemFindingCategory, cat_attr)
        if not isinstance(cat, CategoryInstance):
            continue
        for drop in cat.drops:
            if drop.item_name and drop.item_name != 'Nothing':
                if cat_attr not in category_items:
                    category_items[cat_attr] = []
                category_items[cat_attr].append((drop.item_name, drop.chance_percent, cat.name))
    
    # --- Activities ---
    for attr_name in dir(Activity):
        if attr_name.startswith('_'):
            continue
        activity = getattr(Activity, attr_name)
        if not isinstance(activity, ActivityInfo):
            continue
        
        activity_id = activity.name.lower().replace(' ', '_').replace('(', '').replace(')', '').replace('-', '_').replace("'", '')
        skill = activity.primary_skill or 'Other'
        
        # Skill level requirement (primary skill)
        skill_level = activity.skill_requirements.get(skill.lower(), activity.skill_requirements.get(skill, 0))
        if skill_level == 0:
            # Try any skill requirement
            for s, lv in activity.skill_requirements.items():
                if lv > 0:
                    skill_level = lv
                    break
        
        # Process primary drop table
        for drop in activity.drop_table:
            if drop.item_name == 'Nothing':
                continue
            chance = drop.chance_percent
            
            source_entry = {
                'type': 'activity_drop',
                'id': activity_id,
                'name': activity.name,
                'skill': skill,
                'level': skill_level,
                'base_steps': activity.base_steps,
                'drop_rate': round(chance, 2) if chance else None,
            }
            add_source(drop.item_name, source_entry)
            
            # Also add fine version if applicable
            if drop.item_ref and drop.item_ref.startswith('Material.'):
                try:
                    from util.autogenerated.materials import Material
                    mat_attr = drop.item_ref.split('.', 1)[1]
                    fine_attr = mat_attr + '_FINE'
                    if hasattr(Material, fine_attr):
                        fine_name = getattr(Material, fine_attr).name
                        fine_source = dict(source_entry)
                        fine_source['drop_rate'] = None  # Fine rate is derived
                        add_source(fine_name, fine_source)
                except Exception:
                    pass
        
        # Process secondary drop table
        for drop in activity.secondary_drop_table:
            if drop.item_name == 'Nothing':
                continue
            chance = drop.chance_percent
            
            source_entry = {
                'type': 'activity_drop',
                'id': activity_id,
                'name': activity.name,
                'skill': skill,
                'level': skill_level,
                'base_steps': activity.base_steps,
                'drop_rate': round(chance, 2) if chance else None,
                'secondary': True,
            }
            add_source(drop.item_name, source_entry)
    
    # --- Item Finding Categories ---
    # Items that drop via item finding (equipment stats like ItemFindingCategory.FIBROUS_PLANT)
    # These aren't tied to specific activities — they drop from any activity when wearing
    # gear with the corresponding item finding stat.
    for cat_const, items_in_cat in category_items.items():
        for item_name, item_chance, cat_display_name in items_in_cat:
            add_source(item_name, {
                'type': 'item_finding',
                'category': cat_display_name,
                'category_id': cat_const,
                'chance_in_category': round(item_chance, 2) if item_chance else None,
            })
            # Also add fine version
            try:
                from util.autogenerated.materials import Material
                mat_attr = item_name.upper().replace(' ', '_').replace("'", '').replace('-', '_')
                fine_attr = mat_attr + '_FINE'
                if hasattr(Material, fine_attr):
                    fine_name = getattr(Material, fine_attr).name
                    add_source(fine_name, {
                        'type': 'item_finding',
                        'category': cat_display_name,
                        'category_id': cat_const,
                        'chance_in_category': None,  # Fine rate is derived from FMF stat
                    })
            except Exception:
                pass
    
    # --- Recipes ---
    for attr_name in dir(recipes_module):
        if attr_name.startswith('_'):
            continue
        recipe = getattr(recipes_module, attr_name)
        if not isinstance(recipe, RecipeInstance):
            continue
        
        recipe_id = attr_name.lower()
        
        # Recipe produces an output item
        if recipe.output_item:
            try:
                parts = recipe.output_item.split('.', 1)
                if len(parts) == 2:
                    cls_name, item_attr = parts
                    obj = None
                    if cls_name == 'Material':
                        from util.autogenerated.materials import Material
                        obj = getattr(Material, item_attr, None)
                    elif cls_name == 'Item':
                        from util.autogenerated.equipment import Item
                        obj = getattr(Item, item_attr, None)
                    elif cls_name == 'Consumable':
                        from util.autogenerated.consumables import Consumable
                        obj = getattr(Consumable, item_attr, None)
                    
                    if obj and hasattr(obj, 'name'):
                        add_source(obj.name, {
                            'type': 'recipe_output',
                            'id': recipe_id,
                            'name': recipe.name,
                            'skill': recipe.skill,
                            'level': recipe.level,
                            'base_steps': recipe.base_steps,
                        })
                        # Also add fine version for materials
                        if cls_name == 'Material':
                            fine_attr = item_attr + '_FINE'
                            if hasattr(Material, fine_attr):
                                fine_obj = getattr(Material, fine_attr)
                                add_source(fine_obj.name, {
                                    'type': 'recipe_output',
                                    'id': recipe_id,
                                    'name': recipe.name,
                                    'skill': recipe.skill,
                                    'level': recipe.level,
                                    'base_steps': recipe.base_steps,
                                })
            except Exception:
                pass
        
        # Recipe drop table (secondary drops like pet eggs)
        if recipe.drop_table:
            for drop in recipe.drop_table:
                drop_name = drop.get('item_name')
                if drop_name and drop_name != 'Nothing':
                    add_source(drop_name, {
                        'type': 'recipe_drop',
                        'id': recipe_id,
                        'name': recipe.name,
                        'skill': recipe.skill,
                        'level': recipe.level,
                        'base_steps': recipe.base_steps,
                        'drop_rate': round(drop.get('chance_percent', 0), 2) if drop.get('chance_percent') else None,
                    })
        
        # Recipe consumes materials
        for group in recipe.materials:
            for qty, mat_obj in group:
                if hasattr(mat_obj, 'name'):
                    add_source(mat_obj.name, {
                        'type': 'recipe_input',
                        'id': recipe_id,
                        'name': recipe.name,
                        'skill': recipe.skill,
                        'level': recipe.level,
                        'base_steps': recipe.base_steps,
                        'quantity': qty,
                    })
    
    # --- Containers (Chests) ---
    from util.autogenerated.containers import Container, ContainerInfo, ROLLS_PER_CHEST

    RARITY_TABLE_NAMES = {
        'main_table': None,
        'valuables_table': 'valuables',
        'common_table': 'common',
        'uncommon_table': 'uncommon',
        'rare_table': 'rare',
        'epic_table': 'epic',
        'legendary_table': 'legendary',
        'ethereal_table': 'ethereal',
    }

    for attr_name in dir(Container):
        if attr_name.startswith('_'):
            continue
        container = getattr(Container, attr_name)
        if not isinstance(container, ContainerInfo):
            continue

        for table_attr, rarity in RARITY_TABLE_NAMES.items():
            table = getattr(container, table_attr, None)
            if not table:
                continue
            for drop in table:
                if not drop.item_name or drop.item_name == 'Nothing':
                    continue
                chance_per_roll = drop.chance_percent
                qty = drop.quantity
                qty_display = f"{qty.min_qty}-{qty.max_qty}" if qty and qty.min_qty != qty.max_qty else (str(qty.min_qty) if qty else '1')
                add_source(drop.item_name, {
                    'type': 'container_drop',
                    'name': container.name,
                    'container_type': container.container_type,
                    'rarity': rarity,
                    'drop_rate': round(chance_per_roll, 4) if chance_per_roll else None,
                    'rolls_per_chest': ROLLS_PER_CHEST,
                    'quantity': qty_display,
                })

    # --- Shops ---
    from util.autogenerated.shops import ALL_SHOPS
    
    for shop in ALL_SHOPS:
        for shop_item in shop.inventory:
            if shop_item.item_type in ('Cosmetic',):
                continue  # Skip cosmetics
            
            # Format price display
            if shop_item.currency == 'coins':
                price_display = f"{shop_item.price:,} coins"
            elif shop_item.currency == 'adventurers_guild_token':
                price_display = f"{shop_item.price} AG tokens"
            else:
                price_display = f"{shop_item.price} {shop_item.currency}"
            
            add_source(shop_item.item_name, {
                'type': 'shop',
                'name': shop.name,
                'location': shop.location,
                'region': shop.region,
                'price': shop_item.price,
                'currency': shop_item.currency,
                'price_display': price_display,
                'stock': shop_item.stock,
                'item_type': shop_item.item_type,
            })
    
    return {
        'sources': sources,
        'count': len(sources)
    }


@app.get("/api/container/{container_name}")
async def get_container_details(container_name: str, response: Response):
    """
    Get full details for a container (chest) — all drops grouped by rarity table.

    Used by the drops-section popover when hovering a container card.
    Lookup is by display name (case-insensitive), e.g. "Agility chest", "Bird nest".

    Returns:
        - name: display name
        - container_type: "skill_chest" or "unique_openable"
        - rolls_per_chest: number of rolls per chest opening
        - tables: list of {rarity, drops} where drops contain item_name, item_ref,
                  chance_per_roll (percent), chance_per_chest (percent, 1-(1-p)^N),
                  min_qty, max_qty, quantity_display
    """
    from util.autogenerated.containers import (
        Container,
        ContainerInfo,
        CONTAINERS_BY_NAME,
        ROLLS_PER_CHEST,
    )

    # Case-insensitive lookup against display names
    search = container_name.strip().lower()
    container: Optional[ContainerInfo] = None
    for display_name, cinfo in CONTAINERS_BY_NAME.items():
        if display_name.lower() == search:
            container = cinfo
            break

    if container is None:
        raise HTTPException(status_code=404, detail=f"Container not found: {container_name}")

    # Table ordering and rarity labels (main_table gets no rarity — shown as "Main")
    TABLE_ORDER = [
        ('main_table', 'main'),
        ('valuables_table', 'valuables'),
        ('common_table', 'common'),
        ('uncommon_table', 'uncommon'),
        ('rare_table', 'rare'),
        ('epic_table', 'epic'),
        ('legendary_table', 'legendary'),
        ('ethereal_table', 'ethereal'),
    ]

    tables = []
    for attr_name, rarity in TABLE_ORDER:
        table = getattr(container, attr_name, None)
        if not table:
            continue
        drops_out = []
        for drop in table:
            if not drop.item_name or drop.item_name == 'Nothing':
                continue
            qty = drop.quantity
            if qty is None:
                min_qty, max_qty, qty_display = 1, 1, '1'
            else:
                min_qty = qty.min_qty if qty.min_qty is not None else 1
                max_qty = qty.max_qty if qty.max_qty is not None else min_qty
                qty_display = (
                    f"{min_qty}-{max_qty}" if min_qty != max_qty else str(min_qty)
                )

            chance_per_roll = drop.chance_percent or 0.0
            # Probability of getting at least one across ROLLS_PER_CHEST rolls
            chance_per_chest = (
                (1.0 - pow(1.0 - chance_per_roll / 100.0, ROLLS_PER_CHEST)) * 100.0
                if chance_per_roll > 0
                else 0.0
            )

            drops_out.append({
                'item_name': drop.item_name,
                'item_ref': drop.item_ref,
                'chance_per_roll': round(chance_per_roll, 4),
                'chance_per_chest': round(chance_per_chest, 4),
                'min_qty': min_qty,
                'max_qty': max_qty,
                'quantity_display': qty_display,
            })

        if drops_out:
            tables.append({
                'rarity': rarity,
                'drops': drops_out,
            })

    response.headers['Cache-Control'] = 'public, max-age=3600'
    return {
        'name': container.name,
        'container_type': container.container_type,
        'rolls_per_chest': ROLLS_PER_CHEST,
        'tables': tables,
    }


@app.get("/api/services")
async def get_services(request: Request, response: Response):
    """
    Get all services with unlock requirements.
    
    Returns services with:
    - Tier (Basic/Advanced)
    - Category (Carpentry, Cooking, etc.)
    - Location
    - Stats bonuses
    - Requirements (skill, reputation, keyword counts)
    
    Returns:
        Dict with services organized by category
    """
    from util.autogenerated.services import Service, ServiceInstance
    
    cached = _maybe_static_304(request, response, "services")
    if cached:
        return cached
    
    # Collect all services
    services_by_category = {}
    all_services = []
    
    for attr_name in dir(Service):
        if attr_name.startswith('_'):
            continue
        
        service = getattr(Service, attr_name)
        if not isinstance(service, ServiceInstance):
            continue
        
        # Generate service ID from attribute name
        service_id = attr_name.lower()
        
        # Get category name
        category = service.category.value if hasattr(service.category, 'value') else str(service.category)
        
        # Get location info
        location_data = None
        if service.location:
            loc = service.location
            location_data = {
                'id': loc.name.lower().replace(' ', '_').replace("'", ''),
                'name': loc.name,
                'regions': loc.regions if hasattr(loc, 'regions') else [],
                'is_underwater': loc.is_underwater if hasattr(loc, 'is_underwater') else False,
                'icon_name': loc.icon_name if hasattr(loc, 'icon_name') else None
            }
        
        # Build requirements
        requirements = {
            'skill': service.requirements.get('skill', {}),
            'reputation': service.requirements.get('reputation', {}),
            'keyword_counts': service.requirements.get('keyword_counts', {}),
            'access': service.requirements.get('access', [])
        }
        
        # Build stats - keep nested structure for frontend
        stats = service._stats if service._stats else {}
        
        # Build gated stats (reputation-based bonuses)
        gated_stats = {}
        if service.gated_stats:
            gated_stats = service.gated_stats
        
        # Determine if Basic or Advanced
        tier_lower = service.tier.lower()
        is_basic = 'basic' in tier_lower
        is_advanced = 'advanced' in tier_lower
        
        service_data = {
            'id': service_id,
            'name': service.name,
            'display_name': f"{service.name} ({service.location.name})" if service.location else service.name,
            'category': category,
            'tier': service.tier,
            'is_basic': is_basic,
            'is_advanced': is_advanced,
            'location': location_data,
            'requirements': requirements,
            'stats': stats,
            'gated_stats': gated_stats
        }
        
        all_services.append(service_data)
        
        # Organize by category
        if category not in services_by_category:
            services_by_category[category] = []
        services_by_category[category].append(service_data)
    
    # Sort services within each category: Basic first, then named Basic, then Advanced
    def service_sort_key(s):
        tier = s['tier'].lower()
        name = s['name'].lower()
        
        # Priority: 1=Basic (unnamed), 2=Basic (named), 3=Advanced
        if 'basic' in tier:
            if name.startswith('basic'):
                return (1, name)  # Unnamed basic
            else:
                return (2, name)  # Named basic
        else:
            return (3, name)  # Advanced
    
    for category in services_by_category:
        services_by_category[category].sort(key=service_sort_key)
    
    # Sort categories alphabetically
    sorted_categories = sorted(services_by_category.keys())
    sorted_by_category = {cat: services_by_category[cat] for cat in sorted_categories}
    
    return {
        'services': all_services,
        'by_category': sorted_by_category,
        'count': len(all_services)
    }


@app.get("/api/services/for-recipe/{recipe_id}")
async def get_services_for_recipe(recipe_id: str, request: Request):
    """
    Get services that can be used for a specific recipe.
    
    Filters services by recipe's service_type and sorts them:
    - Basic services first (unnamed)
    - Named Basic services second
    - Advanced services last
    
    Includes unlock status based on session character data.
    
    Args:
        recipe_id: Recipe ID (e.g., "iron_sickle")
        request: Request object to get session UUID
        
    Returns:
        Dict with filtered services and unlock status
        
    Raises:
        HTTPException: If recipe not found
    """
    # Import data directly instead of calling endpoints
    import util.autogenerated.recipes as recipes_module
    from util.autogenerated.recipes import RecipeInstance
    from util.walkscape_constants import Service
    
    # Find the recipe by attribute name (recipe_id is like "bronze_saw")
    recipe_obj = None
    for attr_name in dir(recipes_module):
        if attr_name.lower() == recipe_id.lower():
            obj = getattr(recipes_module, attr_name)
            if isinstance(obj, RecipeInstance):
                recipe_obj = obj
                break
    
    if not recipe_obj:
        raise HTTPException(
            status_code=404,
            detail={
                "error": True,
                "code": "RECIPE_NOT_FOUND",
                "message": f"Recipe {recipe_id} not found"
            }
        )
    
    # Convert recipe to dict format expected by the rest of the function
    recipe = {
        'id': recipe_id,
        'name': recipe_obj.name,
        'service_type': recipe_obj.service,  # RecipeInstance has 'service' attribute
        'skill': recipe_obj.skill,
        'level': recipe_obj.level
    }
    
    # Get session data for unlock status
    session_uuid = request.state.session_uuid
    session = get_db().get_session(session_uuid)
    character_config = session.get('character_config') if session else None
    
    # Convert services to dict format expected by the rest of the function
    # Replicate the logic from get_services() endpoint
    all_services = []
    for attr_name in dir(Service):
        if attr_name.startswith('_'):
            continue
        service_obj = getattr(Service, attr_name)
        if not hasattr(service_obj, 'name'):
            continue
        
        # Get location info - match the structure from get_services()
        location_data = None
        if service_obj.location:
            loc = service_obj.location
            location_data = {
                'id': loc.name.lower().replace(' ', '_').replace("'", ''),
                'name': loc.name,
                'regions': loc.regions if hasattr(loc, 'regions') else [],
                'is_underwater': loc.is_underwater if hasattr(loc, 'is_underwater') else False,
                'icon_name': loc.icon_name if hasattr(loc, 'icon_name') else None
            }
        
        # Determine if Basic or Advanced from tier string
        tier_lower = service_obj.tier.lower()
        is_basic = 'basic' in tier_lower
        is_advanced = 'advanced' in tier_lower
        
        all_services.append({
            'id': attr_name.lower(),  # Use attribute name as ID
            'name': service_obj.name,
            'category': service_obj.category.value if hasattr(service_obj.category, 'value') else str(service_obj.category),
            'tier': service_obj.tier,
            'is_basic': is_basic,
            'is_advanced': is_advanced,
            'location': location_data,
            'requirements': {
                'skill': service_obj.requirements.get('skill', {}),
                'reputation': service_obj.requirements.get('reputation', {}),
                'keyword_counts': service_obj.requirements.get('keyword_counts', {})
            },
            'stats': service_obj._stats,
            'gated_stats': service_obj.gated_stats if hasattr(service_obj, 'gated_stats') else {}
        })
    
    # Filter services that can be used for this recipe
    # Match by service tier (e.g., "Basic Kitchen" in tier field)
    recipe_service_type = recipe['service_type']  # e.g., "Basic Sawmill" or "Advanced Cursed Sawmill"
    valid_services = []
    
    # If recipe has no service requirement, show all services for the recipe's skill
    if not recipe_service_type or recipe_service_type == 'None':
        recipe_skill = recipe.get('skill', '').lower()
        for service in all_services:
            category = service.get('category', '').lower()
            if category == recipe_skill:
                is_unlocked = True
                missing_requirements = []
                if character_config:
                    for skill_name, required_level in service['requirements']['skill'].items():
                        char_level = character_config.get('skills', {}).get(skill_name.lower(), 0)
                        if char_level < required_level:
                            is_unlocked = False
                            missing_requirements.append(f"{skill_name} level {required_level} (have {char_level})")
                    for faction, required_amount in service['requirements']['reputation'].items():
                        char_rep = character_config.get('reputation', {}).get(faction, 0)
                        if char_rep < required_amount:
                            is_unlocked = False
                            missing_requirements.append(f"{faction} reputation {required_amount} (have {char_rep})")
                service['is_unlocked'] = is_unlocked
                service['missing_requirements'] = missing_requirements
                valid_services.append(service)
    else:
        for service in all_services:
            # Check if service tier matches the recipe's service type
            service_tier_full = service['tier']
            service_name = service['name']
            
            recipe_tier_level = 'basic' if 'Basic' in recipe_service_type else 'advanced'
            service_tier_level = 'basic' if 'Basic' in service_tier_full else 'advanced'
            
            recipe_without_tier = recipe_service_type.replace('Basic ', '').replace('Advanced ', '')
            service_base_type = service_tier_full.replace('Basic ', '').replace('Advanced ', '')
            
            is_specific_service = recipe_without_tier.lower() != service_base_type.lower()
            
            if is_specific_service:
                if service_name.lower() != recipe_without_tier.lower():
                    continue
                if recipe_tier_level != service_tier_level:
                    continue
            else:
                if recipe_without_tier.lower() != service_base_type.lower():
                    continue
                if recipe_tier_level == 'advanced' and service_tier_level == 'basic':
                    continue
            
            # Check unlock status
            is_unlocked = True
            missing_requirements = []
            
            if character_config:
                for skill_name, required_level in service['requirements']['skill'].items():
                    char_level = character_config.get('skills', {}).get(skill_name.lower(), 0)
                    if char_level < required_level:
                        is_unlocked = False
                        missing_requirements.append(f"{skill_name} level {required_level} (have {char_level})")
                
                for faction, required_amount in service['requirements']['reputation'].items():
                    char_rep = character_config.get('reputation', {}).get(faction, 0)
                    if char_rep < required_amount:
                        is_unlocked = False
                        missing_requirements.append(f"{faction} reputation {required_amount} (have {char_rep})")
                
                for keyword, required_count in service['requirements']['keyword_counts'].items():
                    if required_count > 0:
                        if keyword.lower() == 'diving gear':
                            missing_requirements.append(f"{required_count}x {keyword} required")
            else:
                if (service['requirements']['skill'] or 
                    service['requirements']['reputation'] or 
                    service['requirements']['keyword_counts']):
                    is_unlocked = False
                    missing_requirements.append("Character data not loaded")
            
            service_with_status = service.copy()
            service_with_status['is_unlocked'] = is_unlocked
            service_with_status['missing_requirements'] = missing_requirements
            
            valid_services.append(service_with_status)
    
    # Group services by name and collect their locations
    services_grouped = {}
    for service in valid_services:
        service_name = service['name']
        
        if service_name not in services_grouped:
            # Create new group
            services_grouped[service_name] = {
                'id': service_name.lower().replace(' ', '_'),  # Use name as ID for grouped service
                'name': service_name,
                'category': service['category'],
                'tier': service['tier'],
                'is_basic': service['is_basic'],
                'is_advanced': service['is_advanced'],
                'stats': service['stats'],  # Add stats to grouped service
                'gated_stats': service['gated_stats'],  # Include reputation-gated bonuses
                'locations': [],
                'is_unlocked': True,  # Will be False if ALL locations are locked
                'missing_requirements': []
            }
        
        # Add this location to the group
        if service['location']:
            services_grouped[service_name]['locations'].append({
                'service_id': service['id'],  # Original service ID with location
                'location': service['location'],
                'is_unlocked': service['is_unlocked'],
                'missing_requirements': service['missing_requirements'],
                'requirements': service['requirements'],
                'stats': service['stats'],
                'gated_stats': service['gated_stats']
            })
            
            # Service is unlocked if ANY location is unlocked
            # (We'll show red border on locked locations specifically)
    
    # Convert to list and sort
    grouped_services_list = list(services_grouped.values())
    
    # Sort services: Basic first, then named Basic, then Advanced
    def service_sort_key(s):
        tier = s['tier'].lower()
        name = s['name'].lower()
        
        # Priority: 1=Basic (unnamed), 2=Basic (named), 3=Advanced
        if 'basic' in tier:
            if name.startswith('basic'):
                return (1, name)  # Unnamed basic
            else:
                return (2, name)  # Named basic
        else:
            return (3, name)  # Advanced
    
    grouped_services_list.sort(key=service_sort_key)
    
    return {
        'recipe_id': recipe_id,
        'recipe_name': recipe['name'],
        'recipe_service_type': recipe['service_type'],
        'services': grouped_services_list,
        'count': len(grouped_services_list)
    }


