@app.get("/api/item-finding-categories")
async def get_item_finding_categories(request: Request, response: Response):
    """
    Get item finding category information for display.
    
    Returns category display names, quantities, and singular forms for proper formatting.
    """
    from util.autogenerated.item_finding import ItemFindingCategory
    
    cached = _maybe_static_304(request, response, "item-finding-categories")
    if cached:
        return cached
    
    categories = {}
    
    for attr_name in dir(ItemFindingCategory):
        if attr_name.startswith('_'):
            continue
        
        category = getattr(ItemFindingCategory, attr_name)
        if hasattr(category, 'drops') and len(category.drops) > 0:
            # Get quantity range from first drop (all items in category have same quantity)
            first_drop = category.drops[0]
            min_qty = first_drop.quantity.min_qty
            max_qty = first_drop.quantity.max_qty
            
            # Create singular form of display name
            display_name = category.name
            display_name_singular = display_name.rstrip('s') if display_name.endswith('s') and display_name != 'Ectoplasm' else display_name
            # Special cases
            if display_name == "Adventurers' Guild Tokens":
                display_name_singular = "Adventurers' guild token"
            elif display_name == "Gold Pieces":
                display_name_singular = "gold pieces"  # Already plural in meaning
            elif display_name == "Sea Shells":
                display_name_singular = "sea shell"
            
            # Icon name should be singular (matching the actual file)
            # The icon files are named after the singular form
            icon_name_base = attr_name.lower()  # e.g., "adventurers_guild_tokens"
            
            # Remove trailing 's' for plural categories
            if icon_name_base.endswith('s') and icon_name_base not in ['ectoplasm', 'gold_pieces']:
                icon_name_singular = icon_name_base[:-1]  # Remove trailing 's'
            else:
                icon_name_singular = icon_name_base
            
            icon_name = f'find_{icon_name_singular}'
            
            categories[attr_name] = {
                'display_name': display_name,
                'display_name_singular': display_name_singular,
                'min_qty': min_qty,
                'max_qty': max_qty,
                'icon_name': icon_name
            }
    
    return categories


@app.post("/api/expand-equipment-drops")
async def expand_equipment_drops(request: Request):
    """
    Expand ItemFindingCategory stats to actual drop entries.
    
    Request body:
        stats: Dict of stats including ItemFindingCategory.* entries
    
    Returns:
        List of expanded drop entries with has_fine_material flag
    """
    from util.autogenerated.item_finding import ItemFindingCategory
    from util.item_utils import DropEntry, Quantity
    import logging
    
    logger = logging.getLogger(__name__)
    
    body = await request.json()
    stats = body.get('stats', {})
    
    logger.info(f"=== expand_equipment_drops called ===")
    logger.info(f"Received stats: {stats}")
    
    expanded_drops = []
    
    for stat_name, stat_value in stats.items():
        if stat_name.startswith('ItemFindingCategory.'):
            category_const = stat_name.split('.', 1)[1]
            logger.info(f"Processing category: {category_const} with value {stat_value}")
            
            if hasattr(ItemFindingCategory, category_const):
                category = getattr(ItemFindingCategory, category_const)
                logger.info(f"  Category found: {category.name} with {len(category.drops)} items")
                
                # Expand with the stat value (already in percentage form)
                drops = category.expand_with_chance(stat_value)
                logger.info(f"  Expanded to {len(drops)} drops")
                
                for drop in drops:
                    # Check if this item has a fine version
                    has_fine = False
                    try:
                        if drop.item_object:
                            # Check if it's a Material with has_fine_material method
                            if hasattr(drop.item_object, 'has_fine_material'):
                                has_fine = drop.item_object.has_fine_material()
                            # Skip currencies - they don't have fine versions
                            elif isinstance(drop.item_object, CurrencyInstance):
                                has_fine = False
                            # Check if it's a Consumable - look for fine version by name
                            else:
                                from util.autogenerated.consumables import Consumable
                                # Try to find fine version: "Bug bait" -> "BUG_BAIT_FINE"
                                item_name_enum = drop.item_name.upper().replace(' ', '_').replace("'", '').replace('-', '_')
                                fine_enum_name = item_name_enum + '_FINE'
                                if hasattr(Consumable, fine_enum_name):
                                    has_fine = True
                                    logger.info(f"    {drop.item_name} has fine version: {fine_enum_name}")
                    except Exception as e:
                        logger.error(f"    Error checking fine version for {drop.item_name}: {e}")
                    
                    logger.info(f"    Adding drop: {drop.item_name} ({drop.chance_percent}%) has_fine={has_fine}")
                    
                    # Get currency info (resolve directly from item_ref to avoid circular import)
                    coin_value = 0
                    special_sell_info = None
                    try:
                        ref = drop.item_ref
                        if ref == 'Currency.COIN':
                            coin_value = 1
                        elif ref == 'Currency.ADVENTURERS_GUILD_TOKEN':
                            special_sell_info = {'quantity': 1, 'currency': 'ag_token'}
                        elif ref and ref.startswith('Container.'):
                            # 2026-05-26 (jwbail): Containers (skill chests) have an
                            # expected coin yield when opened — the worker uses
                            # util/coin_value.py:CHEST_COIN_VALUES for this. Without
                            # this branch, the 11 IF-eq skill chests that aren't in
                            # the activity drop_table (Agility, Carpentry, Cooking,
                            # Crafting, Foraging, Hunting, Mining, Smithing, Tailoring,
                            # Trinketry, Woodcutting on Sea fishing) all return
                            # coin_value=0 and column-3's coins/1k under-counts by
                            # ~6.36 vs the worker's stored value (228.24 vs 221.88).
                            from util.coin_value import CHEST_COIN_VALUES
                            coin_value = float(CHEST_COIN_VALUES.get(ref, 0) or 0)
                        elif ref and ref.startswith('Material.'):
                            from util.autogenerated.materials import Material as Mat
                            attr_name = ref.split('.', 1)[1]
                            if hasattr(Mat, attr_name):
                                obj = getattr(Mat, attr_name)
                                coin_value = obj.value or 0
                                if hasattr(obj, 'special_sell') and obj.special_sell:
                                    qty, currency_obj = obj.special_sell
                                    if hasattr(currency_obj, 'name') and 'guild token' in currency_obj.name.lower():
                                        special_sell_info = {'quantity': qty, 'currency': 'ag_token'}
                        elif ref and ref.startswith('Consumable.'):
                            attr_name = ref.split('.', 1)[1]
                            if hasattr(Consumable, attr_name):
                                obj = getattr(Consumable, attr_name)
                                if hasattr(obj, 'value'):
                                    coin_value = obj.value or 0
                        elif ref and ref.startswith('Item.'):
                            # 2026-05-28 (jwbail): mirror the Item.* fix from
                            # _get_drop_currency_info above. Equipment drops
                            # carried via IF expansions also need the
                            # intrinsic .value or column-3 reads them as
                            # worth 0.
                            from util.autogenerated.equipment import Item
                            attr_name = ref.split('.', 1)[1]
                            if hasattr(Item, attr_name):
                                obj = getattr(Item, attr_name)
                                if hasattr(obj, 'value'):
                                    coin_value = obj.value or 0
                    except Exception:
                        pass

                    # Sea shell values for IF-expanded drops. Mirror the
                    # logic in util/shell_value.py:get_drop_shell_value:
                    #   Material.SEA_SHELL → 1, Material.SEA_SHELL_FINE → 10,
                    #   Container.* → CHEST_SHELL_VALUES.get(ref, 0).
                    # Without this, the column-3 shells/1k pill misses
                    # IF-stat-driven shell sources (e.g. flatpack shark).
                    shell_value = 0.0
                    fine_shell_value = 0.0
                    try:
                        from util.shell_value import (
                            get_drop_shell_value,
                            get_drop_fine_shell_value,
                        )
                        shell_value = get_drop_shell_value(drop)
                        fine_shell_value = get_drop_fine_shell_value(drop)
                    except Exception:
                        pass

                    expanded_drops.append({
                        'item_name': drop.item_name,
                        'item_ref': drop.item_ref,
                        'chance_percent': drop.chance_percent,
                        'min_qty': drop.quantity.min_qty,
                        'max_qty': drop.quantity.max_qty,
                        'has_fine_material': has_fine,
                        'coin_value': coin_value,
                        'special_sell': special_sell_info,
                        'fine_ag_token_value': get_drop_fine_ag_token_value(drop),
                        'shell_value': shell_value,
                        'fine_shell_value': fine_shell_value,
                    })
            else:
                logger.warning(f"Category not found: {category_const}")
    
    logger.info(f"Returning {len(expanded_drops)} expanded drops")
    logger.info(f"=== expand_equipment_drops END ===")
    
    return {'drops': expanded_drops}


@app.post("/api/all-item-finding-drops")
async def get_all_item_finding_drops(request: Request):
    """
    Get all possible item finding drops from ALL owned items for a given skill.
    Scans all equipment items and collects ItemFindingCategory stats.
    
    Request body:
        skill: Skill name (e.g., 'fishing', 'cooking', 'global')
    
    Returns:
        List of expanded drop entries from all owned items
    """
    from util.autogenerated.equipment import Item, ItemInstance, CraftedItem, AchievementItem
    from util.autogenerated.item_finding import ItemFindingCategory
    from util.autogenerated.consumables import Consumable
    from util.walkscape_constants import Skill
    import logging
    
    logger = logging.getLogger(__name__)
    
    body = await request.json()
    skill = body.get('skill', 'global')
    
    logger.info(f"=== all-item-finding-drops for skill: {skill} ===")
    
    # Collect ALL ItemFindingCategory stats from ALL equipment items
    all_stats = {}
    
    for attr_name in dir(Item):
        if attr_name.startswith('_'):
            continue
        
        item = getattr(Item, attr_name)
        if not isinstance(item, (ItemInstance, CraftedItem, AchievementItem)):
            continue
        
        if not hasattr(item, '_stats'):
            continue
        
        # Check all skills in the item's stats
        for stat_skill, location_data in item._stats.items():
            # Match global or the specific skill
            if stat_skill != 'global' and stat_skill != skill:
                # Also check component skills (e.g., 'agility' matches 'travel')
                try:
                    skill_obj = Skill.from_name(skill)
                    if skill_obj and not skill_obj.matches_skill(stat_skill):
                        continue
                except:
                    continue
            
            for location, stats in location_data.items():
                for stat_name, stat_value in stats.items():
                    if stat_name.startswith('ItemFindingCategory.'):
                        if stat_name not in all_stats:
                            all_stats[stat_name] = 0
                        all_stats[stat_name] = max(all_stats[stat_name], stat_value)  # Use max, not sum (different items)
    
    logger.info(f"Found {len(all_stats)} unique ItemFindingCategory stats: {all_stats}")
    
    # Expand all categories to actual drops
    expanded_drops = []
    
    for stat_name, stat_value in all_stats.items():
        category_const = stat_name.split('.', 1)[1]
        
        if hasattr(ItemFindingCategory, category_const):
            category = getattr(ItemFindingCategory, category_const)
            drops = category.expand_with_chance(stat_value)
            
            for drop in drops:
                # Check if this item has a fine version
                has_fine = False
                try:
                    if drop.item_object:
                        if hasattr(drop.item_object, 'has_fine_material'):
                            has_fine = drop.item_object.has_fine_material()
                        else:
                            item_name_enum = drop.item_name.upper().replace(' ', '_').replace("'", '').replace('-', '_')
                            fine_enum_name = item_name_enum + '_FINE'
                            if hasattr(Consumable, fine_enum_name):
                                has_fine = True
                except:
                    pass
                
                # Get currency info (resolve directly from item_ref to avoid circular import)
                coin_value = 0
                special_sell_info = None
                try:
                    ref = drop.item_ref
                    if ref == 'Currency.COIN':
                        coin_value = 1
                    elif ref == 'Currency.ADVENTURERS_GUILD_TOKEN':
                        special_sell_info = {'quantity': 1, 'currency': 'ag_token'}
                    elif ref and ref.startswith('Material.'):
                        from util.autogenerated.materials import Material as Mat
                        attr_name = ref.split('.', 1)[1]
                        if hasattr(Mat, attr_name):
                            obj = getattr(Mat, attr_name)
                            coin_value = obj.value or 0
                            if hasattr(obj, 'special_sell') and obj.special_sell:
                                qty, currency_obj = obj.special_sell
                                if hasattr(currency_obj, 'name') and 'guild token' in currency_obj.name.lower():
                                    special_sell_info = {'quantity': qty, 'currency': 'ag_token'}
                    elif ref and ref.startswith('Consumable.'):
                        attr_name = ref.split('.', 1)[1]
                        if hasattr(Consumable, attr_name):
                            obj = getattr(Consumable, attr_name)
                            if hasattr(obj, 'value'):
                                coin_value = obj.value or 0
                except Exception:
                    pass
                
                expanded_drops.append({
                    'item_name': drop.item_name,
                    'item_ref': drop.item_ref,
                    'chance_percent': drop.chance_percent,
                    'min_qty': drop.quantity.min_qty,
                    'max_qty': drop.quantity.max_qty,
                    'has_fine_material': has_fine,
                    'coin_value': coin_value,
                    'special_sell': special_sell_info,
                    'fine_ag_token_value': get_drop_fine_ag_token_value(drop),
                    'stat_key': stat_name
                })
    
    logger.info(f"Returning {len(expanded_drops)} expanded drops")
    
    return {'drops': expanded_drops}


# ============================================================================
# BUG REPORT API ENDPOINTS
# ============================================================================

class BugReportData(BaseModel):
    """Bug report submission model."""
    description: str = Field(..., min_length=1, max_length=5000)
    app_version: str
    browser_info: str
    screenshots: Optional[Dict[str, str]] = None  # tab_name -> base64 data
    debug_log: Optional[str] = None  # Formatted debug log text


@app.post("/api/bug-reports")
async def submit_bug_report(request: Request, data: BugReportData):
    """
    Submit a new bug report.
    
    Creates a snapshot of the current session state and stores it with
    the bug report for later review.
    
    Args:
        request: Request object to get session UUID
        data: Bug report data with description, version, browser info, screenshots
        
    Returns:
        Created bug report with IDs
    """
    original_uuid = request.state.session_uuid
    
    # Get current session
    session = get_db().get_session(original_uuid)
    if not session:
        raise HTTPException(
            status_code=404,
            detail={
                "error": True,
                "code": "SESSION_NOT_FOUND",
                "message": "Session not found"
            }
        )
    
    # Create snapshot session with new UUID
    snapshot_uuid = str(uuid.uuid4())
    snapshot_session = get_db().create_session(snapshot_uuid)
    
    # Copy character_config and ui_config to snapshot
    if session.get('character_config'):
        get_db().update_character_config(snapshot_uuid, session['character_config'])
    if session.get('ui_config'):
        get_db().update_ui_config(snapshot_uuid, session['ui_config'])

    # Copy owned items + inventory value to the snapshot. Without this the
    # snapshot session had an empty inventory, so the goals-report / crafting
    # optimizer produced no (or degenerate 0-metric) results when a reviewer
    # ran it -- the reporter's "best chest farming for recipes" options
    # (e.g. tailoring linen) silently disappeared. get_session returns
    # all_items_raw as the RAW json string (or None); update_all_items_raw
    # re-serialises a dict, so parse it back first.
    raw_items = session.get('all_items_raw')
    if raw_items:
        try:
            items_dict = json.loads(raw_items) if isinstance(raw_items, str) else raw_items
            get_db().update_all_items_raw(snapshot_uuid, items_dict)
        except Exception as e:
            log(f"Failed to copy all_items_raw to snapshot: {e}", original_uuid)
    inv_value = session.get('inventory_value')
    if inv_value is not None:
        try:
            get_db().update_inventory_value(snapshot_uuid, inv_value)
        except Exception as e:
            log(f"Failed to copy inventory_value to snapshot: {e}", original_uuid)

    # Copy gear sets to snapshot
    gear_sets = get_db().get_gear_sets(original_uuid)
    for gear_set in gear_sets:
        get_db().create_gear_set(
            session_uuid=snapshot_uuid,
            name=gear_set['name'],
            slots_json=gear_set['slots_json']
        )
    
    # Copy feature flags to snapshot so reviewer sees the same features
    try:
        conn = get_db()._get_connection()
        cursor = conn.cursor()
        cursor.execute(
            "SELECT feature, enabled_by FROM feature_flags WHERE session_uuid = ?",
            (original_uuid,)
        )
        for row in cursor.fetchall():
            get_db().enable_feature(snapshot_uuid, row[0], f"snapshot-of-{row[1]}")
        if not get_db()._persistent_conn:
            conn.close()
        # Also copy hardcoded feature access
        if get_db().has_feature(original_uuid, 'travel'):
            get_db().enable_feature(snapshot_uuid, 'travel', 'snapshot-copy')
    except Exception as e:
        log(f"Failed to copy feature flags to snapshot: {e}", original_uuid)

    # Copy the full goals-report (stats_report_*) state to the snapshot so the
    # report reproduces exactly at review time -- results rows AND the stale-badge
    # state AND the prev snapshot used for stale diffing (previously only the
    # results rows were copied). See DatabaseManager.copy_stats_report_data.
    try:
        _sr_counts = get_db().copy_stats_report_data(original_uuid, snapshot_uuid)
        log(f"Copied goals-report data to snapshot: {_sr_counts}", original_uuid)
    except Exception as e:
        log(f"Failed to copy goals-report data to snapshot: {e}", original_uuid)
    
    # Create bug report
    report = get_db().create_bug_report(
        original_session_uuid=original_uuid,
        snapshot_session_uuid=snapshot_uuid,
        description=data.description,
        app_version=data.app_version,
        browser_info=data.browser_info,
        screenshots_json=data.screenshots
    )
    
    # Capture server logs at time of report
    try:
        server_logs = _capture_server_logs(5000)
        # Also attach the most recently-modified optimize_worker_*.log file
        # from /tmp so the worker's own subprocess output isn't lost to
        # the rolling docker-logs buffer. This is the log that has
        # [worker] ... RAW sorting_priority ..., scoring, etc.
        try:
            import glob as _glob
            worker_logs = sorted(
                _glob.glob('/tmp/optimize_worker_*.log'),
                key=lambda p: os.path.getmtime(p),
                reverse=True,
            )[:3]
            for wpath in worker_logs:
                try:
                    with open(wpath, 'r') as _wf:
                        _wcontent = _wf.read()
                    # Tail to last 40K chars each so bug report doesn't explode
                    _wcontent = _wcontent[-40000:]
                    server_logs = (server_logs or '') + \
                        f"\n\n===== WORKER LOG: {wpath} (last {len(_wcontent)} chars) =====\n" + \
                        _wcontent
                except Exception:
                    pass
        except Exception:
            pass
        if server_logs:
            conn = get_db()._get_connection()
            conn.execute(
                "UPDATE bug_reports SET server_logs = ? WHERE id = ?",
                (server_logs, report['id'])
            )
            conn.commit()
            log(f"Captured server logs ({len(server_logs)} chars) for report {report['id'][:8]}", original_uuid)
    except Exception as e:
        log(f"Failed to capture server logs: {e}", original_uuid)
    
    # Save debug log as file if provided
    if data.debug_log:
        from pathlib import Path
        report_dir = Path("ui/bug_report_screenshots") / report['id']
        report_dir.mkdir(parents=True, exist_ok=True)
        debug_log_path = report_dir / "debug_log.txt"
        debug_log_path.write_text(data.debug_log, encoding='utf-8')
        log(f"Saved debug log ({len(data.debug_log)} chars) for report {report['id'][:8]}", original_uuid)
    
    return {
        "success": True,
        "message": "Bug report submitted successfully",
        "report": report
    }


