def _sanitize_for_json(obj):
    """Recursively replace non-JSON-compliant float values (inf, -inf, nan) with None.

    Python's json.dumps raises ValueError on these IEEE 754 special values.
    This ensures any data loaded from the database can be safely serialized.
    """
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            return None
        return obj
    if isinstance(obj, dict):
        return {k: _sanitize_for_json(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_sanitize_for_json(v) for v in obj]
    return obj












# ============================================================================
# Active Debug Link API
# Lets the admin (jwbail) link a bug-report snapshot session to their main
# session. The main site nav header reads /api/active-debug-link to show an
# orange caterpillar "swap" button. Clicking it sets the session_uuid cookie
# to the snapshot UUID and reloads. On the snapshot session, the same button
# (rendered green via localStorage cache) swaps back to the main UUID.
# ============================================================================


@app.get("/api/active-debug-link")
async def get_active_debug_link(request: Request):
    """Return the active debug link if the requesting cookie is the main UUID.

    Per spec: "only tries to get the URL/API endpoint IF I'm on my main
    session UUID. No other sessions should be pinging that endpoint to check."
    The frontend gates the call on `currentCookie === ACTIVE_DEBUG_MAIN_UUID`,
    but we also gate server-side as defense in depth: any other session_uuid
    receives a uniform "not linked" response so the endpoint cannot be used
    to enumerate the linked snapshot UUID.

    Response shape:
        { "linked": true, "snapshot_session_uuid": "...", "bug_report_id": "..." | null }
        { "linked": false }
    """
    cookie_uuid = request.cookies.get("session_uuid")
    if cookie_uuid != ACTIVE_DEBUG_MAIN_UUID:
        return {"linked": False}
    link = get_db().get_active_debug_link(ACTIVE_DEBUG_MAIN_UUID)
    if not link:
        return {"linked": False}
    return {
        "linked": True,
        "snapshot_session_uuid": link["snapshot_session_uuid"],
        "bug_report_id": link.get("bug_report_id"),
        "linked_at": link.get("linked_at"),
    }


@app.get("/api/active-debug-snapshot-check")
async def get_active_debug_snapshot_check(request: Request):
    """Report whether the requesting cookie session is a bug-report snapshot.

    The main-site nav calls this from NON-main sessions to decide whether to
    show the green "swap back to main session" button. It returns only a
    boolean about the current cookie and never reveals any other session's
    UUID (the swap-back target is the hard-coded main UUID already known to
    the client), so it is safe to call from any session.

    The button must appear on EVERY bug-report snapshot session — even when
    the snapshot is not currently linked — so the admin is never stranded
    inside a snapshot session after delinking. Identification is therefore by
    membership in bug_reports.snapshot_session_uuid, independent of the
    active_debug_links table.

    Response shape:
        { "is_snapshot": true } | { "is_snapshot": false }
    """
    cookie_uuid = request.cookies.get("session_uuid")
    if not cookie_uuid or cookie_uuid == ACTIVE_DEBUG_MAIN_UUID:
        return {"is_snapshot": False}
    return {"is_snapshot": get_db().is_bug_report_snapshot_session(cookie_uuid)}
















