WRITE_KEYWORDS = {'INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 'CREATE', 'TRUNCATE', 'REPLACE'}


def _json_safe_value(v):
    """Make a single SQL cell value JSON-serializable.

    BLOB columns (e.g. item_static_dominators.dominators_bitmap) come back as
    raw `bytes`, which FastAPI's JSON encoder cannot serialize -- the failure
    happens during response rendering (after the handler returns), surfacing as
    a 500.

    These blobs are bitmaps (membership sets indexed by item_id). Render them as
    a binary bit string so the admin can read which bits are set. Bit order
    matches the producer (build_dominators._set_bit): byte i, bit position j is
    item_id (i*8 + j), LSB-first within each byte -- so string index == item_id
    (bit 0 is unused; ids start at 1). Cap very large blobs to keep the response
    bounded.
    """
    if isinstance(v, (bytes, bytearray, memoryview)):
        b = bytes(v)
        MAX_BITS = 8192
        bits = "".join(
            str((byte >> j) & 1)
            for byte in b[: MAX_BITS // 8]
            for j in range(8)
        )
        if len(b) * 8 > MAX_BITS:
            bits += f"...(+{len(b) - MAX_BITS // 8} more bytes)"
        return f"0b{bits}" if bits else "0b (empty)"
    return v


def _json_safe_row(row):
    return [_json_safe_value(v) for v in row]








