    """Register or update a push subscription for the current session."""
    if not _push_enabled:
        raise HTTPException(status_code=503, detail="push_not_configured")
    session_uuid = request.cookies.get("session_uuid")
    if not session_uuid:
        raise HTTPException(status_code=400, detail="No session")
    get_db().upsert_push_subscription(session_uuid, body.endpoint, body.p256dh, body.auth)
    return {"ok": True}


