@app.get("/api/optimization-result")
async def get_optimization_result(request: Request):
    """
    Get the result of the most recent optimization for this session.
    
    Returns:
        Export string and metadata, or null if no result available
    """
    session_uuid = request.state.session_uuid
    session = get_db().get_session(session_uuid)
    
    if session and session.get('ui_config'):
        result = session['ui_config'].get('optimization_result')
        if result:
            # Clear the result after retrieving (one-time use)
            ui_config = session['ui_config']
            del ui_config['optimization_result']
            get_db().update_ui_config(session_uuid, ui_config)
            
            log(f"✓ Retrieved and cleared optimization result", session_uuid)
            return result
    
    return None


def _is_snapshot_session(session_uuid: str) -> bool:
    """Return True if session_uuid is a bug-report snapshot session.

    Snapshot sessions are clones created when a bug report is filed; the client
    uses this to skip the per-device local-speed benchmark + warning popup so we
    never benchmark or nudge inside a snapshot being inspected for debugging.
    """
    if not session_uuid:
        return False
    try:
        conn = get_db()._get_connection()
        cur = conn.cursor()
        cur.execute(
            "SELECT 1 FROM bug_reports WHERE snapshot_session_uuid = ? LIMIT 1",
            (session_uuid,),
        )
        found = cur.fetchone() is not None
        if not get_db()._persistent_conn:
            conn.close()
        return found
    except Exception:
        return False


@app.get("/api/optimization-settings")
async def get_optimization_settings(request: Request):
    """
    Get optimization settings including available sorting options.

    Returns:
        Available sorting metrics for activities and recipes,
        plus current user preferences from session.
        current_order is a list of [metric_key, weight] tuples where
        weight is an integer 0-100.
    """
    from util.walkscape_constants import Sorting, SortingType

    # Get session
    session_uuid = request.state.session_uuid
    session = get_db().get_session(session_uuid)

    # Get current preferences from session
    ui_config = session.get('ui_config', {}) if session else {}
    activity_sorting = ui_config.get('optimize_sorting_activity', [])
    recipe_sorting = ui_config.get('optimize_sorting_recipe', [])
    travel_sorting = ui_config.get('optimize_sorting_travel', [])
    # Support both old per-type flags and new unified flag (backward compat)
    include_consumables = ui_config.get('include_consumables',
        ui_config.get('activity_include_consumables', False) or ui_config.get('recipe_include_consumables', False)
    )

    def normalize_sorting(sorting_list, is_activity=True):
        """Convert plain key arrays to [key, 100, null] tuples if needed.
        Also applies metric key aliases for backward compatibility,
        and repairs corrupted keys from a previous bug where tuples
        were stringified into the key (e.g. 'steps_per_reward_roll,100,').

        When is_activity is True, migrates deprecated activity metrics
        (steps_for_chest, steps_for_fine_material, steps_for_collectible)
        to steps_per_reward_roll with the appropriate cat:* target."""
        # Aliases for renamed metric keys
        metric_key_aliases = {}
        
        if not sorting_list:
            return []

        def repair_key(key):
            """Fix corrupted keys like 'steps_per_reward_roll,100,' back to just the metric key."""
            if not isinstance(key, str):
                return key
            # Corrupted keys contain commas from array stringification
            if ',' in key:
                repaired = key.split(',')[0].strip()
                if repaired:
                    return repaired
            return key

        # Check if old format (plain strings) or new format ([key, weight, target] tuples)
        if sorting_list and isinstance(sorting_list[0], str):
            # Old format: plain key array -> convert to [key, 100, null] tuples
            return [[metric_key_aliases.get(repair_key(key), repair_key(key)), 100, None] for key in sorting_list]
        # Already in tuple format, ensure weights are clamped ints
        # Allow duplicates for keys marked `duplicable` on the Sorting enum
        duplicable_keys = {s.metric_key for s in Sorting if s.duplicable}
        # Migrate deprecated activity metric keys to steps_per_reward_roll with
        # the appropriate category target. Only applied to activity sorting —
        # recipe sorting never had these metrics. Pristine defaults outside
        # the top N positions are stripped entirely for a cleaner UX — see
        # ui/optimization_settings_migration.py.
        if is_activity:
            from ui.optimization_settings_migration import (
                migrate_activity_sorting,
                DEPRECATED_KEY_MAP,
            )
            before_snapshot = [
                list(entry) if isinstance(entry, (list, tuple)) else entry
                for entry in sorting_list
            ]
            migrated_list, action = migrate_activity_sorting(sorting_list)
            if action != 'none':
                try:
                    db = get_db()
                    if not db.has_optimization_settings_migration(session_uuid):
                        db.log_optimization_settings_migration(
                            session_uuid, action, before_snapshot, migrated_list,
                        )
                except Exception as _e:
                    # Logging is best-effort; never block a settings load.
                    pass
            # Replace sorting_list with the migrated form, then fall through
            # to the general validation/dedup pass below for alias+repair+weight-clamp.
            sorting_list = migrated_list
        deprecated_key_migration = {}  # handled upstream for activity; no-op here
        def migrate(key, target):
            if key in deprecated_key_migration:
                new_key, new_target = deprecated_key_migration[key]
                return new_key, target or new_target
            return key, target
        result = []
        seen_keys = set()
        for entry in sorting_list:
            # Recipe sorting uses the new X-per-Y dict form after the migration.
            # Pass dict entries through unchanged — migrate_recipe_sorting will
            # handle them downstream. Without this branch, dict entries fall
            # through all the isinstance checks below and get silently dropped,
            # which wipes the user's saved recipe priorities on every load.
            if isinstance(entry, dict):
                result.append(entry)
                continue
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                key = repair_key(entry[0])
                key = metric_key_aliases.get(key, key)
                target = entry[2] if len(entry) >= 3 else None
                key, target = migrate(key, target)
                # Deduplicate: corrupted data may have both corrupted and clean versions
                # But keep duplicates for duplicable keys (user-intended)
                if key in seen_keys and key not in duplicable_keys:
                    continue
                seen_keys.add(key)
                weight = max(0, min(100, int(entry[1])))
                result.append([key, weight, target])
            elif isinstance(entry, str):
                key = repair_key(entry)
                key = metric_key_aliases.get(key, key)
                key, target = migrate(key, None)
                if key in seen_keys and key not in duplicable_keys:
                    continue
                seen_keys.add(key)
                # Mixed format fallback
                result.append([key, 100, target])
        return result

    activity_sorting = normalize_sorting(activity_sorting, is_activity=True)
    recipe_sorting = normalize_sorting(recipe_sorting, is_activity=False)

    # Activity: migrate to the new X-per-Y dict form (mirror of recipe).
    # Preserves user customizations (weights, order, per-entry targets)
    # and adds default entries on first-time migration.
    from ui.optimization_settings_migration import (
        migrate_activity_to_xy_form,
    )
    removed_activity_raw = ui_config.get('optimize_removed_activity', []) or []
    activity_sorting_migrated, activity_action = migrate_activity_to_xy_form(
        activity_sorting,
        removed_keys=[k for k in removed_activity_raw if isinstance(k, str)],
    )
    if activity_action not in ('already_migrated',):
        log(f"[activity-xy-migration] session action={activity_action}, entries={len(activity_sorting_migrated)}", session_uuid)
    activity_sorting = activity_sorting_migrated

    # Recipe: migrate to the new X-per-Y dict form (preserves user
    # customizations — weights, order, per-entry quality targets).
    # optimize_removed_recipe entries come back as hiddenInQuick=true so
    # they remain accessible via the Detailed view.
    from ui.optimization_settings_migration import (
        migrate_recipe_sorting,
        is_new_form_recipe_entry,
    )
    removed_recipe_raw = ui_config.get('optimize_removed_recipe', []) or []
    recipe_sorting_migrated, recipe_action = migrate_recipe_sorting(
        recipe_sorting,
        removed_keys=[k for k in removed_recipe_raw if isinstance(k, str)],
    )
    # Best-effort log so we can track rollout.
    if recipe_action not in ('already_migrated',):
        log(f"[recipe-migration] session action={recipe_action}, entries={len(recipe_sorting_migrated)}", session_uuid)
    recipe_sorting = recipe_sorting_migrated

    # Build available sorting options
    activity_options = []
    recipe_options = []
    travel_options = []

    # Travel exposes only the two column-3 metrics the UI supports:
    # Total Steps (default) and the duplicable Steps/Target Item. Other
    # TRAVEL-typed enums (XP/Step, Steps/Chest, Average Steps) are used
    # internally by the advanced travel-config optimizer, not the column-3
    # priority panel, so they're intentionally excluded here.
    TRAVEL_OPTION_KEYS = {'total_steps', 'travel_steps_per_target'}

    # Quality-specific metrics (have "X Quality" in display name)
    quality_specific_keys = ['materials_for_target', 'steps_for_target', 'total_crafts']
    budget_specific_keys = ['steps_for_budget']

    for sorting in Sorting:
        option = {
            'key': sorting.metric_key,
            'name': sorting.name,
            'display_name': sorting.display_name,
            'is_reverse': sorting.is_reverse,
            'requires_quality': sorting.metric_key in quality_specific_keys,
            'requires_budget': sorting.metric_key in budget_specific_keys,
            'duplicable': sorting.duplicable
        }

        # Check which types this sorting applies to
        if SortingType.ACTIVITY in sorting.types:
            activity_options.append(option)
        if SortingType.RECIPE in sorting.types:
            recipe_options.append(option)
        if SortingType.TRAVEL in sorting.types and sorting.metric_key in TRAVEL_OPTION_KEYS:
            travel_options.append(option)

    # If no preferences saved, use default order with weight 100
    # If preferences exist, only append genuinely NEW metrics (not ones the user removed)
    removed_activity = set(ui_config.get('optimize_removed_activity', [])) & {s.metric_key for s in Sorting if SortingType.ACTIVITY in s.types}

    # Activity sorting already went through migrate_activity_to_xy_form above,
    # which handles default-appending and removed_keys → hiddenInQuick. No
    # further reconciliation needed here — it's already in the final dict form.
    # (Recipe has the same comment below.)

    # Recipe sorting already went through migrate_recipe_sorting above, which
    # handles default-appending and removed_keys → hiddenInQuick. No further
    # reconciliation needed here — it's already in the final dict form.

    # Travel sorting: light normalization to [key, weight, target] tuples,
    # dropping any keys not in the two supported travel metrics. Default to
    # a single Total Steps priority when nothing is saved (identical to the
    # pre-priority-list behaviour).
    def normalize_travel_sorting(sorting_list):
        result = []
        seen = set()
        duplicable_keys = {s.metric_key for s in Sorting if s.duplicable}
        for entry in (sorting_list or []):
            if isinstance(entry, (list, tuple)) and len(entry) >= 1:
                key = entry[0]
                try:
                    weight = max(0, min(100, int(entry[1]))) if len(entry) >= 2 else 100
                except (ValueError, TypeError):
                    weight = 100
                target = entry[2] if len(entry) >= 3 else None
            elif isinstance(entry, str):
                key, weight, target = entry, 100, None
            else:
                continue
            if key not in TRAVEL_OPTION_KEYS:
                continue
            dedup = f"{key}::{target}" if target else key
            if dedup in seen and key not in duplicable_keys:
                continue
            seen.add(dedup)
            result.append([key, weight, target])
        if not result:
            result = [['total_steps', 100, None]]
        return result

    travel_sorting = normalize_travel_sorting(travel_sorting)

    return {
        'activity': {
            'options': activity_options,
            'current_order': activity_sorting,
        },
        'recipe': {
            'options': recipe_options,
            'current_order': recipe_sorting,
        },
        'travel': {
            'options': travel_options,
            'current_order': travel_sorting,
        },
        'include_consumables': include_consumables,
        'auto_equip_optimized': ui_config.get('auto_equip_optimized', False),
        'auto_copy_export': ui_config.get('auto_copy_export', False),
        'lock_current_gear_slots': ui_config.get('lock_current_gear_slots', False),
        'include_pets': ui_config.get('include_pets', False),
        'show_non_owned_alternatives': True,  # Always on for everyone
        'skip_obtained_collectibles': ui_config.get('skip_obtained_collectibles', True),
        'run_local_optimization': ui_config.get('run_local_optimization', False),
        'finish_on_server_on_leave': ui_config.get('finish_on_server_on_leave', False),
        # Persisted across all of the user's devices (per session UUID). When
        # True, the per-device local-speed benchmark + "your device is faster"
        # warning popup are suppressed everywhere.
        'disable_local_opt_warning': ui_config.get('disable_local_opt_warning', False),
        # True when the current session is a bug-report snapshot. The client
        # skips the local-speed benchmark + warning on snapshot sessions.
        'is_snapshot': _is_snapshot_session(session_uuid),
    }


@app.post("/api/local-speed-benchmark")
async def record_local_speed_benchmark(request: Request):
    """Record a per-device local-optimization speed benchmark sample.

    Best-effort calibration data: the client posts the Pyodide loop count after
    each benchmark run (auto on first load, or manual via the settings button).
    Always returns 200 so a failure here never disrupts the client.
    """
    try:
        body = await request.json()
    except Exception:
        body = {}
    count = body.get('count')
    if count is None:
        return {'status': 'ignored'}
    try:
        session_uuid = request.state.session_uuid
    except Exception:
        session_uuid = None
    get_db().record_local_speed_benchmark(
        session_uuid=session_uuid,
        count=count,
        run_ms=body.get('run_ms'),
        boot_ms=body.get('boot_ms'),
        faster=body.get('faster'),
        threshold=body.get('threshold'),
        user_agent=request.headers.get('user-agent'),
        source=body.get('source'),
    )
    return {'status': 'ok'}


@app.post("/api/optimization-settings")
async def save_optimization_settings(request: Request):
    """
    Save optimization sorting preferences to session.

    Request body:
        activity_sorting: List of [metric_key, weight] tuples where weight is int 0-100
        recipe_sorting: List of [metric_key, weight] tuples where weight is int 0-100
        activity_include_consumables: bool
        recipe_include_consumables: bool
    """
    body = await request.json()
    activity_sorting = body.get('activity_sorting', [])
    recipe_sorting = body.get('recipe_sorting', [])
    travel_sorting = body.get('travel_sorting', [])
    # Support both old per-type flags and new unified flag
    include_consumables = body.get('include_consumables',
        body.get('activity_include_consumables', False) or body.get('recipe_include_consumables', False)
    )
    auto_equip_optimized = body.get('auto_equip_optimized', False)
    auto_copy_export = body.get('auto_copy_export', False)
    lock_current_gear_slots = body.get('lock_current_gear_slots', False)
    include_pets = body.get('include_pets', False)
    show_non_owned_alternatives = body.get('show_non_owned_alternatives', False)
    skip_obtained_collectibles = body.get('skip_obtained_collectibles', True)
    run_local_optimization = body.get('run_local_optimization', False)
    finish_on_server_on_leave = body.get('finish_on_server_on_leave', False)
    disable_local_opt_warning = body.get('disable_local_opt_warning', False)

    def validate_sorting_tuples(sorting_list, is_activity=True):
        """Validate and normalize sorting entries to [key, weight, target] tuples with clamped weights.
        Also repairs corrupted keys from a previous bug where tuples were stringified.
        Allows duplicates for keys marked `duplicable` on the Sorting enum.
        When is_activity is True, migrates deprecated activity metric keys to
        steps_per_reward_roll with the appropriate category target. Pristine
        defaults outside the top N positions are stripped entirely for a
        cleaner UX — see ui/optimization_settings_migration.py."""
        from util.walkscape_constants import Sorting
        duplicable_keys = {s.metric_key for s in Sorting if s.duplicable}

        # For activity sorting, run the pristine-aware migration first, then
        # log the transition (once per session) before falling through to the
        # general validation/dedup pass below which handles non-activity keys
        # and further cleanups.
        if is_activity:
            from ui.optimization_settings_migration import migrate_activity_sorting
            before_snapshot = [
                list(entry) if isinstance(entry, (list, tuple)) else entry
                for entry in sorting_list
            ]
            migrated_list, action = migrate_activity_sorting(sorting_list)
            if action != 'none':
                try:
                    db = get_db()
                    if not db.has_optimization_settings_migration(session_uuid):
                        db.log_optimization_settings_migration(
                            session_uuid, action, before_snapshot, migrated_list,
                        )
                except Exception:
                    pass
            sorting_list = migrated_list
        # Deprecated-key migration is now a no-op here (handled above for activity);
        # recipe sorting never had these keys.
        deprecated_key_migration = {}

        def repair_key(key):
            if not isinstance(key, str):
                return key
            if ',' in key:
                repaired = key.split(',')[0].strip()
                if repaired:
                    return repaired
            return key

        def migrate(key, target):
            """Return (migrated_key, migrated_target) if key is deprecated."""
            if key in deprecated_key_migration:
                new_key, new_target = deprecated_key_migration[key]
                return new_key, target or new_target
            return key, target

        result = []
        seen_keys = set()
        for entry in sorting_list:
            # New X-per-Y dict form (activity AND recipe) — pass through
            # unchanged so migrate_activity_to_xy_form / migrate_recipe_sorting
            # downstream can handle them. Without this branch, the dict
            # entries fall into the `# Skip malformed entries` no-op below
            # and get silently dropped on save.
            if isinstance(entry, dict) and entry.get('mode') in ('ratio', 'budget'):
                result.append(entry)
                continue
            if isinstance(entry, str):
                key = repair_key(entry)
                key, target = migrate(key, None)
                if key in seen_keys and key not in duplicable_keys:
                    continue
                seen_keys.add(key)
                result.append([key, 100, target])
            elif isinstance(entry, (list, tuple)) and len(entry) >= 2:
                key = repair_key(entry[0])
                existing_target = entry[2] if len(entry) >= 3 else None
                key, existing_target = migrate(key, existing_target)
                if key in seen_keys and key not in duplicable_keys:
                    continue
                seen_keys.add(key)
                try:
                    weight = int(entry[1])
                except (ValueError, TypeError):
                    weight = 100
                weight = max(0, min(100, weight))
                result.append([key, weight, existing_target])
            # Skip malformed entries
        return result

    activity_sorting = validate_sorting_tuples(activity_sorting, is_activity=True)
    # Activity sorting: same X-per-Y dict treatment as recipe — pass any
    # legacy tuples that slipped through validate_sorting_tuples through
    # migrate_activity_to_xy_form so the saved value is the canonical
    # dict shape. New-form dict entries pass through unchanged.
    from ui.optimization_settings_migration import migrate_activity_to_xy_form
    activity_sorting, _activity_action = migrate_activity_to_xy_form(activity_sorting)
    # Recipe sorting: the frontend always sends the new dict form
    # (migrate_recipe_sorting handles any legacy tuples that slip through).
    # The migration function already validates/clamps weights and drops
    # unknown keys.
    from ui.optimization_settings_migration import migrate_recipe_sorting
    recipe_sorting, _recipe_action = migrate_recipe_sorting(recipe_sorting)

    # Travel sorting is a simple [metric_key, weight, target] tuple list over
    # the two TRAVEL metrics (total_steps, travel_steps_per_target). Validate
    # keys against the Sorting enum's TRAVEL members, clamp weights, keep
    # per-entry targets. Unknown keys are dropped. Empty list is allowed
    # (the optimizer falls back to minimizing Total Steps).
    def validate_travel_sorting(sorting_list):
        from util.walkscape_constants import Sorting, SortingType
        travel_keys = {
            s.metric_key for s in Sorting
            if SortingType.TRAVEL in s.types
        }
        duplicable_keys = {s.metric_key for s in Sorting if s.duplicable}
        result = []
        seen = set()
        for entry in (sorting_list or []):
            if isinstance(entry, (list, tuple)) and len(entry) >= 1:
                key = entry[0]
                try:
                    weight = int(entry[1]) if len(entry) >= 2 else 100
                except (ValueError, TypeError):
                    weight = 100
                target = entry[2] if len(entry) >= 3 else None
            elif isinstance(entry, str):
                key, weight, target = entry, 100, None
            else:
                continue
            if key not in travel_keys:
                continue
            weight = max(0, min(100, weight))
            dedup_key = f"{key}::{target}" if target else key
            if dedup_key in seen and key not in duplicable_keys:
                continue
            seen.add(dedup_key)
            result.append([key, weight, target])
        return result

    travel_sorting = validate_travel_sorting(travel_sorting)

    session_uuid = request.state.session_uuid
    log(f"Saving optimization settings:", session_uuid)
    log(f"  Activity sorting: {activity_sorting}", session_uuid)
    log(f"  Recipe sorting: {recipe_sorting}", session_uuid)
    log(f"  Activity include consumables: {include_consumables}", session_uuid)
    log(f"  Recipe include consumables: {include_consumables}", session_uuid)

    # Get session
    session = get_db().get_session(session_uuid)
    if not session:
        raise HTTPException(status_code=404, detail="Session not found")

    # Update UI config directly (not using update_config_path which has path logic)
    ui_config = session.get('ui_config', {})
    ui_config['optimize_sorting_activity'] = activity_sorting
    ui_config['optimize_sorting_recipe'] = recipe_sorting
    ui_config['optimize_sorting_travel'] = travel_sorting
    ui_config['include_consumables'] = include_consumables
    ui_config['auto_equip_optimized'] = auto_equip_optimized
    ui_config['auto_copy_export'] = auto_copy_export
    ui_config['lock_current_gear_slots'] = lock_current_gear_slots
    ui_config['include_pets'] = include_pets
    ui_config['show_non_owned_alternatives'] = show_non_owned_alternatives
    ui_config['skip_obtained_collectibles'] = skip_obtained_collectibles
    ui_config['run_local_optimization'] = run_local_optimization
    ui_config['finish_on_server_on_leave'] = finish_on_server_on_leave
    ui_config['disable_local_opt_warning'] = disable_local_opt_warning

    # `optimize_removed_activity` is no longer maintained on save — entries
    # are dicts now and per-entry `hiddenInQuick` is the source of truth.
    # The previous code below was buggy: after migrate_activity_to_xy_form,
    # every entry is a dict, so `isinstance(entry, (list, tuple))` was
    # always False, `saved_activity_keys` was always empty, and the diff
    # marked EVERY activity key as "removed". That value then got re-applied
    # on the next load by migrate_activity_to_xy_form's removed_keys path,
    # forcibly hiding every entry the user had unhid in the Quick panel.
    #
    # The legacy field is left alone (mirrors `optimize_removed_recipe` —
    # see comment below). It's effectively frozen and consulted only on
    # first-time migration, which the load-side `first_time_migration`
    # guard now enforces.
    # Leave optimize_removed_recipe alone on save (the migration function
    # reads it on first load and folds it into hiddenInQuick). We don't
    # rewrite it here — it's effectively frozen and can be cleaned up in a
    # later migration once every session has been migrated at least once.

    get_db().update_ui_config(session_uuid, ui_config)

    log(f"✓ Optimization settings saved", session_uuid)

    return {
        'success': True,
        'message': 'Optimization settings saved'
    }


# ============================================================================
# OPTIMIZATION PRESETS
# ============================================================================

@app.get("/api/optimization-presets/{preset_type}")
async def get_optimization_presets(preset_type: str, request: Request):
    """Get all optimization presets for a type ('activity' or 'recipe').

    Recipe presets are auto-migrated to the new X-per-Y dict form on
    read. Presets saved before the redesign contained legacy
    [key, weight, target] tuples; returning those to the frontend
    would make the Detailed/Quick panels silently drop them (they
    only understand the new dict form) and the user would see their
    saved preset as empty.
    """
    if preset_type not in ('activity', 'recipe', 'travel'):
        raise HTTPException(status_code=400, detail="preset_type must be 'activity', 'recipe', or 'travel'")
    session_uuid = request.state.session_uuid
    presets = get_db().get_optimization_presets(session_uuid, preset_type)

    if preset_type == 'recipe':
        from ui.optimization_settings_migration import migrate_recipe_sorting
        for p in presets:
            try:
                migrated, _ = migrate_recipe_sorting(p.get('sorting') or [])
                p['sorting'] = migrated
            except Exception as _e:
                # Best effort — if a specific preset has weird data, leave it
                # alone so the UI can at least still render a stub.
                log(f"[preset-migration] skipping preset id={p.get('id')} name={p.get('name')!r}: {_e}", session_uuid)
    elif preset_type == 'activity':
        from ui.optimization_settings_migration import migrate_activity_to_xy_form
        for p in presets:
            try:
                migrated, _ = migrate_activity_to_xy_form(p.get('sorting') or [])
                p['sorting'] = migrated
            except Exception as _e:
                log(f"[activity-preset-migration] skipping preset id={p.get('id')} name={p.get('name')!r}: {_e}", session_uuid)

    return presets


@app.post("/api/optimization-presets/{preset_type}")
async def save_optimization_preset(preset_type: str, request: Request):
    """
    Save or update an optimization preset.
    
    Request body:
        name: Preset name
        sorting: List of [metric_key, weight] tuples
        include_consumables: bool
        id: Optional preset ID for updates
    """
    if preset_type not in ('activity', 'recipe', 'travel'):
        raise HTTPException(status_code=400, detail="preset_type must be 'activity', 'recipe', or 'travel'")
    
    body = await request.json()
    name = body.get('name', '').strip()
    sorting = body.get('sorting', [])
    include_consumables = body.get('include_consumables', False)
    preset_id = body.get('id')

    if not name:
        raise HTTPException(status_code=400, detail="Preset name is required")

    session_uuid = request.state.session_uuid

    # Normalize recipe presets to the new X-per-Y dict form before saving
    # so legacy presets saved pre-redesign get migrated on first re-save,
    # and new presets never regress to the old tuple shape.
    if preset_type == 'recipe':
        from ui.optimization_settings_migration import migrate_recipe_sorting
        sorting, _ = migrate_recipe_sorting(sorting or [])
    elif preset_type == 'activity':
        from ui.optimization_settings_migration import migrate_activity_to_xy_form
        sorting, _ = migrate_activity_to_xy_form(sorting or [])
    
    try:
        preset = get_db().save_optimization_preset(
            session_uuid=session_uuid,
            name=name,
            preset_type=preset_type,
            sorting=sorting,
            include_consumables=include_consumables,
            preset_id=preset_id
        )
        log(f"✓ Saved optimization preset '{name}' ({preset_type})", session_uuid)
        return preset
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))


@app.delete("/api/optimization-presets/{preset_type}/{preset_id}")
async def delete_optimization_preset(preset_type: str, preset_id: str, request: Request):
    """Delete an optimization preset."""
    session_uuid = request.state.session_uuid
    deleted = get_db().delete_optimization_preset(session_uuid, preset_id)
    if not deleted:
        raise HTTPException(status_code=404, detail="Preset not found")
    log(f"✓ Deleted optimization preset {preset_id} ({preset_type})", session_uuid)
    return {'success': True}


# ============================================================================
# PINNED SAVES (Pin Item feature)
# ============================================================================

def _require_pin_item(session_uuid: str):
    """Raise HTTPException(403) if the session does not have the pin_item flag."""
    if not get_db().has_feature(session_uuid, 'pin_item'):
        raise HTTPException(status_code=403, detail='Pin Item feature not enabled')


@app.get("/api/pinned-saves")
async def get_pinned_saves(request: Request):
    """Return all pinned-save presets for the current session, newest first."""
    session_uuid = request.state.session_uuid
    _require_pin_item(session_uuid)
    return get_db().get_pinned_saves(session_uuid)


@app.post("/api/pinned-saves")
async def save_pinned_save(request: Request):
    """Create or update a pinned-save preset.

    Request body: { "name": str, "pin_paths": PinPath[], "id"?: str }

    Returns the saved preset dict. Upsert-by-name: if a preset with the same
    name already exists in this session, it is updated in place.
    """
    session_uuid = request.state.session_uuid
    _require_pin_item(session_uuid)
    body = await request.json()
    name = body.get('name', '')
    pin_paths = body.get('pin_paths', [])
    preset_id = body.get('id')
    try:
        preset = get_db().save_pinned_save(
            session_uuid=session_uuid,
            name=name,
            pin_paths=pin_paths,
            preset_id=preset_id,
        )
        log(f"✓ Saved pinned preset '{preset['name']}'", session_uuid)
        return preset
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))


@app.delete("/api/pinned-saves/{preset_id}")
async def delete_pinned_save(preset_id: str, request: Request):
    """Delete a pinned-save preset owned by the current session."""
    session_uuid = request.state.session_uuid
    _require_pin_item(session_uuid)
    deleted = get_db().delete_pinned_save(session_uuid, preset_id)
    if not deleted:
        raise HTTPException(status_code=404, detail='Preset not found')
    log(f"✓ Deleted pinned preset {preset_id}", session_uuid)
    return {'deleted': True}


