@app.get("/api/stats-report/results")
async def stats_report_results(request: Request):
    """Get all results for the most recent stats report run, grouped by category."""
    session_uuid = request.state.session_uuid
    if not get_db().has_feature(session_uuid, 'stats_report'):
        raise HTTPException(status_code=403, detail='Stats report feature not enabled')

    run = get_db().get_latest_stats_report_run(session_uuid)
    if not run:
        return {'success': True, 'run_id': None, 'results': {}}

    # 2026-06-11 (jwbail): read ADDITIVE results — the latest row per scope
    # across ALL of the session's runs, not just run['id']. A stale_only
    # re-run only writes rows for the stale scopes under a new run_id, so
    # the old run-scoped query dropped every unchanged scope and blanked
    # the report. run_id is still returned for the stale-banner key.
    results = get_db().get_stats_report_results_latest_per_scope(session_uuid)
    return {'success': True, 'run_id': run['id'], 'results': results}


@app.post("/api/stats-report/save-gearset")
async def stats_report_save_gearset(request: Request):
    """Copy a stats report result's gearset to the main gearsets table."""
    import uuid as _uuid
    from datetime import datetime, timezone

    session_uuid = request.state.session_uuid
    if not get_db().has_feature(session_uuid, 'stats_report'):
        raise HTTPException(status_code=403, detail='Stats report feature not enabled')

    body = await request.json()
    result_id = body.get('result_id', '').strip()
    if not result_id:
        return {'success': False, 'error': 'result_id required'}

    result = get_db().get_stats_report_gearset(result_id)
    if not result:
        return {'success': False, 'error': 'Result not found'}
    if result.get('session_uuid') != session_uuid:
        raise HTTPException(status_code=403, detail='Not your result')
    if not result.get('gearset_export'):
        return {'success': False, 'error': 'No gearset export for this result'}

    # Generate a clear, unique name. Format:
    #   "<source> - <type> - <location> - <date>"
    # e.g. "Craft triple rod rest - Carpentry chest farming - Halfling Campgrounds - 2026-06-16"
    # Location (not service name) is used per user direction: each location has
    # only one service of a given type, so the location is the unambiguous,
    # friendlier identifier. The old template emitted the raw category key for
    # chests_recipes ("... chests_recipes - <date>") because it wasn't in the
    # label map — that's fixed here too.
    import json as _json
    _md = {}
    try:
        _raw = result.get('metrics_json')
        if _raw:
            _md = _raw if isinstance(_raw, dict) else _json.loads(_raw)
    except Exception:
        _md = {}

    category = result.get('category', '') or ''
    source_name = result.get('activity_name') or result.get('skill_name') or 'Gearset'
    chest_name = (result.get('chest_name') or '').strip()
    skill_name = (result.get('skill_name') or '').strip()

    if category in ('chests_recipes', 'chests'):
        type_label = f'{chest_name} farming' if chest_name else 'Chest farming'
    elif category == 'xp':
        type_label = f'{skill_name} XP' if skill_name else 'XP'
    elif category == 'coins':
        type_label = 'Coin farming'
    elif category == 'new_items':
        # new_items rows carry the targeted drop in metrics_json.best_drop
        _item = ''
        try:
            _item = ((_md.get('best_drop') or {}).get('item_name') or '').strip()
        except Exception:
            _item = ''
        type_label = f'New item: {_item}' if _item else 'New item'
    else:
        type_label = category

    # Recipe rows carry service_location; activity rows may carry 'location'.
    location = (_md.get('service_location') or _md.get('location') or '').strip()

    date_str = datetime.now(timezone.utc).strftime('%Y-%m-%d')
    base_name = ' - '.join(p for p in (source_name, type_label, location, date_str) if p)

    # Get existing gearset names to avoid collision
    existing_gearsets = get_db().get_gear_sets(session_uuid) or []
    existing_names = {gs.get('name', '') for gs in existing_gearsets}

    # Append suffix if needed
    name = base_name
    counter = 2
    while name in existing_names:
        name = f'{base_name} ({counter})'
        counter += 1

    # Save to main gearsets table
    gear_set_id = str(_uuid.uuid4())
    get_db().save_gear_set(
        session_uuid=session_uuid,
        name=name,
        slots_json={},
        gear_set_id=gear_set_id,
        is_optimized=True,
        export_string=result['gearset_export'],
    )

    log(f'[stats_report] Saved gearset "{name}" from result {result_id}', session_uuid)
    return {'success': True, 'gear_set_id': gear_set_id, 'name': name}


@app.post("/api/stats-report/merge")
async def stats_report_merge(request: Request):
    """Add new jobs to an existing stats report run (merge mode)."""
    import subprocess
    import sys
    import uuid as _uuid

    session_uuid = request.state.session_uuid
    if not get_db().has_feature(session_uuid, 'stats_report'):
        raise HTTPException(status_code=403, detail='Stats report feature not enabled')

    body = await request.json()
    run_id = body.get('run_id', '').strip()
    categories = body.get('categories', [])
    skills = body.get('skills', [])
    # Mirror the run endpoint's optional flags. Default false so an older
    # client that doesn't send them keeps the previous "no pets/no
    # consumables" behavior.
    include_pets = bool(body.get('include_pets', False))
    include_consumables = bool(body.get('include_consumables', False))

    if not run_id:
        return {'success': False, 'error': 'run_id required'}

    # Validate run belongs to session
    run = get_db().get_stats_report_run(run_id)
    if not run:
        return {'success': False, 'error': 'Run not found'}
    if run.get('session_uuid') != session_uuid:
        raise HTTPException(status_code=403, detail='Not your run')

    # Spawn worker in merge mode
    worker_path = os.path.join(os.path.dirname(__file__), 'stats_report_worker.py')
    db_path = get_db().db_path
    cmd = [
        sys.executable, worker_path,
        '--session-uuid', session_uuid,
        '--run-id', run_id,
        '--db-path', db_path,
        '--categories', json.dumps(categories),
        '--skills', json.dumps(skills),
        '--notify', 'false',
        '--include-pets', 'true' if include_pets else 'false',
        '--include-consumables', 'true' if include_consumables else 'false',
        '--mode', 'merge',
    ]
    log_path = os.path.join('/tmp', f'stats_report_worker_{session_uuid[:8]}_{run_id[:8]}_merge.log')
    log_file = open(log_path, 'w')
    subprocess.Popen(cmd, stdout=log_file, stderr=log_file, start_new_session=True)
    log_file.close()
    log(f'[stats_report] Merge started for run {run_id} (log: {log_path})', session_uuid)

    updated_run = get_db().get_stats_report_run(run_id)
    return {
        'success': True,
        'run_id': run_id,
        'new_jobs_added': 0,  # Worker will update total_jobs
        'total_jobs': updated_run.get('total_jobs', 0) if updated_run else 0,
    }


@app.post("/api/stats-report/recalc-row")
async def stats_report_recalc_row(request: Request):
    """Recalculate a single row's metric for an arbitrary gearset.

    Used by the in-place gear-slot picker on the stats report results
    page (2026-05-21). When the user opens a row's gear preview, clicks
    a slot, and picks a different item from the popup, the frontend
    calls this endpoint with the modified gearset slots and gets back
    the same metric_value + metrics_json blob the worker would have
    written had this gearset come out of the optimizer.

    Request body:
        activity_name: str — full activity name (e.g. "Gold panning")
        skill_name: str — section skill ("Mining" or "Fishing" for Gold
                          panning depending on which section the row is in)
        category: str — 'xp' | 'coins' | 'chests' | 'chests_recipes'
        chest_name: str | None — only relevant for chest categories
        gearset_slots: dict — {slot: {itemId, quality, is_fine}, ...}
                              Same shape decode_gearset returns.

    Returns:
        success: bool
        metric_value: number — display value for the metric pill
        metric_name: str — label suffix
        metrics_json: dict — same breakdown the worker writes (used for
                             Total XP/step, secondary popover, steps-to-next)
    """
    session_uuid = request.state.session_uuid
    if not get_db().has_feature(session_uuid, 'stats_report'):
        raise HTTPException(status_code=403, detail='Stats report feature not enabled')

    body = await request.json()
    activity_name = body.get('activity_name', '')
    skill_name = body.get('skill_name', '')
    category = body.get('category', 'xp')
    chest_name = body.get('chest_name', None)
    gearset_slots = body.get('gearset_slots', {}) or {}

    if not activity_name:
        return {'success': False, 'error': 'activity_name required'}

    # ----- Look up activity by name -----
    from util.autogenerated.activities import ACTIVITIES_BY_NAME
    activity = ACTIVITIES_BY_NAME.get(activity_name)
    if not activity:
        return {'success': False, 'error': f'Activity not found: {activity_name}'}

    # ----- Build a Gearset from the slot dict -----
    # The frontend sends slots in the same shape decode_gearset emits:
    # {head: {itemId, quality, is_fine}, ...}. Look each up and build a
    # dict of {slot: Item} the optimize_activity_gearsets path expects.
    from util.autogenerated.equipment import Item as EquipmentItem
    from util.autogenerated.consumables import Consumable as ConsumableLookup
    from util.autogenerated.pets import PETS_BY_NAME

    gearset_dict = {}
    for slot, slot_data in gearset_slots.items():
        if not isinstance(slot_data, dict):
            continue
        item_id = slot_data.get('itemId') or slot_data.get('item_id')
        if not item_id:
            continue
        quality = slot_data.get('quality')
        is_fine = bool(slot_data.get('is_fine'))

        if slot == 'consumable':
            try:
                cons = ConsumableLookup.by_export_name(item_id)
                if is_fine and cons is not None and hasattr(cons, 'fine_variant'):
                    cons = cons.fine_variant() or cons
                if cons is not None:
                    gearset_dict['consumable'] = cons
            except Exception:
                pass
            continue

        if slot == 'pet':
            # Pets are looked up by species + level; the frontend should
            # send species in itemId and level in slot_data.level.
            level = int(slot_data.get('level') or 0)
            species = str(item_id).capitalize()
            pet_levels = PETS_BY_NAME.get(species)
            if pet_levels and level > 0:
                pet_info = pet_levels.get_level(level)
                if pet_info:
                    gearset_dict['pet'] = pet_info
            continue

        # Equipment slots
        # 2026-06-04 (jwbail): resolve via Item.by_uuid. Item has NO
        # by_id method — the old EquipmentItem.by_id(item_id, ...) call
        # raised AttributeError on every slot, was swallowed by the bare
        # except, and left gearset_dict EMPTY. The frontend payload
        # carries uuid + rarity; by_uuid maps the rarity string to the
        # crafted quality tier. Mirrors the working col-2 / crafting-tree
        # resolution (app.py ~line 5226).
        try:
            uuid_val = slot_data.get('uuid')
            rarity_val = slot_data.get('rarity')
            # Altered-slot edits (in-place picker) may carry a quality
            # NAME (Great/Perfect) rather than a rarity; map it so
            # crafted variants resolve to the right tier.
            if not rarity_val and quality:
                _qn = {'normal': 'common', 'good': 'uncommon', 'great': 'rare',
                       'excellent': 'epic', 'perfect': 'legendary', 'eternal': 'ethereal'}
                rarity_val = _qn.get(str(quality).lower(), quality)
            item = EquipmentItem.by_uuid(uuid_val, quality=rarity_val) if uuid_val else None
            if item is not None:
                gearset_dict[slot] = item
        except Exception:
            pass

    # ----- Load character -----
    try:
        session = get_db().get_session(session_uuid)
        char_config = (session or {}).get('character_config') or {}
    except Exception:
        char_config = {}

    from util.character_export_util import Character as DbCharacter
    try:
        # Character.__init__ wants a JSON string (per stats_report_worker
        # commit 9f944750). Re-serialize.
        char_json = json.dumps(char_config) if isinstance(char_config, dict) else (char_config or '{}')
        character = DbCharacter(char_json)
    except Exception:
        return {'success': False, 'error': 'Failed to load character'}

    # ----- Compute metrics -----
    import optimize_activity_gearsets
    try:
        # calculate_gearset_metrics returns (metrics, total_stats). The
        # metrics dict carries everything we need: primary_xp_per_step,
        # steps_per_reward_roll, expected_steps_per_action, etc.
        # Pass the activity in via SELECTED_LOCATION = None (worker also
        # leaves this None) — location-scoped stats fall back to global.
        prev_loc = optimize_activity_gearsets.SELECTED_LOCATION
        try:
            optimize_activity_gearsets.SELECTED_LOCATION = None
            final_metrics, total_stats = optimize_activity_gearsets.calculate_gearset_metrics(
                gearset_dict, activity, character, final=True
            )
        finally:
            optimize_activity_gearsets.SELECTED_LOCATION = prev_loc
    except Exception as e:
        log(f'[stats_report] recalc-row failed for {activity_name}: {e}', session_uuid)
        return {'success': False, 'error': f'Calculation failed: {e}'}

    # ----- Build the same per-skill XP/step breakdown the worker writes.
    # Mirrors stats_report_worker.run_optimizer_for_job lines ~330-370.
    bonus_xp_pct = float(total_stats.get('bonus_xp_percent', 0.0)) if total_stats else 0.0
    bonus_xp_add = float(total_stats.get('bonus_xp_add', 0.0)) if total_stats else 0.0
    secondary_xp_base = getattr(activity, 'secondary_xp', None) or {}
    secondary_xp_per_action = {
        sk: float(base) * (1.0 + bonus_xp_pct) + bonus_xp_add
        for sk, base in secondary_xp_base.items() if base
    }
    expected_steps = final_metrics.get('expected_steps_per_action') or 0
    primary_xp_per_action = final_metrics.get('primary_xp_per_action') or 0
    primary_xp_per_step = final_metrics.get('primary_xp_per_step') or 0
    primary_skill = getattr(activity, 'primary_skill', None)
    xp_per_step_by_skill = {}
    if primary_skill and expected_steps > 0:
        xp_per_step_by_skill[primary_skill] = primary_xp_per_action / expected_steps
    for sk, xp_per_action in secondary_xp_per_action.items():
        if expected_steps > 0:
            xp_per_step_by_skill[sk] = xp_per_action / expected_steps
    total_xp_per_step = sum(xp_per_step_by_skill.values())

    metrics_breakdown = {
        'primary_skill': primary_skill,
        'displayed_steps_per_action': final_metrics.get('displayed_steps_per_action'),
        'expected_steps_per_action': expected_steps,
        'primary_xp_per_action': primary_xp_per_action,
        'primary_xp_per_step': primary_xp_per_step,
        'secondary_xp_per_action': secondary_xp_per_action,
        'xp_per_step_by_skill': xp_per_step_by_skill,
        'total_xp_per_step': total_xp_per_step,
        'bonus_xp_percent': bonus_xp_pct,
        'bonus_xp_add': bonus_xp_add,
    }

    # ----- Pick the metric_value for this category, mirroring the worker.
    if category == 'xp':
        if skill_name and skill_name in xp_per_step_by_skill:
            metric_value = xp_per_step_by_skill[skill_name]
        else:
            metric_value = primary_xp_per_step
        metric_name = 'XP/step'
    elif category == 'coins':
        metric_value = final_metrics.get('steps_per_reward_roll', activity.base_steps)
        metric_name = 'Steps/reward'
    elif category in ('chests', 'chests_recipes'):
        metric_value = final_metrics.get('steps_per_reward_roll', activity.base_steps)
        metric_name = f'Steps/chest ({chest_name or "chest"})'
    else:
        metric_value = final_metrics.get('steps_per_reward_roll', activity.base_steps)
        metric_name = 'Steps/reward'

    return {
        'success': True,
        'metric_value': metric_value,
        'metric_name': metric_name,
        'metrics_json': metrics_breakdown,
    }


@app.post("/api/stats-report/slot-alternatives")
async def stats_report_slot_alternatives(request: Request):
    """Compute non-owned/locked item alternatives for a stats-report row's
    current gearset, ranked by improvement to the row's metric.

    Used by the in-place gear-slot picker (2026-05-21). Frontend calls
    this once per row when the gear preview expands; result is cached on
    the row so subsequent slot clicks reuse it. The popup renders the
    returned alternatives via its existing
    treeNodeContext.alternatives / .lockedAlternatives plumbing — no new
    UI code, just data.

    Internally delegates to ui.optimize_worker.compute_slot_alternatives
    (the same call the column-2 + crafting-tree paths use). For XP rows
    we set sorting_priority=[Sorting.XP_PER_STEP] so the improvement
    delta is the per-step XP delta, exactly what the user asked for.
    For coin / chest rows we use STEPS_PER_REWARD_ROLL (lower is better,
    same as the optimizer).

    Request body:
        activity_name: str
        skill_name: str
        category: str — 'xp' | 'coins' | 'chests' | 'chests_recipes'
        chest_name: str | None
        gearset_slots: dict — same shape as decode_gearset emits
    """
    session_uuid = request.state.session_uuid
    if not get_db().has_feature(session_uuid, 'stats_report'):
        raise HTTPException(status_code=403, detail='Stats report feature not enabled')

    body = await request.json()
    activity_name = body.get('activity_name', '')
    skill_name = body.get('skill_name', '')
    category = body.get('category', 'xp')
    chest_name = body.get('chest_name', None)
    gearset_slots = body.get('gearset_slots', {}) or {}

    if not activity_name:
        return {'success': False, 'error': 'activity_name required'}

    # 2026-06-02 (jwbail): chests_recipes rows store the RECIPE display
    # name in activity_name (the row's "what is this row about" field).
    # The endpoint previously looked it up in ACTIVITIES_BY_NAME which
    # always returned None, so alternatives silently failed for every
    # recipe row. Branch on category so chests_recipes uses the recipe
    # optimizer path with opt_type='recipe'; other categories keep the
    # activity path.
    activity = None
    recipe = None
    service_for_recipe = None
    if category == 'chests_recipes':
        from util.autogenerated.recipes import RECIPES_BY_NAME
        recipe = RECIPES_BY_NAME.get(activity_name)
        if not recipe:
            return {'success': False, 'error': f'Recipe not found: {activity_name}'}
        # Resolve a service for the recipe so the optimizer scores
        # against the right service-tier work efficiency. Prefer the
        # alphabetic-first match for now (matches what the worker
        # historically wrote — the multi-service iteration runs in the
        # WORKER, not in the alternatives endpoint).
        try:
            from util.autogenerated.services import SERVICES_BY_NAME
            svc_name = getattr(recipe, 'service', None)
            if svc_name and svc_name not in ('None', 'NONE', ''):
                # We need character to call is_unlocked — load it now so
                # we can validate. Cheap: just pulls character_config.
                _sess_for_svc = get_db().get_session(session_uuid)
                _cc_for_svc = (_sess_for_svc or {}).get('character_config') or {}
                if isinstance(_cc_for_svc, str):
                    _cc_for_svc = json.loads(_cc_for_svc)
                from util.character_export_util import Character as _Char
                _c_for_svc = _Char(json.dumps(_cc_for_svc))
                for _svc in SERVICES_BY_NAME.values():
                    try:
                        if _svc.is_valid_for_recipe(recipe) and _svc.is_unlocked(_c_for_svc):
                            service_for_recipe = _svc
                            break
                    except Exception:
                        continue
        except Exception:
            pass
    else:
        from util.autogenerated.activities import ACTIVITIES_BY_NAME
        activity = ACTIVITIES_BY_NAME.get(activity_name)
        if not activity:
            return {'success': False, 'error': f'Activity not found: {activity_name}'}

    from util.autogenerated.equipment import Item as EquipmentItem
    from util.autogenerated.consumables import Consumable as ConsumableLookup
    from util.autogenerated.pets import PETS_BY_NAME

    gearset_dict = {}
    consumable_obj = None
    for slot, slot_data in gearset_slots.items():
        if not isinstance(slot_data, dict):
            continue
        item_id = slot_data.get('itemId') or slot_data.get('item_id')
        if not item_id:
            continue
        quality = slot_data.get('quality')
        is_fine = bool(slot_data.get('is_fine'))

        if slot == 'consumable':
            try:
                cons = ConsumableLookup.by_export_name(item_id)
                if is_fine and cons is not None and hasattr(cons, 'fine_variant'):
                    cons = cons.fine_variant() or cons
                if cons is not None:
                    consumable_obj = cons
            except Exception:
                pass
            continue

        if slot == 'pet':
            level = int(slot_data.get('level') or 0)
            species = str(item_id).capitalize()
            pet_levels = PETS_BY_NAME.get(species)
            if pet_levels and level > 0:
                pet_info = pet_levels.get_level(level)
                if pet_info:
                    gearset_dict['pet'] = pet_info
            continue

        # 2026-06-04 (jwbail): resolve via Item.by_uuid. Item has NO
        # by_id method — the old EquipmentItem.by_id(item_id, ...) raised
        # AttributeError on every slot, was swallowed by the bare except,
        # and left gearset_dict EMPTY -> compute_slot_alternatives had no
        # slots to check -> the "non-owned / locked upgrades" section was
        # ALWAYS empty for BOTH chests and chests_recipes rows. The
        # frontend payload carries uuid + rarity; by_uuid maps the rarity
        # to the crafted quality tier. Mirrors the working col-2 path.
        try:
            uuid_val = slot_data.get('uuid')
            rarity_val = slot_data.get('rarity')
            if not rarity_val and quality:
                _qn = {'normal': 'common', 'good': 'uncommon', 'great': 'rare',
                       'excellent': 'epic', 'perfect': 'legendary', 'eternal': 'ethereal'}
                rarity_val = _qn.get(str(quality).lower(), quality)
            item = EquipmentItem.by_uuid(uuid_val, quality=rarity_val) if uuid_val else None
            if item is not None:
                gearset_dict[slot] = item
        except Exception:
            pass

    # Load character
    try:
        session = get_db().get_session(session_uuid)
        char_config = (session or {}).get('character_config') or {}
    except Exception:
        session = None
        char_config = {}

    # 2026-06-17 (jwbail): respect the user's hide list in the non-owned /
    # locked upgrades panel so it never suggests hidden gear / items /
    # collectibles / eggs. Same source the optimizer uses.
    try:
        from ui.optimize_worker import build_hidden_items_set
        _ui_config = (session or {}).get('ui_config') or {}
        if isinstance(_ui_config, str):
            _ui_config = json.loads(_ui_config)
        _hidden_items = build_hidden_items_set(_ui_config)
    except Exception:
        _hidden_items = set()

    # 2026-06-25 (jwbail): build the character with load_character — which
    # reconstructs the OWNED inventory from `all_items_raw` (plus column-1
    # quality overrides + the custom-stats toggle) — NOT a bare
    # Character(character_config). The `sessions` row stores only
    # character_config + ui_config; character_config does NOT carry the raw
    # inventory dict (see stats_report_worker.load_character docstring), so
    # Character(character_config).items is EMPTY. With no owned items,
    # compute_slot_alternatives recognizes NOTHING as owned and every
    # owned-but-locked item leaks into the NON-OWNED bucket instead of
    # "Owned but locked" (locked_alternatives comes back empty). This is the
    # goals-report-only divergence the user reported (2026-06-25): the
    # worker-stored path already uses load_character and is correct, but
    # this on-demand endpoint — used for edited rows / when no stored alts
    # exist — built the character wrong. The normal optimizer and crafting
    # tree never hit this path, which is why only the goals report was
    # affected. Fall back to the bare build only if load_character fails.
    from util.character_export_util import Character as DbCharacter
    character = None
    try:
        from ui import stats_report_worker as _srw_char
        character = _srw_char.load_character(session_uuid, get_db().db_path)
    except Exception as _lc_e:
        print(f'[slot-alternatives] load_character failed ({_lc_e}); '
              f'falling back to character_config-only build', flush=True)
    if character is None:
        try:
            char_json = json.dumps(char_config) if isinstance(char_config, dict) else (char_config or '{}')
            character = DbCharacter(char_json)
        except Exception:
            return {'success': False, 'error': 'Failed to load character'}

    # Pick the sorting priority that matches the row's category. Same
    # mapping the worker uses (stats_report_worker.run_optimizer_for_job).
    from util.walkscape_constants import Sorting, SortingEntry
    if category == 'xp':
        sorting_priority = [Sorting.XP_PER_STEP]
        sorting_weights = {Sorting.XP_PER_STEP: 100}
        target_obj = None
    elif category == 'coins':
        # 2026-06-04 (jwbail): coin rows score against the cat:coins
        # target (steps per coin), exactly like the worker
        # (run_optimizer_for_job reads steps_per_reward_roll::cat:coins).
        # The old bare Sorting.STEPS_PER_REWARD_ROLL read the activity's
        # raw_rewards headline instead, so the alternatives' improvement
        # ratio reflected raw rewards, NOT coins — coin-finding gear that
        # only helps coins (not raw rewards) was invisible, and the
        # numbers were on the wrong axis. Target-aware SortingEntry +
        # TARGET_ITEM='cat:coins' (compute_slot_alternatives sets the
        # activity TARGET_ITEM from target_obj) emits + reads the right
        # composite key.
        sorting_priority = [SortingEntry(sort=Sorting.STEPS_PER_REWARD_ROLL, target='cat:coins')]
        sorting_weights = {Sorting.STEPS_PER_REWARD_ROLL: 100}
        target_obj = 'cat:coins'
    elif category == 'chests_recipes':
        # 2026-06-02 (jwbail): recipe optimizer scores by
        # steps_per_chest_recipe, not steps_per_reward_roll. Wrong
        # sorting key was producing zero-score alternatives that all
        # got pruned, surfacing as "No better alternatives" for every
        # slot on chests_recipes rows.
        # 2026-06-04 (jwbail): make it TARGET-AWARE on cat:chests so the
        # comparator reads steps_per_chest_recipe::cat:chests — the same
        # composite the worker stores (run_recipe_optimizer reads
        # steps_per_chest_recipe::cat:chests). The bare key read a
        # different headline target, so the improvement ratio (and the
        # numbers) were on the wrong axis vs the row.
        sorting_priority = [SortingEntry(sort=Sorting.STEPS_PER_CHEST_RECIPE, target='cat:chests')]
        sorting_weights = {Sorting.STEPS_PER_CHEST_RECIPE: 100}
        target_obj = chest_name or None
    elif category == 'chests':
        # 2026-06-04 (jwbail): chest-farming-for-ACTIVITIES rows. The
        # chest-specific composite key steps_per_reward_roll::<chest>
        # is only emitted by calculate_gearset_metrics when the
        # optimizer's TARGET_ITEM / SORTING_PRIORITY drive it (see
        # optimize_activity_gearsets._effective_targets_for_scoring).
        # Pass a TARGET-AWARE SortingEntry so the comparator reads the
        # chest composite, and compute_slot_alternatives sets TARGET_ITEM
        # during scoring so the composite is actually present. Without
        # the target, the comparator fell back to the bare
        # steps_per_reward_roll (raw_rewards headline, NOT the chest) and
        # almost nothing scored as an improvement -> the "non-owned /
        # locked upgrades" section stayed empty. (chests_recipes never
        # had this bug because it uses the recipe optimizer whose
        # steps_per_chest_recipe metric is emitted natively.)
        from util.walkscape_constants import SortingEntry as _SortingEntry
        sorting_priority = [_SortingEntry(sort=Sorting.STEPS_PER_REWARD_ROLL, target=chest_name)] \
            if chest_name else [Sorting.STEPS_PER_REWARD_ROLL]
        sorting_weights = {Sorting.STEPS_PER_REWARD_ROLL: 100}
        target_obj = chest_name or None
    elif category == 'new_items':
        # 2026-06-05 (jwbail): new_items rows farm a SPECIFIC drop
        # (collectible / gear / tool / egg). The worker scored the row on
        # steps_per_reward_roll::<best_drop> (run_optimizer_for_job sets
        # TARGET_ITEM = best_drop_name) — which is find_collectibles-aware
        # for collectible drops. The endpoint previously fell through to
        # the bare STEPS_PER_REWARD_ROLL (raw reward throughput / work-
        # efficiency only), so find_collectibles gear (e.g. Jade tipped
        # steel pan) never surfaced as an upgrade and the item set + rank
        # diverged from the real optimizer (user-reported: collectibles
        # row missing 6 of 7 upgrades). Make it target-aware on the row's
        # drop item so compute_slot_alternatives sets TARGET_ITEM and the
        # composite key steps_per_reward_roll::<drop> drives scoring.
        target_name = body.get('target_item') or None
        sorting_priority = [SortingEntry(sort=Sorting.STEPS_PER_REWARD_ROLL, target=target_name)] \
            if target_name else [Sorting.STEPS_PER_REWARD_ROLL]
        sorting_weights = {Sorting.STEPS_PER_REWARD_ROLL: 100}
        target_obj = target_name
    else:
        sorting_priority = [Sorting.STEPS_PER_REWARD_ROLL]
        sorting_weights = {Sorting.STEPS_PER_REWARD_ROLL: 100}
        target_obj = None

    # compute_slot_alternatives lives in optimize_worker — it walks every
    # game item, slots it in, scores against the current gearset, and
    # returns the items that beat the current pick. Capped at top_n=10
    # per slot for UI sanity (matches the column-2 default).
    try:
        from ui.optimize_worker import compute_slot_alternatives
        # 2026-06-02 (jwbail): chests_recipes branches into the recipe
        # optimizer path. Without this, opt_type='activity' + activity=None
        # returned no alternatives for every recipe slot click.
        if category == 'chests_recipes':
            alts, locked_alts = compute_slot_alternatives(
                gearset_dict, character, 'recipe',
                recipe=recipe,
                service=service_for_recipe,
                consumable=consumable_obj,
                sorting_priority=sorting_priority,
                sorting_weights=sorting_weights,
                target_item=target_obj,
                target_drop_rate=0,
                selected_location=None,
                input_item=None,
                use_fine_inputs=False,
                hidden_items=_hidden_items,
                top_n=10,
            )
        else:
            # 2026-07-08 (jwbail): resolve the row's accessible location + input
            # item so on-demand alternatives are scored in the SAME environment
            # the worker used (location-scoped gear stats + input-derived
            # stats). Previously both were None, so location-scoped activities
            # (desert/underwater/etc.) ranked items differently than the row.
            # The worker no longer precomputes alternatives, so this endpoint is
            # now the sole source and must reproduce that environment.
            _sel_loc = None
            _input_item = None
            try:
                from ui.stats_report_worker import (
                    _activity_first_accessible_location as _afal,
                    _auto_pick_input_item_for_activity as _apii,
                )
                _loc = _afal(activity)
                if _loc is not None and not isinstance(_loc, str):
                    _sel_loc = _loc
                _input_item = _apii(activity, character)
            except Exception:
                _sel_loc = None
                _input_item = None
            alts, locked_alts = compute_slot_alternatives(
                gearset_dict, character, 'activity',
                activity=activity,
                consumable=consumable_obj,
                sorting_priority=sorting_priority,
                sorting_weights=sorting_weights,
                target_item=target_obj,
                target_drop_rate=0,
                selected_location=_sel_loc,
                input_item=_input_item,
                use_fine_inputs=False,
                hidden_items=_hidden_items,
                top_n=10,
            )
    except Exception as e:
        log(f'[stats_report] slot-alternatives failed for {activity_name}: {e}', session_uuid)
        return {'success': False, 'error': f'Alternatives calculation failed: {e}'}

    return {
        'success': True,
        'alternatives': alts or {},
        'locked_alternatives': locked_alts or {},
    }


def run_optimization_background(
    session_uuid: str,
    opt_type: str,
    opt_id: str,
    sorting_priority: list,
    character_config: dict,
    target_item: str = None,
    target_quality: str = 'Perfect',
    service_id: str = None,
    include_consumables: bool = False,
    budget_materials: int = 0,
    budget_target: int = 0,
    locked_slots: dict = None,
    selected_location: str = None,
    target_drop_rate: float = 0,
    input_items: dict = None,
    use_fine_inputs: bool = False,
    include_pets: bool = False,
    target_slot: int = None,
    equipped_consumable: dict = None,
    equipped_pet: dict = None,
    instant_actions: bool = False,
    pet_ability_stats: bool = False,
):
    """
    Spawn optimization as a fully detached subprocess that saves directly to DB.

    The worker process runs independently of uvicorn, so it survives file reloads.
    It writes results directly to the database via --db-save flag.

    Race-safe cancel: we check _cancelled_optimizations at three points
    (before spawn, after spawn, after DB record write) so that a cancel
    arriving at any point during startup is honoured instead of leaving a
    runaway worker that blocks future runs with "Optimization already running".
    """
    import sys
    import os
    import subprocess
    import json
    import tempfile
    import signal as _signal

    def _bail_cancelled(reason: str, proc=None, had_db_record: bool = False):
        """Common cleanup path when a cancel is detected during startup."""
        log(f"Optimization cancelled during startup ({reason}); cleaning up", session_uuid)
        if proc is not None:
            try:
                os.kill(proc.pid, _signal.SIGTERM)
            except Exception as _e:
                log(f"Cancel: failed to SIGTERM new PID {proc.pid}: {_e}", session_uuid)
        if had_db_record:
            try:
                get_db().finish_optimization(session_uuid, exit_code=-15)
            except Exception as _e:
                log(f"Cancel: failed to finish_optimization record: {_e}", session_uuid)
        # Signal SSE so the frontend stops waiting. Leave the cancel flag
        # intact so /api/optimization-cancel/check returns True to the poller.
        _event = _optimization_events.get(session_uuid)
        if _event and _optimization_event_loop:
            _optimization_event_loop.call_soon_threadsafe(_event.set)

    try:
        # RACE CHECK #1: Cancel could have arrived between POST return and
        # this background task starting. If so, bail before doing any work.
        # NOTE: the DB record was already written by the POST endpoint to
        # close the SSE race, so we must clean it up on bail.
        if session_uuid in _cancelled_optimizations:
            _bail_cancelled("pre-spawn", had_db_record=True)
            return

        # Get ui_config for hide states
        session = get_db().get_session(session_uuid)
        ui_config = session.get('ui_config', {}) if session else {}

        # Create a temporary file with the optimization request
        # Use delete=False so the worker can read it after we return
        with tempfile.NamedTemporaryFile(mode='w', suffix='.json', delete=False) as f:
            request_data = _build_worker_request_data(
                opt_type, opt_id, sorting_priority, character_config, ui_config,
                target_item, target_quality, target_drop_rate, service_id,
                include_consumables, include_pets, budget_materials, budget_target,
                locked_slots, selected_location, input_items, use_fine_inputs,
                target_slot, equipped_consumable, equipped_pet, instant_actions,
                pet_ability_stats,
            )
            json.dump(request_data, f)
            temp_file = f.name

        # PROTOTYPE (Pyodide hybrid): stash the exact request the worker
        # receives so the client-side benchmark harness can replay an
        # identical real workload. Best-effort; never affects the run.
        try:
            with open(_PYODIDE_LAST_REQUEST_PATH, 'w') as _rf:
                json.dump(request_data, _rf)
        except Exception:
            pass

        # Get the project root directory (parent of ui/)
        project_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        
        # Resolve the database path so the worker can find it
        db_path = os.path.join(os.getcwd(), DATABASE_PATH)
        
        # Build command with --db-save so worker persists results directly
        cmd = [
            sys.executable, '-m', 'ui.optimize_worker',
            temp_file,
            '--db-save', session_uuid, db_path,
            json.dumps(sorting_priority)
        ]
        
        log(f"Starting detached optimization subprocess...", session_uuid)
        log(f"  Command: {' '.join(cmd[:5])}...", session_uuid)
        log(f"  DB path: {db_path}", session_uuid)
        
        # Spawn as a fully detached process using start_new_session=True
        # This ensures the worker survives uvicorn reloads
        # Write stderr to /tmp to avoid triggering uvicorn's --reload watcher
        log_path = os.path.join('/tmp', f'optimize_worker_{session_uuid[:8]}.log')
        log_file = open(log_path, 'w')  # 'w' to overwrite previous run's log
        proc = subprocess.Popen(
            cmd,
            cwd=project_root,
            stdout=subprocess.DEVNULL,
            stderr=log_file,
            start_new_session=True,
            env={**os.environ, 'PYTHONPATH': project_root}
        )
        # Close our copy of the file handle — child process has its own
        log_file.close()

        # RACE CHECK #2: Cancel could have arrived during Popen. The DB
        # record was pre-created by the POST endpoint (to close the SSE
        # race), so had_db_record is always True here.
        if session_uuid in _cancelled_optimizations:
            _bail_cancelled("post-spawn-pre-db-record", proc=proc, had_db_record=True)
            return

        # Update the pre-created DB record with the real PID. INSERT OR
        # REPLACE overwrites the pid=None entry written by the POST handler.
        get_db().start_optimization(session_uuid, opt_type, opt_id, pid=proc.pid)

        # RACE CHECK #3: Cancel could have arrived between Popen and the DB
        # record update above. Kill the worker and clear the record.
        if session_uuid in _cancelled_optimizations:
            _bail_cancelled("post-db-record", proc=proc, had_db_record=True)
            return

        # NOTE: we do NOT discard the cancel flag here. The POST
        # /api/optimize-gearset endpoint clears any stale flag atomically at
        # start, and discarding here would silently drop a cancel request
        # that arrived during the race windows above. Any flag still present
        # will be consumed by /api/optimization-cancel/check when the
        # frontend finishes polling.
        
        log(f"✓ Optimization subprocess spawned (PID: {proc.pid})", session_uuid)
        log(f"  Worker log: {log_path}", session_uuid)
        log(f"  Worker will save results directly to DB when complete", session_uuid)
        
        # Start a background thread to tail the worker log and forward to app log
        import threading
        def _tail_worker_log(pid, path, sess_uuid):
            """Wait for worker to finish, then dump its log to the app log."""
            import time as _time
            max_wait = 120  # 2 minute timeout
            start = _time.time()
            finished = False
            try:
                while _time.time() - start < max_wait:
                    try:
                        result = os.waitpid(pid, os.WNOHANG)
                        if result[0] != 0:
                            finished = True
                            exit_code = os.WEXITSTATUS(result[1]) if os.WIFEXITED(result[1]) else -1
                            break
                    except ChildProcessError:
                        finished = True
                        exit_code = -1
                        break
                    _time.sleep(0.5)
                
                if not finished:
                    log(f"  [worker] ⚠ Worker still running after {max_wait}s — killing PID {pid}", sess_uuid)
                    try:
                        os.kill(pid, 9)
                        os.waitpid(pid, 0)
                    except Exception:
                        pass
                    exit_code = -9
            except Exception:
                exit_code = -1
            
            try:
                with open(path, 'r') as f:
                    lines = f.read().strip().split('\n')
                if lines and lines[0]:
                    for line in lines:
                        log(f"  [worker] {line}", sess_uuid)
                else:
                    log(f"  [worker] ⚠ Worker log is empty (exit code: {exit_code})", sess_uuid)
                if exit_code != 0:
                    log(f"  [worker] ⚠ Worker exited with code {exit_code}", sess_uuid)
            except Exception as _e:
                log(f"  [worker] ⚠ Could not read worker log: {_e}", sess_uuid)
            # If worker crashed or timed out, clean up the active optimization record
            # so the UI stops polling. (Normal completion cleans up inside the worker.)
            if exit_code != 0:
                try:
                    get_db().finish_optimization(sess_uuid, exit_code=exit_code)
                    log(f"  [worker] Cleaned up active optimization after crash/timeout", sess_uuid)
                except Exception:
                    pass
            # Signal the SSE event so the frontend gets notified instantly
            event = _optimization_events.get(sess_uuid)
            if event and _optimization_event_loop:
                log(f"  [worker] Signaling SSE done event", sess_uuid)
                _optimization_event_loop.call_soon_threadsafe(event.set)
            else:
                log(f"  [worker] ⚠ No SSE event to signal (event={event is not None}, loop={_optimization_event_loop is not None})", sess_uuid)
        
        threading.Thread(
            target=_tail_worker_log,
            args=(proc.pid, log_path, session_uuid),
            daemon=True
        ).start()
        
    except Exception as e:
        import traceback
        log(f"Failed to start optimization: {traceback.format_exc()}", session_uuid)
        # Clean up on failure
        get_db().finish_optimization(session_uuid)


@app.get("/api/feature-flags")
async def get_feature_flags(request: Request):
    """Return which features are enabled for the current session."""
    session_uuid = request.state.session_uuid
    flags = {
        "travel": get_db().has_feature(session_uuid, "travel"),
        "generic": False,  # Globally disabled — re-enable when generic definitions are ready
        "non_owned_alternatives": True,  # Released to all users
        "april_fools": get_db().has_april_fools(session_uuid),
        "comparison_view": True,  # Released to all users
        "crafting_tree": get_db().has_feature(session_uuid, "crafting_tree"),
        "crafting_tree_lp": get_db().has_feature(session_uuid, "crafting_tree_lp"),
        "stats_report": get_db().has_feature(session_uuid, "stats_report"),
        "pin_item": get_db().has_feature(session_uuid, "pin_item"),
        "sell_for_chips": True,  # Released to all users (FAC gate removed)
        "local_optimization": get_db().has_feature(session_uuid, "local_optimization"),
        "walkdle": _walkdle_enabled(request),
        "notepad": get_db().has_feature(session_uuid, "notepad"),
    }
    log(f"Feature flags for {session_uuid}: crafting_tree={flags['crafting_tree']} crafting_tree_lp={flags['crafting_tree_lp']}", session_uuid)
    return flags


# ============================================================================
# NOTEPAD ENDPOINTS (FAC-gated; see .kiro/NOTEPAD_SPEC.md)
# ============================================================================

_NOTE_MAX_BYTES = 200 * 1024   # ~200 KB per note
_NOTE_MAX_COUNT = 200          # soft cap on notes per session


def _require_notepad(session_uuid: str):
    """Raise HTTPException(403) unless the notepad flag is enabled (ACTIONS only)."""
    if not get_db().has_feature(session_uuid, 'notepad'):
        raise HTTPException(status_code=403, detail="Notepad is not enabled for this session")


@app.get("/api/notes")
async def notes_list(request: Request):
    """List the session's notes. Benign 200 when the feature is off (polled on open)."""
    session_uuid = request.state.session_uuid
    if not get_db().has_feature(session_uuid, 'notepad'):
        return {"enabled": False, "notes": [], "selected_note_id": None}
    return {
        "enabled": True,
        "notes": get_db().list_notes(session_uuid),
        "selected_note_id": get_db().get_selected_note(session_uuid),
    }


@app.get("/api/notes/{note_id}")
async def notes_get(note_id: str, request: Request):
    """Return one note's full content. Benign 200 when the feature is off."""
    session_uuid = request.state.session_uuid
    if not get_db().has_feature(session_uuid, 'notepad'):
        return {"enabled": False, "note": None}
    note = get_db().get_note(session_uuid, note_id)
    if not note:
        raise HTTPException(status_code=404, detail="Note not found")
    return {"enabled": True, "note": note}


@app.post("/api/notes")
async def notes_create(request: Request):
    """Create a new note; returns {id, note} and marks it selected."""
    session_uuid = request.state.session_uuid
    _require_notepad(session_uuid)
    if get_db().count_notes(session_uuid) >= _NOTE_MAX_COUNT:
        raise HTTPException(status_code=400, detail=f"Note limit reached ({_NOTE_MAX_COUNT})")
    try:
        body = await request.json()
    except Exception:
        body = {}
    content_json = body.get("content_json") if isinstance(body, dict) else None
    if isinstance(content_json, str) and len(content_json.encode("utf-8")) > _NOTE_MAX_BYTES:
        raise HTTPException(status_code=413, detail="Note too large")
    note_id = get_db().create_note(session_uuid, content_json if isinstance(content_json, str) else None)
    get_db().set_selected_note(session_uuid, note_id)
    return {"id": note_id, "note": get_db().get_note(session_uuid, note_id)}


@app.put("/api/notes/{note_id}")
async def notes_update(note_id: str, request: Request):
    """Autosave a note's content (re-derives title server-side)."""
    session_uuid = request.state.session_uuid
    _require_notepad(session_uuid)
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid JSON body")
    content_json = body.get("content_json") if isinstance(body, dict) else None
    if not isinstance(content_json, str):
        raise HTTPException(status_code=400, detail="content_json (string) required")
    if len(content_json.encode("utf-8")) > _NOTE_MAX_BYTES:
        raise HTTPException(status_code=413, detail="Note too large")
    if not get_db().update_note(session_uuid, note_id, content_json):
        raise HTTPException(status_code=404, detail="Note not found")
    return {"success": True, "title": get_db()._derive_note_title(content_json)}


@app.delete("/api/notes/{note_id}")
async def notes_delete(note_id: str, request: Request):
    """Delete a note (also clears it from remembered selection)."""
    session_uuid = request.state.session_uuid
    _require_notepad(session_uuid)
    if not get_db().delete_note(session_uuid, note_id):
        raise HTTPException(status_code=404, detail="Note not found")
    return {"success": True}


@app.put("/api/notes-selection")
async def notes_set_selection(request: Request):
    """Remember the selected note for this session (distinct path avoids /{note_id} clash)."""
    session_uuid = request.state.session_uuid
    _require_notepad(session_uuid)
    try:
        body = await request.json()
    except Exception:
        body = {}
    note_id = body.get("note_id") if isinstance(body, dict) else None
    get_db().set_selected_note(session_uuid, note_id if isinstance(note_id, str) else None)
    return {"success": True}


# ============================================================================
# WALKDLE (DAILY PUZZLE) ENDPOINTS
# ============================================================================

def _is_walkdle_testing_host(request) -> bool:
    """True when served from the testing site (walkscapetest.flamesandvoltiply.com).

    On testing, Walkdle is enabled for EVERY session; on prod it stays
    FAC-gated. Host is read from the forwarded/Host header (Caddy preserves it).
    """
    try:
        host = (request.headers.get('x-forwarded-host')
                or request.headers.get('host')
                or (request.url.hostname or ''))
        host = host.split(',')[0].strip().split(':')[0].lower()
        return host == 'walkscapetest.flamesandvoltiply.com'
    except Exception:
        return False


def _walkdle_enabled(request) -> bool:
    """Walkdle is now generally available — enabled for every session."""
    return True


def _require_walkdle(request):
    """Raise HTTPException(403) unless Walkdle is enabled for this request."""
    if not _walkdle_enabled(request):
        raise HTTPException(status_code=403, detail="Walkdle is not enabled for this session")


@app.get("/api/walkdle/catalog")
async def walkdle_catalog(request: Request):
    """Return the guessable item pool for Walkdle (FAC-gated).

    The browser engine seeds the daily target from this id-sorted pool and
    compares guesses attribute-by-attribute. Gated because it is only fetched
    when the (feature-enabled) overlay is opened.
    """
    session_uuid = request.state.session_uuid
    _require_walkdle(request)
    from ui.walkdle_catalog import build_walkdle_items, RARITY_ORDER, QUALITY_ORDER, WALKDLE_LAUNCH_DATE
    items = build_walkdle_items()
    # Attach each item's first-seen date so the engine can pin every day's
    # target to the items that existed then (adding items never reshuffles past
    # days). Best-effort: if this fails the engine falls back to the permutation.
    try:
        import datetime
        today = datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d')
        first_seen = get_db().sync_walkdle_first_seen([it['id'] for it in items], WALKDLE_LAUNCH_DATE, today)
        for it in items:
            it['first_seen'] = first_seen.get(it['id'], WALKDLE_LAUNCH_DATE)
    except Exception as e:
        logging.getLogger(__name__).warning(f"[walkdle] first_seen sync failed: {e}")
    return {"items": items, "rarity_order": RARITY_ORDER, "quality_order": QUALITY_ORDER, "pool_size": len(items)}


@app.get("/api/walkdle/history")
async def walkdle_history(request: Request, mode: str = "guess_item"):
    """Return per-date play results for the session (for the calendar)."""
    session_uuid = request.state.session_uuid
    _require_walkdle(request)
    rows = get_db().list_walkdle_attempts(session_uuid, mode)
    days = []

    def _resolve_mode(st):
        # easy: advanced filters used (or pre-feature attempt, no easy_mode key)
        # normal: not easy AND Show-stats assist used; hard: neither.
        if st.get("easy_mode") is not False:
            return "easy"
        if st.get("stats_used"):
            return "normal"
        return "hard"

    for r in rows:
        st = r.get("state") or {}
        days.append({
            "date": r["puzzle_date"],
            "solved": bool(st.get("solved")),
            "failed": bool(st.get("failed")),
            "guesses": len(st.get("guesses") or []),
            # Resolved difficulty drives the calendar star (gold hard / silver
            # normal / none easy). Only a solved day shows a star.
            "mode": _resolve_mode(st),
        })
    return {"mode": mode, "days": days}


@app.get("/api/walkdle/stats")
async def walkdle_stats(request: Request, date: str, mode: str = "guess_item"):
    """Aggregate guess-count distribution for a day (for the end-screen scoreboard)."""
    _require_walkdle(request)
    return get_db().walkdle_day_stats(date, mode)


@app.get("/api/walkdle/attempt")
async def walkdle_get_attempt(request: Request, date: str, mode: str = "guess_item"):
    """Return the saved attempt state for (session, date, mode), or empty state."""
    session_uuid = request.state.session_uuid
    _require_walkdle(request)
    saved = get_db().get_walkdle_attempt(session_uuid, date, mode)
    if not saved:
        return {"date": date, "mode": mode, "state": None}
    return {"date": date, "mode": mode, "state": saved["state"], "updated_at": saved["updated_at"]}


@app.post("/api/walkdle/attempt")
async def walkdle_save_attempt(request: Request):
    """Upsert the attempt state for (session, date, mode)."""
    session_uuid = request.state.session_uuid
    _require_walkdle(request)
    body = await request.json()
    date = (body.get("date") or "").strip()
    mode = (body.get("mode") or "guess_item").strip()
    state = body.get("state")
    if not date:
        raise HTTPException(status_code=400, detail="date required")
    if not isinstance(state, dict):
        raise HTTPException(status_code=400, detail="state must be an object")
    get_db().upsert_walkdle_attempt(session_uuid, date, mode, state)
    return {"success": True}


@app.get("/api/version")
async def get_version():
    """Get application version and git commit info."""
    import subprocess
    from pathlib import Path

    def _from_env():
        """Fall back to build-time env vars (set during docker build)."""
        commit_date = os.getenv("GIT_COMMIT_DATE", "")
        commit_hash = os.getenv("GIT_COMMIT_HASH", "")
        commit_relative = os.getenv("GIT_COMMIT_RELATIVE", "")
        if commit_date:
            return {
                "version": "1.0.0",
                "commit_date": commit_date,
                "commit_relative": commit_relative,
                "commit_hash": commit_hash,
                "last_updated": f"{commit_date} ({commit_relative})" if commit_relative else commit_date
            }
        return {"version": "1.0.0", "error": "Version info unavailable"}

    try:
        git_dir = Path(__file__).parent.parent

        # Allow git to access /app even if owned by a different user (Docker volume mount)
        subprocess.run(
            ['git', 'config', '--global', '--add', 'safe.directory', str(git_dir)],
            capture_output=True
        )

        result = subprocess.run(
            ['git', '-P', 'log', '-1', '--format=%ci'],
            cwd=git_dir, capture_output=True, text=True
        )
        if result.returncode != 0:
            raise Exception(f"Git command failed: {result.stderr}")
        commit_date = result.stdout.strip()

        result = subprocess.run(
            ['git', '-P', 'log', '-1', '--format=%cr'],
            cwd=git_dir, capture_output=True, text=True
        )
        commit_relative = result.stdout.strip()

        result = subprocess.run(
            ['git', '-P', 'log', '-1', '--format=%h'],
            cwd=git_dir, capture_output=True, text=True
        )
        commit_hash = result.stdout.strip()

        return {
            "version": "1.0.0",
            "commit_date": commit_date,
            "commit_relative": commit_relative,
            "commit_hash": commit_hash,
            "last_updated": f"{commit_date} ({commit_relative})"
        }
    except Exception as e:
        log(f"Git unavailable, falling back to build-time env vars: {e}")
        return _from_env()


