class TravelValidateRequest(BaseModel):
    """Request body for POST /api/travel-config/validate."""
    export_string: str     # Base64-gzip gearset export string
    route_ids: list        # list of route ID strings


@app.post("/api/travel-config/validate")
async def validate_travel_gearset(request: Request, data: TravelValidateRequest):
    """
    Validate a gearset against terrain requirements for a list of routes.

    Returns per-route validation results with specific missing requirement details.
    Also returns travel stats (WE, DA, steps_add, steps_percent) for the gearset.

    Requirements: 9.1, 9.2, 9.3, 9.4, 9.5
    """
    try:
        session_uuid = request.state.session_uuid
        session = get_db().get_session(session_uuid)
        character_config = session.get("character_config") if session else None

        from optimize_travel_gearsets import validate_gearset_for_routes, compute_travel_gearset_stats
        results = validate_gearset_for_routes(data.export_string, data.route_ids, character_config)
        stats = compute_travel_gearset_stats(data.export_string, data.route_ids, character_config)
        return {"success": True, "results": results, "stats": stats}
    except Exception as e:
        return {"success": False, "error": str(e), "results": {}}


class TravelOptimizeRequest(BaseModel):
    """Request body for POST /api/travel-config/optimize."""
    task_key: str          # e.g. "jarvonia:single", "trellin:1"
    region_id: str
    gearset_slot: str
    mode: str              # "single" | "long_short" | "multi" | "advanced"
    route_ids: list        # list of route ID strings
    breakpoint: Optional[float] = None
    multi_count: Optional[int] = None
    locked_slots: Optional[dict] = None
    from_location: Optional[str] = None  # For flipped cross-region routes
    to_location: Optional[str] = None    # For flipped cross-region routes


@app.post("/api/travel-config/optimize")
async def start_travel_optimization(
    request: Request,
    data: TravelOptimizeRequest,
    background_tasks: BackgroundTasks,
):
    """
    Start a background Optimization_Task for one RouteGearset.

    Returns 429 if a task with the same task_key is already running for this session.

    Requirements: 5.5, 5.10, 13.2
    """
    session_uuid = request.state.session_uuid
    session = get_db().get_session(session_uuid)

    character_config = session.get("character_config") if session else None
    ui_config = session.get("ui_config", {}) if session else {}
    if not character_config:
        # Allow UI overrides as fallback (mirrors existing optimize endpoint)
        ui_config = session.get("ui_config", {}) if session else {}
        user_overrides = ui_config.get("user_overrides", {})
        override_skills = user_overrides.get("skills", {})
        override_skills_xp = user_overrides.get("skills_xp", {})
        if not override_skills and not override_skills_xp:
            raise HTTPException(
                status_code=400,
                detail={
                    "error": True,
                    "code": "NO_CHARACTER",
                    "message": "No character data found. Please import your character or manually set skill levels.",
                },
            )
        owned_items = [
            item_id
            for item_id, state in user_overrides.get("items", {}).items()
            if state.get("has", False)
        ]
        character_config = {
            "name": "Manual Input",
            "game_version": "1.0",
            "steps": sum(override_skills_xp.values()),
            "achievement_points": user_overrides.get("achievement_points", 0),
            "coins": user_overrides.get("coins", 0),
            "skills": override_skills,
            "skills_xp": override_skills_xp,
            "reputation": user_overrides.get("reputation", {}),
            "owned_items": owned_items,
            "collectibles": [],
            "gear": {},
            "item_quantities": {},
            "item_qualities": {},
            "owned_quantities": {},
        }

    # Check for duplicate running task
    session_tasks = _travel_optimization_tasks.get(session_uuid, {})
    existing = session_tasks.get(data.task_key)
    if existing and existing.get("status") == "running":
        raise HTTPException(
            status_code=429,
            detail={
                "error": True,
                "code": "TASK_ALREADY_RUNNING",
                "message": f"Optimization task '{data.task_key}' is already running.",
            },
        )

    # Register task as running
    if session_uuid not in _travel_optimization_tasks:
        _travel_optimization_tasks[session_uuid] = {}
    _travel_optimization_tasks[session_uuid][data.task_key] = {
        "status": "running",
        "result": None,
        "error": None,
        "started_at": __import__("datetime").datetime.utcnow().isoformat(),
    }

    # When the request includes per-request locked_slots, honor them regardless
    # of the persisted lock_current_gear_slots toggle. Bug 0ca4acab: previously
    # locks were only respected if lock_current_gear_slots was already true,
    # which silently dropped per-slot locks set via the lock icon.
    # Mirrors /api/travel/optimize behavior.
    if data.locked_slots:
        ui_config = dict(ui_config) if ui_config else {}
        ui_config['lock_current_gear_slots'] = True
        ui_config['locked_slots_data'] = data.locked_slots

    background_tasks.add_task(
        _run_travel_optimization_background,
        session_uuid,
        data.task_key,
        data.region_id,
        data.gearset_slot,
        data.mode,
        data.route_ids,
        data.breakpoint,
        data.multi_count,
        character_config,
        ui_config,
        data.from_location,
        data.to_location,
    )

    log(f"Travel optimization started: {data.task_key}", session_uuid)
    return {"success": True, "task_key": data.task_key, "message": "Optimization started"}


@app.get("/api/travel-config/optimize-status")
async def get_travel_optimize_status(request: Request, keys: str = ""):
    """
    Poll for travel optimization task status.

    Accepts ?keys= as a comma-separated list of task keys.

    Requirements: 5.6, 5.7, 5.8, 5.11, 5.12
    """
    session_uuid = request.state.session_uuid
    session_tasks = _travel_optimization_tasks.get(session_uuid, {})

    requested_keys = [k.strip() for k in keys.split("|") if k.strip()] if keys else []

    tasks_out: Dict[str, Any] = {}
    for key in requested_keys:
        task = session_tasks.get(key)
        if task is None:
            tasks_out[key] = {"status": "not_found"}
        elif task["status"] == "running":
            tasks_out[key] = {"status": "running"}
        elif task["status"] == "complete":
            tasks_out[key] = {"status": "complete", **task["result"]}
        else:
            tasks_out[key] = {"status": "error", "error": task.get("error", "Unknown error")}

    return {"success": True, "tasks": tasks_out}


def _run_travel_optimization_background(
    session_uuid: str,
    task_key: str,
    region_id: str,
    gearset_slot: str,
    mode: str,
    route_ids: list,
    breakpoint_val: Optional[float],
    multi_count: Optional[int],
    character_config: dict,
    ui_config: dict,
    from_location: Optional[str] = None,
    to_location: Optional[str] = None,
):
    """
    Background worker for travel gearset optimization.

    Writes a temp JSON config, spawns ui.travel_optimize_worker as a subprocess,
    parses the result, and stores it in _travel_optimization_tasks.
    Also persists the result into the travel_config table so it survives restarts.
    """
    import sys
    import os
    import subprocess
    import tempfile
    from datetime import datetime

    try:
        with tempfile.NamedTemporaryFile(mode="w", suffix=".json", delete=False) as f:
            request_data = {
                "task_key": task_key,
                "region_id": region_id,
                "gearset_slot": gearset_slot,
                "mode": mode,
                "route_ids": route_ids,
                "breakpoint": breakpoint_val,
                "multi_count": multi_count,
                "character_config": character_config,
                "ui_config": ui_config,
                "from_location": from_location,
                "to_location": to_location,
            }
            json.dump(request_data, f)
            temp_file = f.name

        project_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        log(f"Starting travel optimization subprocess for {task_key}...", session_uuid)

        result = subprocess.run(
            [sys.executable, "-m", "ui.travel_optimize_worker", temp_file],
            cwd=project_root,
            capture_output=True,
            text=True,
            timeout=300,  # 5-minute timeout for multi-region optimization
        )

        try:
            os.unlink(temp_file)
        except Exception:
            pass

        if result.returncode != 0:
            # The worker prints a clean {"success": false, "error": str(e)} to
            # STDOUT on exception, while STDERR holds the diagnostic dump
            # followed by the full traceback at the very end. Prefer the
            # structured stdout error; otherwise use the TAIL of stderr (the
            # traceback lives at the end) — never the head, which is just the
            # diagnostic dump and hides the real cause.
            error_msg = None
            try:
                parsed_err = json.loads(result.stdout) if result.stdout else None
                if isinstance(parsed_err, dict) and parsed_err.get("error"):
                    error_msg = str(parsed_err["error"])
            except Exception:
                pass
            if not error_msg:
                raw = result.stderr or result.stdout or "Unknown error"
                error_msg = raw[-1000:]  # tail: traceback is at the end
            # Log the last lines of stderr so the traceback is captured server-side.
            if result.stderr:
                for line in result.stderr.strip().split("\n")[-40:]:
                    if line.strip():
                        log(f"  [travel-opt-err] {line.strip()}", session_uuid)
            log(f"❌ Travel optimization failed [{task_key}]: {error_msg[:1000]}", session_uuid)
            _travel_optimization_tasks.setdefault(session_uuid, {})[task_key] = {
                "status": "error",
                "result": None,
                "error": error_msg[:1000],
                "started_at": _travel_optimization_tasks.get(session_uuid, {}).get(task_key, {}).get("started_at"),
            }
            return

        try:
            response_data = json.loads(result.stdout)
        except json.JSONDecodeError as e:
            log(f"❌ Failed to parse travel optimization result [{task_key}]: {e}", session_uuid)
            _travel_optimization_tasks.setdefault(session_uuid, {})[task_key] = {
                "status": "error",
                "result": None,
                "error": f"JSON parse error: {e}",
                "started_at": _travel_optimization_tasks.get(session_uuid, {}).get(task_key, {}).get("started_at"),
            }
            return

        # Log subprocess debug output (print statements go to stderr)
        if result.stderr:
            for line in result.stderr.strip().split('\n'):
                if line.strip():
                    log(f"  [travel-opt] {line.strip()}", session_uuid)

        if not response_data.get("success"):
            err = response_data.get("error", "Unknown error")
            log(f"❌ Travel optimization error [{task_key}]: {err}", session_uuid)
            _travel_optimization_tasks.setdefault(session_uuid, {})[task_key] = {
                "status": "error",
                "result": None,
                "error": err,
                "started_at": _travel_optimization_tasks.get(session_uuid, {}).get(task_key, {}).get("started_at"),
            }
            return

        # Build the task result payload
        task_result = {
            "export_string": response_data.get("gearset_export"),
            "stats": response_data.get("stats", {}),
            "route_statuses": response_data.get("route_statuses", {}),
            "breakpoint": response_data.get("breakpoint"),
            "gearsets": response_data.get("gearsets"),  # for multi-mode
            "alternatives": response_data.get("alternatives"),  # for "Optimize Slot & Equip" popup
            "locked_alternatives": response_data.get("locked_alternatives"),  # for custom stats warning
        }

        _travel_optimization_tasks.setdefault(session_uuid, {})[task_key] = {
            "status": "complete",
            "result": task_result,
            "error": None,
            "started_at": _travel_optimization_tasks.get(session_uuid, {}).get(task_key, {}).get("started_at"),
        }

        # For simple A→B travel optimization, save result as a named gearset
        # so the frontend can use the same polling mechanism as the regular optimizer.
        if region_id == "simple" and task_result.get("export_string"):
            try:
                db = get_db()
                # Parse task_key: "simple:{start}:{end}" or "simple:{start}:{end}:{payload_hash}"
                # The popup-flow appends a payload_hash 4th segment when locked_slots
                # are present (see _travel_optimization_tasks task_key construction above).
                # Use >= 3 so both shapes produce the named gearset; the frontend's
                # _handleTravelOptimizationComplete name lookup expects "Travel: A → B".
                # Regression: bonez 7c9d53d2 (2026-05-16). Originally fixed 2026-05-14
                # (bugs d7c77316 / 0cec4bb8 / e9b367c5); regressed and re-fixed here.
                parts = task_key.split(":")
                if len(parts) >= 3:
                    start_id = parts[1].replace("_", " ").title()
                    end_id = parts[2].replace("_", " ").title()
                    gearset_name = f"Travel: {start_id} → {end_id}"
                else:
                    gearset_name = "Travel Optimized"

                # Decode the export string only to confirm it's well-formed.
                # We deliberately do NOT write per-slot {itemId, quality} data
                # into slots_json — see Bug df8f9b6b (Banbo). The frontend's
                # loadGearSetFromExport derives canonical slot objects from the
                # export_string by catalog UUID lookup, then merges extraSlots
                # (i.e. slots_json) on top as overrides. Writing minimal
                # {itemId: <UUID>, quality: <rarity>} blobs per slot caused
                # those overrides to clobber name/icon/stats, rendering as
                # "undefined" tiles in the gear preview. The export_string is
                # the source of truth for slot contents; slots_json now only
                # carries the meta keys (_alternatives, _locked_alternatives).
                import base64, gzip, json as _json
                raw = base64.b64decode(task_result["export_string"])
                _json.loads(gzip.decompress(raw).decode("utf-8"))  # validate
                slots_json = {}

                # Store locked alternatives so the frontend can show the
                # "you own X but it's locked behind custom stats" warning.
                if task_result.get("locked_alternatives") is not None:
                    slots_json["_locked_alternatives"] = task_result["locked_alternatives"]
                    total_locked = sum(len(v) for v in task_result["locked_alternatives"].values())
                    log(f"  Stored {total_locked} locked alternatives in travel gearset slots_json", session_uuid)
                else:
                    log(f"  No locked_alternatives in task_result (keys: {list(task_result.keys())})", session_uuid)

                # Store non-owned alternatives so the item-selection popup can surface
                # upgrade suggestions (drives the "Non-owned/Locked Upgrades" section).
                # Use `is not None` so empty dicts are preserved — this lets the client
                # distinguish "alternatives computed but none found" from "never computed".
                if task_result.get("alternatives") is not None:
                    slots_json["_alternatives"] = task_result["alternatives"]
                    total_alts = sum(len(v) for v in task_result["alternatives"].values())
                    log(f"  Stored {total_alts} non-owned alternatives in travel gearset slots_json", session_uuid)

                # Optimizer-chosen pet / consumable (Optimize-among-owned) ride in
                # slots_json so loadGearSet's extraSlots merge equips them —
                # encode_gearset does NOT carry pet/consumable slots.
                if isinstance(task_result.get("pet"), dict) and task_result["pet"].get("name"):
                    slots_json["pet"] = task_result["pet"]
                    log(f"  Stored optimized pet {task_result['pet'].get('name')} in slots_json", session_uuid)
                if isinstance(task_result.get("consumable"), dict) and task_result["consumable"].get("name"):
                    slots_json["consumable"] = task_result["consumable"]
                    log(f"  Stored optimized consumable {task_result['consumable'].get('name')} in slots_json", session_uuid)

                db.save_gear_set(
                    session_uuid=session_uuid,
                    name=gearset_name,
                    slots_json=slots_json,
                    is_optimized=True,
                    export_string=task_result["export_string"],
                )
                log(f"✓ Saved simple travel gearset: {gearset_name}", session_uuid)
            except Exception as save_err:
                log(f"⚠️  Failed to save simple travel gearset: {save_err}", session_uuid)

        # Persist result into travel_config so it survives server restarts
        try:
            db = get_db()
            config = db.get_travel_config(session_uuid) or _default_travel_config()
            region_cfg = config.get("regions", {}).get(region_id, {})
            gearsets = region_cfg.get("gearsets", {})
            # Merge with existing slot data to preserve frontend-set fields (color, name, etc.)
            existing = gearsets.get(gearset_slot, {})
            existing.update({
                "export_string": task_result["export_string"],
                "route_ids": route_ids,
                "stats": task_result["stats"],
            })
            # Only set name/color if not already set by frontend
            if not existing.get("name"):
                existing["name"] = f"{region_id.replace('_', ' ').title()} {gearset_slot}"
            gearsets[gearset_slot] = existing
            region_cfg["gearsets"] = gearsets
            if task_result.get("breakpoint") is not None:
                region_cfg["breakpoint"] = task_result["breakpoint"]
            config.setdefault("regions", {})[region_id] = region_cfg
            db.save_travel_config(session_uuid, config)
        except Exception as persist_err:
            log(f"⚠️  Failed to persist travel optimization result: {persist_err}", session_uuid)

        log(f"✓ Travel optimization complete: {task_key}", session_uuid)

    except subprocess.TimeoutExpired:
        log(f"Travel optimization timed out [{task_key}]", session_uuid)
        _travel_optimization_tasks.setdefault(session_uuid, {})[task_key] = {
            "status": "error",
            "result": None,
            "error": "Optimization timed out after 5 minutes.",
            "started_at": _travel_optimization_tasks.get(session_uuid, {}).get(task_key, {}).get("started_at"),
        }
    except Exception as e:
        import traceback
        log(f"Travel optimization background error [{task_key}]: {traceback.format_exc()}", session_uuid)
        _travel_optimization_tasks.setdefault(session_uuid, {})[task_key] = {
            "status": "error",
            "result": None,
            "error": str(e),
            "started_at": _travel_optimization_tasks.get(session_uuid, {}).get(task_key, {}).get("started_at"),
        }


# ============================================================================
# CRAFTING TREE CALCULATOR API
# ============================================================================

def _enrich_session_data_with_regions(session_data: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """Add region_unlocks and locked_locations to session_data for crafting tree spoiler protection."""
    if session_data is None:
        return None
    region_info = _compute_region_unlock(session_data)
    if "unlocked" in region_info:
        unlocked = region_info["unlocked"]
    else:
        unlocked = region_info
    valid_regions = {'jarvonia', 'trellin', 'erdwise', 'gdte',
                     'halfling_rebels', 'syrenthia',
                     'wallisia', 'wrentmark', 'ghostly', 'spectral'}
    # ghostly/spectral are the charter realm BEYOND Wraithwater. Wallisia
    # entry is now GDTE-based (Tendon Wet Fields + Wraithwater), so only treat
    # these sub-regions as unlocked with the Charter of the Drowned — not on
    # Wallisia entry alone.
    _charter_collectibles = {
        (c if isinstance(c, str) else (c.get('name') or c.get('id') or c.get('export_name') or ''))
        .lower().replace(' ', '_').replace("'", '')
        for c in ((session_data or {}).get('collectibles') or [])
    }
    if 'charter_of_the_drowned' in _charter_collectibles:
        unlocked = {**unlocked, 'ghostly': True, 'spectral': True}
    region_unlocks = [r for r, v in unlocked.items() if v and r in valid_regions]
    log(f"[crafting_tree] Region unlocks: {region_unlocks} (raw: {unlocked})")

    # Per-location locks (within otherwise-unlocked regions)
    locked_locations = set()
    try:
        from optimize_travel_gearsets import detect_locked_locations
        locked_locations = detect_locked_locations(session_data)
        log(f"[crafting_tree] Locked locations: {locked_locations}")
    except Exception as e:
        log(f"[crafting_tree] detect_locked_locations failed: {e}")
        import traceback
        traceback.print_exc()

    return {**session_data, "region_unlocks": region_unlocks, "locked_locations": list(locked_locations)}


# _auto_pick_input_items_for_activity moved to ui/crafting_tree_optimize.py
# (shared with the local Pyodide path); nothing else in app.py uses it.

@app.get("/api/crafting-tree/items")
async def crafting_tree_items():
    """Return list of craftable items (items that appear as recipe outputs)."""
    from ui.crafting_tree import get_craftable_items
    return {"items": get_craftable_items()}


@app.post("/api/crafting-tree/build")
async def crafting_tree_build(request: Request):
    """Build a default crafting tree for a target item.

    Request body: {item_id: str, session_uuid: str, spoiler_protection?: bool}
    Returns: {nodes: [...], global_settings: {...}}
    """
    body = await request.json()
    item_id = body.get("item_id")
    session_uuid = body.get("session_uuid")
    spoiler_protection = body.get("spoiler_protection", True)

    if not item_id:
        raise HTTPException(status_code=400, detail="item_id is required")

    # Validate session
    session_data = None
    if session_uuid:
        session = get_db().get_session(session_uuid)
        if not session:
            raise HTTPException(status_code=401, detail="Invalid or expired session")
        session_data = _enrich_session_data_with_regions(session.get("character_config"))

    from ui.crafting_tree import build_crafting_tree, _load_game_data
    game_data = _load_game_data()

    # Verify item exists as a recipe output
    from ui.crafting_tree import get_craftable_items
    craftable = get_craftable_items(game_data)
    valid_ids = {item["item_id"] for item in craftable}
    if item_id not in valid_ids:
        raise HTTPException(status_code=404, detail=f"Item '{item_id}' not found as a recipe output")

    nodes = build_crafting_tree(item_id, game_data, session_data, spoiler_protection)

    # Load saved settings from session, fall back to defaults
    saved_settings = {}
    if session_uuid and session:
        ui_config = session.get("ui_config") or {}
        ct_config = ui_config.get("crafting_tree") or {}
        saved_settings = ct_config.get("global_settings") or {}

    default_settings = {
        "target_quantity": saved_settings.get("target_quantity", 1),
        "daily_steps": saved_settings.get("daily_steps", 10000),
        "target_quality": saved_settings.get("target_quality", "Perfect"),
        "buffer_percentage": saved_settings.get("buffer_percentage", 0.05),
        "spoiler_protection": saved_settings.get("spoiler_protection", spoiler_protection),
    }

    return {"nodes": nodes, "global_settings": default_settings}


@app.post("/api/crafting-tree/calculate")
async def crafting_tree_calculate(request: Request):
    """Calculate metrics for a crafting tree.

    Request body: {nodes: [...], global_settings: {...}, session_uuid: str}
    Returns: {nodes: [...], summary: {...}}
    """
    body = await request.json()
    nodes = body.get("nodes", [])
    global_settings = body.get("global_settings", {})
    session_uuid = body.get("session_uuid")
    run_local = bool(body.get("run_local", False))  # client-side (Pyodide) compute

    if not nodes:
        # Empty tree (no goal selected yet) is a valid state — return
        # an empty result instead of 400. Frontend Calculate guards now
        # short-circuit on empty trees, but this defends against direct
        # API misuse and future frontend regressions. Bug 2940ca83.
        return {"nodes": [], "summary": None}

    # Validate session
    session_data = None
    if session_uuid:
        session = get_db().get_session(session_uuid)
        if not session:
            raise HTTPException(status_code=401, detail="Invalid or expired session")
        session_data = _enrich_session_data_with_regions(session.get("character_config"))
        # Inject the LP feature-flag decision so calculate_tree can run the LP.
        lp_enabled = get_db().has_feature(session_uuid, "crafting_tree_lp")
        if session_data is None:
            session_data = {}
        session_data['_lp_enabled'] = lp_enabled
        session_data.setdefault('uuid', session_uuid)

    # Client-side (Pyodide) path: return the enriched session_data so the
    # browser can run calculate_tree locally. FAC-gated.
    if run_local and session_uuid and get_db().has_feature(session_uuid, 'local_optimization'):
        return {"run_local": True, "session_data": session_data}

    from ui.crafting_tree import calculate_tree, _load_game_data
    game_data = _load_game_data()

    result = calculate_tree(nodes, global_settings, game_data, session_data)
    return result


@app.post("/api/crafting-tree/aggregate-summary")
async def crafting_tree_aggregate_summary(request: Request):
    """Re-aggregate the summary from the existing per-node metrics.

    Pure aggregation — does NOT re-run the per-node optimizer, the LP
    solver, or any node-level mutations. Result is deterministic for a
    fixed tree state. Used by the manual "Rerun Summary" button.

    Request body: {nodes: [...], global_settings: {...}, session_uuid: str}
    Returns: {nodes: [...], summary: {...}}  (same shape as
    /api/crafting-tree/calculate, but cheaper and stable)
    """
    body = await request.json()
    nodes = body.get("nodes", [])
    global_settings = body.get("global_settings", {})
    session_uuid = body.get("session_uuid")

    if not nodes:
        raise HTTPException(status_code=400, detail="nodes is required")

    session_data = None
    if session_uuid:
        session = get_db().get_session(session_uuid)
        if not session:
            raise HTTPException(status_code=401, detail="Invalid or expired session")
        session_data = _enrich_session_data_with_regions(session.get("character_config"))
        # Note: we deliberately do NOT inject _lp_enabled here. The
        # rerun-summary path ignores the LP solver regardless.
        if session_data is None:
            session_data = {}
        session_data.setdefault('uuid', session_uuid)

    from ui.crafting_tree import calculate_tree, _load_game_data
    game_data = _load_game_data()

    result = calculate_tree(
        nodes,
        global_settings,
        game_data,
        session_data,
        skip_recompute=True,
    )
    return result


