_crafting_tree_optimization_tasks: Dict[str, dict] = {}


@app.post("/api/crafting-tree/optimize")
async def crafting_tree_optimize(request: Request, background_tasks: BackgroundTasks):
    """Queue optimization for crafting tree nodes.

    Request body: {nodes: [...], global_settings: {...}, session_uuid: str,
                   node_ids?: [...], depth_optimize?: bool}
    Returns: {optimization_id: str}
    """
    body = await request.json()
    nodes = body.get("nodes", [])
    global_settings = body.get("global_settings", {})
    session_uuid = body.get("session_uuid")
    node_ids = body.get("node_ids")  # Optional: specific nodes to optimize
    depth_optimize = body.get("depth_optimize", False)
    run_local = bool(body.get("run_local", False))  # client-side (Pyodide) compute

    if not nodes:
        raise HTTPException(status_code=400, detail="nodes is required")

    session = None
    if session_uuid:
        session = get_db().get_session(session_uuid)
        if not session:
            raise HTTPException(status_code=401, detail="Invalid or expired session")

    import os
    optimization_id = os.urandom(8).hex()

    # Initialize task tracking
    _crafting_tree_optimization_tasks[session_uuid] = {
        "optimization_id": optimization_id,
        "status": "running",
        "completed_nodes": [],
        "pending": 0,
        "total": 0,
    }

    # Client-side (Pyodide) handshake: when the local_optimization FAC is on and
    # the client asked to run locally, DON'T schedule the server background
    # task. Return the session payload so the browser can run the SAME shared
    # core (ui.crafting_tree_optimize.optimize_crafting_tree) in-process and
    # POST results to /crafting-tree/optimize-local-result, which feeds the
    # existing optimize-status poll. The task dict (status=running) set above
    # lets the poll work immediately while the browser computes.
    if run_local and session_uuid and get_db().has_feature(session_uuid, 'local_optimization'):
        session_data = session.get("character_config") if session else None
        ui_config = session.get("ui_config", {}) if session else {}
        log("[crafting-tree/optimize] run_local — returning session payload to client", session_uuid)
        return {
            "run_local": True,
            "optimization_id": optimization_id,
            "session_data": session_data,
            "ui_config": ui_config,
        }

    # Run optimization in background (server path)
    background_tasks.add_task(
        _run_crafting_tree_optimization,
        session_uuid, nodes, global_settings, node_ids, depth_optimize
    )

    return {"optimization_id": optimization_id}


@app.get("/api/crafting-tree/optimize-status")
async def crafting_tree_optimize_status(request: Request):
    """Get optimization status for a session's crafting tree.

    Query params: session_uuid
    Returns: {status, completed_nodes: [...], pending: int}
    """
    session_uuid = request.query_params.get("session_uuid")
    if not session_uuid:
        raise HTTPException(status_code=400, detail="session_uuid is required")

    task = _crafting_tree_optimization_tasks.get(session_uuid)
    if not task:
        return {"status": "idle", "completed_nodes": [], "pending": 0}

    # Return a safe copy to avoid serialization issues
    try:
        resp = {
            "status": task.get("status", "unknown"),
            "completed_nodes": task.get("completed_nodes", []),
            "pending": task.get("pending", 0),
            "total": task.get("total", 0),
            "optimization_id": task.get("optimization_id", ""),
        }
        # Gear-aware Best(auto) route resolution can rebuild whole subtrees
        # (new node_ids), so a per-node merge isn't enough. When the run is
        # finished, hand the frontend the full updated tree to adopt. Only
        # sent on completion to keep in-progress polls lightweight.
        if task.get("status") == "complete" and task.get("final_nodes") is not None:
            resp["nodes"] = task.get("final_nodes")
        return resp
    except Exception as e:
        return {"status": "error", "completed_nodes": [], "pending": 0, "error": str(e)}


@app.post("/api/crafting-tree/optimize-local-result")
async def crafting_tree_optimize_local_result(request: Request):
    """Ingest results from a client-side (Pyodide) crafting-tree optimize run.

    The browser runs the shared core locally and POSTs a snapshot of the task
    state (completed_nodes / pending / total / final_nodes / status) here. We
    merge it into _crafting_tree_optimization_tasks so the existing
    /crafting-tree/optimize-status poll returns it to the frontend unchanged.

    Guarded so a late/stale local POST can't clobber a newer run: the
    optimization_id must match the currently-tracked task.
    """
    body = await request.json()
    session_uuid = body.get("session_uuid")
    optimization_id = body.get("optimization_id")
    if not session_uuid:
        raise HTTPException(status_code=400, detail="session_uuid is required")
    # Feature-gated, but return a benign 200 when off (this is only ever called
    # by the local driver, but never surface an error toast).
    if not get_db().has_feature(session_uuid, 'local_optimization'):
        return {"ok": False, "reason": "feature_off"}
    task = _crafting_tree_optimization_tasks.get(session_uuid)
    if not task or (optimization_id and task.get("optimization_id") != optimization_id):
        # No matching run (or a newer run replaced it) — ignore.
        return {"ok": False, "reason": "stale"}
    if body.get("completed_nodes") is not None:
        task["completed_nodes"] = body["completed_nodes"]
    if "pending" in body:
        task["pending"] = body["pending"]
    if "total" in body:
        task["total"] = body["total"]
    if body.get("final_nodes") is not None:
        task["final_nodes"] = body["final_nodes"]
    if body.get("status"):
        task["status"] = body["status"]
    return {"ok": True}


# ============================================================================
# SAVED CRAFTING TREES
# ============================================================================

@app.get("/api/crafting-tree/saved")
async def list_saved_crafting_trees(request: Request):
    """List saved crafting tree presets for the session."""
    session_uuid = request.query_params.get("session_uuid")
    if not session_uuid:
        raise HTTPException(status_code=400, detail="session_uuid required")
    return get_db().list_crafting_trees(session_uuid)


@app.post("/api/crafting-tree/saved")
async def save_crafting_tree(request: Request):
    """Save a crafting tree preset."""
    body = await request.json()
    session_uuid = body.get("session_uuid")
    name = body.get("name", "").strip()
    target_item_id = body.get("target_item_id", "")
    tree_data = body.get("tree_data", {})
    if not session_uuid or not name:
        raise HTTPException(status_code=400, detail="session_uuid and name required")
    tree_id = get_db().save_crafting_tree(session_uuid, name, target_item_id, tree_data)
    return {"id": tree_id, "name": name}


@app.get("/api/crafting-tree/saved/{tree_id}")
async def load_saved_crafting_tree(tree_id: str, request: Request):
    """Load a saved crafting tree preset."""
    session_uuid = request.query_params.get("session_uuid")
    if not session_uuid:
        raise HTTPException(status_code=400, detail="session_uuid required")
    result = get_db().load_crafting_tree(tree_id, session_uuid)
    if not result:
        raise HTTPException(status_code=404, detail="Saved tree not found")
    return result


@app.delete("/api/crafting-tree/saved/{tree_id}")
async def delete_saved_crafting_tree(tree_id: str, request: Request):
    """Delete a saved crafting tree preset."""
    session_uuid = request.query_params.get("session_uuid")
    if not session_uuid:
        raise HTTPException(status_code=400, detail="session_uuid required")
    deleted = get_db().delete_crafting_tree(tree_id, session_uuid)
    if not deleted:
        raise HTTPException(status_code=404, detail="Saved tree not found")
    return {"success": True}


def _run_crafting_tree_optimization(
    session_uuid: str,
    nodes: list,
    global_settings: dict,
    node_ids: list = None,
    depth_optimize: bool = False,
):
    """Background task: load the session, then delegate to the shared core
    (ui.crafting_tree_optimize.optimize_crafting_tree) with a subprocess
    node-executor. The per-node optimize logic is shared verbatim with the
    in-browser local (Pyodide) path so the two cannot drift."""
    import subprocess
    import tempfile
    import sys
    from ui.crafting_tree_optimize import optimize_crafting_tree

    session = get_db().get_session(session_uuid)
    session_data = session.get("character_config") if session else None
    ui_config = session.get("ui_config", {}) if session else {}
    task = _crafting_tree_optimization_tasks.get(session_uuid, {})
    project_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

    def _subprocess_node_executor(request_data):
        # Each node optimizes in a fresh subprocess (clean module state),
        # exactly as before. Returns the CompletedProcess so the core's
        # .returncode/.stdout/.stderr parsing is unchanged.
        with tempfile.NamedTemporaryFile(mode="w", suffix=".json", delete=False) as f:
            json.dump(request_data, f)
            temp_file = f.name
        cmd = [sys.executable, "-m", "ui.optimize_worker", temp_file]
        try:
            return subprocess.run(
                cmd,
                cwd=project_root,
                capture_output=True,
                text=True,
                timeout=120,
                env={**os.environ, "PYTHONPATH": project_root},
            )
        finally:
            try:
                os.unlink(temp_file)
            except Exception:
                pass

    optimize_crafting_tree(
        session_uuid, nodes, global_settings, session_data, ui_config, task,
        node_ids=node_ids, depth_optimize=depth_optimize,
        node_executor=_subprocess_node_executor, log=log,
    )
